TARGET_TEMPERATURE = 70
HEATING_THRESHOLD = 65
COOLING_THRESHOLD = 75
HEATER_COST_PER_DEGREE = 2
COOLER_COST_PER_DEGREE = 3


def validate_readings(temperature_readings):
    validated_readings = []
    for hour_index, raw_reading in enumerate(temperature_readings):
        if isinstance(raw_reading, bool) or not isinstance(raw_reading, (int, float)):
            raise TypeError(
                "reading for hour {} is not numeric: {!r}".format(hour_index, raw_reading)
            )
        validated_readings.append(float(raw_reading))
    return validated_readings


def heater_power_for(current_reading):
    if current_reading < HEATING_THRESHOLD:
        degree_difference = TARGET_TEMPERATURE - current_reading
        return HEATER_COST_PER_DEGREE * degree_difference
    return 0


def cooler_power_for(current_reading):
    if current_reading > COOLING_THRESHOLD:
        degree_difference = current_reading - TARGET_TEMPERATURE
        return COOLER_COST_PER_DEGREE * degree_difference
    return 0


def simulate(temperatures):
    hourly_readings = validate_readings(temperatures)
    total_heater_power = 0
    total_cooler_power = 0
    for current_reading in hourly_readings:
        total_heater_power += heater_power_for(current_reading)
        total_cooler_power += cooler_power_for(current_reading)
    return (total_heater_power, total_cooler_power)


def build_hourly_report(temperatures):
    report_lines = []
    for hour_index, current_reading in enumerate(validate_readings(temperatures)):
        heater_units = heater_power_for(current_reading)
        cooler_units = cooler_power_for(current_reading)
        if heater_units:
            active_device_label = "heater"
            power_used = heater_units
        elif cooler_units:
            active_device_label = "cooler"
            power_used = cooler_units
        else:
            active_device_label = "idle"
            power_used = 0
        report_lines.append(
            "hour {:>2}: {:>5.1f}F  {:<6} {:>5.1f} units".format(
                hour_index, current_reading, active_device_label, power_used
            )
        )
    return report_lines


def main():
    daily_readings = [60, 70, 80, 64.5, 75, 76, 58, 72]
    for single_line in build_hourly_report(daily_readings):
        print(single_line)
    heater_total, cooler_total = simulate(daily_readings)
    combined_power_total = heater_total + cooler_total
    print("heater total: {:.1f} units".format(heater_total))
    print("cooler total: {:.1f} units".format(cooler_total))
    print("combined total: {:.1f} units".format(combined_power_total))
    print(simulate([60, 70, 80]))


if __name__ == "__main__":
    main()

