SETUP_TIME_MINUTES = 45
ASSEMBLY_TIME_PER_ITEM = 12
INSPECTION_TIME_PER_ITEM = 3
MAINTENANCE_BREAK_MINUTES = 30
MAINTENANCE_ITEM_THRESHOLD = 50


def validate_order_list(order_list):
    if not isinstance(order_list, (list, tuple)):
        raise TypeError("orders must be a list or tuple of integers")
    validated_orders = []
    for batch_index, item_count in enumerate(order_list):
        if isinstance(item_count, bool) or not isinstance(item_count, int):
            raise TypeError(
                "batch %d must be an integer, got %r" % (batch_index, item_count)
            )
        if item_count < 0:
            raise ValueError("batch %d cannot hold a negative count" % batch_index)
        validated_orders.append(item_count)
    return validated_orders


def batch_processing_time(item_count):
    per_item_time = ASSEMBLY_TIME_PER_ITEM + INSPECTION_TIME_PER_ITEM
    total_batch_time = SETUP_TIME_MINUTES + item_count * per_item_time
    if item_count > MAINTENANCE_ITEM_THRESHOLD:
        total_batch_time += MAINTENANCE_BREAK_MINUTES
    return total_batch_time


def schedule(orders):
    validated_orders = validate_order_list(orders)
    total_time_minutes = 0
    for item_count in validated_orders:
        total_time_minutes += batch_processing_time(item_count)
    return total_time_minutes


def batch_time_breakdown(orders):
    validated_orders = validate_order_list(orders)
    breakdown_rows = []
    for batch_number, item_count in enumerate(validated_orders, start=1):
        batch_duration = batch_processing_time(item_count)
        needs_maintenance = item_count > MAINTENANCE_ITEM_THRESHOLD
        breakdown_rows.append((batch_number, item_count, batch_duration, needs_maintenance))
    return breakdown_rows


def format_duration(total_minutes):
    whole_hours = total_minutes // 60
    leftover_minutes = total_minutes % 60
    if whole_hours:
        return "%dh %02dm" % (whole_hours, leftover_minutes)
    return "%dm" % leftover_minutes


def build_schedule_report(orders):
    report_lines = ["Batch  Items  Minutes  Duration  Maintenance"]
    for batch_number, item_count, batch_duration, needs_maintenance in batch_time_breakdown(orders):
        maintenance_flag = "yes" if needs_maintenance else "no"
        report_lines.append(
            "%5d  %5d  %7d  %8s  %11s"
            % (batch_number, item_count, batch_duration, format_duration(batch_duration), maintenance_flag)
        )
    grand_total_minutes = schedule(orders)
    report_lines.append(
        "TOTAL         %7d  %8s" % (grand_total_minutes, format_duration(grand_total_minutes))
    )
    return "\n".join(report_lines)


def main():
    sample_orders = [10, 60]
    print(build_schedule_report(sample_orders))
    print("schedule(%r) = %d" % (sample_orders, schedule(sample_orders)))


if __name__ == "__main__":
    main()

