def validate_tracks(tracks):
    if not isinstance(tracks, list):
        raise TypeError("tracks must be a list of durations in seconds")
    validated_durations = []
    for position_index, raw_duration in enumerate(tracks):
        if isinstance(raw_duration, bool) or not isinstance(raw_duration, (int, float)):
            raise TypeError("track %d is not a numeric duration" % position_index)
        if raw_duration < 0:
            raise ValueError("track %d has a negative duration" % position_index)
        validated_durations.append(raw_duration)
    return validated_durations


LONG_TRACK_THRESHOLD = 300
CROSSFADE_SECONDS = 7
EXTENDED_FADE_BONUS = 3


def crossfade_savings(track_count):
    transition_count = max(track_count - 1, 0)
    return transition_count * CROSSFADE_SECONDS


def extended_fade_bonus(durations):
    last_index = len(durations) - 1
    bonus_total = 0
    for track_index, single_duration in enumerate(durations):
        if single_duration > LONG_TRACK_THRESHOLD and track_index != last_index:
            bonus_total += EXTENDED_FADE_BONUS
    return bonus_total


def playtime(tracks):
    track_durations = validate_tracks(tracks)
    raw_total_seconds = sum(track_durations)
    overlap_reduction = crossfade_savings(len(track_durations))
    fade_addition = extended_fade_bonus(track_durations)
    return raw_total_seconds + fade_addition - overlap_reduction


def format_duration(total_seconds):
    whole_seconds = int(round(total_seconds))
    minute_part = whole_seconds // 60
    second_part = whole_seconds % 60
    return "%d:%02d" % (minute_part, second_part)


def queue_report(queue_name, tracks):
    total_playtime = playtime(tracks)
    long_track_count = sum(1 for duration in tracks if duration > LONG_TRACK_THRESHOLD)
    report_lines = [
        "Queue: %s" % queue_name,
        "  tracks: %d (long tracks: %d)" % (len(tracks), long_track_count),
        "  raw duration: %s" % format_duration(sum(tracks)),
        "  crossfade savings: %d s" % crossfade_savings(len(tracks)),
        "  extended fade bonus: %d s" % extended_fade_bonus(tracks),
        "  final playtime: %d s (%s)" % (total_playtime, format_duration(total_playtime)),
    ]
    return "\n".join(report_lines)


def main():
    sample_queues = [
        ("Demo Pair", [200, 305]),
        ("Empty Queue", []),
        ("Single Long Track", [420]),
        ("Evening Mix", [180, 340, 275, 310, 199]),
    ]
    for queue_name, queue_tracks in sample_queues:
        print(queue_report(queue_name, queue_tracks))
        print()
    longest_queue_name, longest_queue_tracks = max(
        sample_queues, key=lambda entry: playtime(entry[1])
    )
    print("Longest queue: %s at %s" % (longest_queue_name, format_duration(playtime(longest_queue_tracks))))


if __name__ == "__main__":
    main()

