text_nat:
STANDARD_RATE_CENTS = 15
SURGE_RATE_CENTS = 5
PEAK_THRESHOLD_WATTS = 1000
DAILY_OPERATING_HOURS = 8


def validate_usage_values(usage):
    """Return the usage readings as floats, rejecting anything unusable."""
    if not isinstance(usage, (list, tuple)):
        raise TypeError("usage must be a list of power consumption values")
    validated_values = []
    for position_index, raw_value in enumerate(usage):
        if isinstance(raw_value, bool) or not isinstance(raw_value, (int, float)):
            raise TypeError("device %d has a non-numeric reading: %r" % (position_index, raw_value))
        if raw_value < 0:
            raise ValueError("device %d has a negative reading: %r" % (position_index, raw_value))
        validated_values.append(float(raw_value))
    return validated_values


def device_energy_kwh(power_watts):
    """Energy used by one device over a full day, in kilowatt hours."""
    return power_watts * DAILY_OPERATING_HOURS / 1000.0


def rate_for_device(power_watts):
    """Cents per kilowatt hour charged for a device at the given power draw."""
    applicable_rate = STANDARD_RATE_CENTS
    if power_watts > PEAK_THRESHOLD_WATTS:
        applicable_rate += SURGE_RATE_CENTS
    return applicable_rate


def device_cost_cents(power_watts):
    """Untruncated cost in cents for running one device for the day."""
    return device_energy_kwh(power_watts) * rate_for_device(power_watts)


def estimate(usage):
    """Total daily electricity cost in cents, rounded down to an integer."""
    device_readings = validate_usage_values(usage)
    accumulated_cost = 0.0
    for power_watts in device_readings:
        accumulated_cost += device_cost_cents(power_watts)
    return int(accumulated_cost)


def build_usage_report(usage):
    """Human readable per-device breakdown plus a total line."""
    device_readings = validate_usage_values(usage)
    report_lines = []
    surge_device_count = 0
    for device_number, power_watts in enumerate(device_readings, start=1):
        energy_amount = device_energy_kwh(power_watts)
        charged_rate = rate_for_device(power_watts)
        if charged_rate > STANDARD_RATE_CENTS:
            surge_device_count += 1
            rate_label = "%d c/kWh (peak surge)" % charged_rate
        else:
            rate_label = "%d c/kWh" % charged_rate
        report_lines.append(
            "device %d: %.0f W -> %.2f kWh at %s = %.2f c"
            % (device_number, power_watts, energy_amount, rate_label, device_cost_cents(power_watts))
        )
    total_cost_cents = estimate(device_readings)
    report_lines.append(
        "total: %d c for %d device(s), %d on peak surge"
        % (total_cost_cents, len(device_readings), surge_device_count)
    )
    return report_lines


def main():
    sample_installations = [[500, 1500], [1000, 1000.5, 0], [2400, 60, 750, 1200]]
    for installation_usage in sample_installations:
        for report_line in build_usage_report(installation_usage):
            print(report_line)
        print()


if __name__ == "__main__":
    main()

