STANDARD_RATE_CENTS = 15
SURGE_RATE_CENTS = 5
PEAK_THRESHOLD_WATTS = 1000
DAILY_OPERATING_HOURS = 8


def validateUsageValues(usage):
    """Return the usage readings as floats, rejecting anything unusable."""
    if not isinstance(usage, (list, tuple)):
        raise TypeError("usage must be a list of power consumption values")
    validatedValues = []
    for positionIndex, rawValue in enumerate(usage):
        if isinstance(rawValue, bool) or not isinstance(rawValue, (int, float)):
            raise TypeError("device %d has a non-numeric reading: %r" % (positionIndex, rawValue))
        if rawValue < 0:
            raise ValueError("device %d has a negative reading: %r" % (positionIndex, rawValue))
        validatedValues.append(float(rawValue))
    return validatedValues


def deviceEnergyKwh(powerWatts):
    """Energy used by one device over a full day, in kilowatt hours."""
    return powerWatts * DAILY_OPERATING_HOURS / 1000.0


def rateForDevice(powerWatts):
    """Cents per kilowatt hour charged for a device at the given power draw."""
    applicableRate = STANDARD_RATE_CENTS
    if powerWatts > PEAK_THRESHOLD_WATTS:
        applicableRate += SURGE_RATE_CENTS
    return applicableRate


def deviceCostCents(powerWatts):
    """Untruncated cost in cents for running one device for the day."""
    return deviceEnergyKwh(powerWatts) * rateForDevice(powerWatts)


def estimate(usage):
    """Total daily electricity cost in cents, rounded down to an integer."""
    deviceReadings = validateUsageValues(usage)
    accumulatedCost = 0.0
    for powerWatts in deviceReadings:
        accumulatedCost += deviceCostCents(powerWatts)
    return int(accumulatedCost)


def buildUsageReport(usage):
    """Human readable per-device breakdown plus a total line."""
    deviceReadings = validateUsageValues(usage)
    reportLines = []
    surgeDeviceCount = 0
    for deviceNumber, powerWatts in enumerate(deviceReadings, start=1):
        energyAmount = deviceEnergyKwh(powerWatts)
        chargedRate = rateForDevice(powerWatts)
        if chargedRate > STANDARD_RATE_CENTS:
            surgeDeviceCount += 1
            rateLabel = "%d c/kWh (peak surge)" % chargedRate
        else:
            rateLabel = "%d c/kWh" % chargedRate
        reportLines.append(
            "device %d: %.0f W -> %.2f kWh at %s = %.2f c"
            % (deviceNumber, powerWatts, energyAmount, rateLabel, deviceCostCents(powerWatts))
        )
    totalCostCents = estimate(deviceReadings)
    reportLines.append(
        "total: %d c for %d device(s), %d on peak surge"
        % (totalCostCents, len(deviceReadings), surgeDeviceCount)
    )
    return reportLines


def main():
    sampleInstallations = [[500, 1500], [1000, 1000.5, 0], [2400, 60, 750, 1200]]
    for installationUsage in sampleInstallations:
        for reportLine in buildUsageReport(installationUsage):
            print(reportLine)
        print()


if __name__ == "__main__":
    main()

