ERROR_THRESHOLD_METERS = 50000
EXHAUSTION_THRESHOLD_METERS = 10000
CALORIES_PER_METER = 2
EXHAUSTION_PENALTY_RATE = 0.2


def is_valid_movement(distance_in_meters):
    """A day's reading is usable only if it is a sane, non-negative distance."""
    if not isinstance(distance_in_meters, (int, float)):
        return False
    if distance_in_meters < 0:
        return False
    return distance_in_meters <= ERROR_THRESHOLD_METERS


def calories_for_day(distance_in_meters):
    """Calories burned on a single valid day, including the exhaustion penalty."""
    base_calorie_burn = distance_in_meters * CALORIES_PER_METER
    if distance_in_meters > EXHAUSTION_THRESHOLD_METERS:
        return base_calorie_burn * (1 + EXHAUSTION_PENALTY_RATE)
    return base_calorie_burn


def daily_breakdown(coordinates):
    """Pair each day's movement with the calories it produced, skipping errors."""
    breakdown_rows = []
    for day_index, distance_in_meters in enumerate(coordinates, start=1):
        if not is_valid_movement(distance_in_meters):
            continue
        breakdown_rows.append((day_index, distance_in_meters,
                               calories_for_day(distance_in_meters)))
    return breakdown_rows


def track(coordinates):
    """Total calories burned across every valid day of the trip."""
    total_calories_burned = 0
    for _, _, day_calorie_total in daily_breakdown(coordinates):
        total_calories_burned += day_calorie_total
    return total_calories_burned


def count_error_readings(coordinates):
    """How many days had to be thrown away as GPS malfunctions."""
    discarded_day_count = 0
    for distance_in_meters in coordinates:
        if not is_valid_movement(distance_in_meters):
            discarded_day_count += 1
    return discarded_day_count


def format_trip_report(coordinates):
    """Build a human readable summary of the tracked trip."""
    report_lines = []
    for day_index, distance_in_meters, day_calorie_total in daily_breakdown(coordinates):
        exhaustion_note = " (exhausted)" if distance_in_meters > EXHAUSTION_THRESHOLD_METERS else ""
        report_lines.append(
            "Day {0}: {1} m -> {2:.0f} cal{3}".format(
                day_index, distance_in_meters, day_calorie_total, exhaustion_note))
    discarded_day_count = count_error_readings(coordinates)
    if discarded_day_count:
        report_lines.append("Discarded readings: {0}".format(discarded_day_count))
    report_lines.append("Total calories burned: {0:.0f}".format(track(coordinates)))
    return "\n".join(report_lines)


