def validate_judge_scores(judge_scores, cake_index):
    if len(judge_scores) != 5:
        raise ValueError(
            "cake %d must have exactly 5 scores, got %d" % (cake_index, len(judge_scores))
        )
    for score_value in judge_scores:
        if not isinstance(score_value, int):
            raise TypeError("cake %d has a non-integer score: %r" % (cake_index, score_value))
        if score_value < 0 or score_value > 10:
            raise ValueError(
                "cake %d has an out-of-range score: %d" % (cake_index, score_value)
            )


def middle_three_scores(judge_scores):
    sorted_scores = sorted(judge_scores)
    return sorted_scores[1:4]


def final_cake_score(judge_scores):
    remaining_scores = middle_three_scores(judge_scores)
    base_total = sum(remaining_scores)
    if all(single_score == 10 for single_score in remaining_scores):
        return base_total + 5
    return base_total


def score(results):
    final_scores = []
    for cake_index, judge_scores in enumerate(results):
        validate_judge_scores(judge_scores, cake_index)
        final_scores.append(final_cake_score(judge_scores))
    return final_scores


def rank_cakes(final_scores):
    indexed_scores = [
        (cake_index, cake_score) for cake_index, cake_score in enumerate(final_scores)
    ]
    indexed_scores.sort(key=lambda scored_pair: (-scored_pair[1], scored_pair[0]))
    return indexed_scores


def format_scoreboard(results):
    final_scores = score(results)
    ranked_cakes = rank_cakes(final_scores)
    report_lines = []
    for rank_position, (cake_index, cake_score) in enumerate(ranked_cakes, start=1):
        dropped_scores = sorted(results[cake_index])
        lowest_score = dropped_scores[0]
        highest_score = dropped_scores[-1]
        bonus_marker = " +bonus" if cake_score > sum(middle_three_scores(results[cake_index])) - 1 and cake_score % 5 == 0 and cake_score == 35 else ""
        report_lines.append(
            "%d. cake #%d: %d (dropped %d and %d)%s"
            % (rank_position, cake_index + 1, cake_score, lowest_score, highest_score, bonus_marker)
        )
    return "\n".join(report_lines)


def main():
    contest_entries = [
        [5, 7, 8, 9, 10],
        [10, 10, 10, 10, 10],
        [8, 8, 9, 10, 10],
        [2, 3, 4, 5, 6],
    ]
    computed_scores = score(contest_entries)
    print("final scores:", computed_scores)
    print(format_scoreboard(contest_entries))
    winning_index, winning_score = rank_cakes(computed_scores)[0]
    print("winner: cake #%d with %d points" % (winning_index + 1, winning_score))


if __name__ == "__main__":
    main()

