ADULT_FARE = 25
CHILD_FARE = 12
SENIOR_FARE = 15
CHILD_AGE_LIMIT = 12
SENIOR_AGE_LIMIT = 65
GROUP_SIZE_THRESHOLD = 10
GROUP_DISCOUNT_AMOUNT = 2


def validate_ages(age_list):
    checked_ages = []
    for position_index, raw_age in enumerate(age_list):
        if not isinstance(raw_age, int) or isinstance(raw_age, bool):
            raise TypeError("age at position %d is not an integer: %r" % (position_index, raw_age))
        if raw_age < 0 or raw_age > 120:
            raise ValueError("age at position %d is out of range: %d" % (position_index, raw_age))
        checked_ages.append(raw_age)
    return checked_ages


def base_ticket_price(passenger_age):
    if passenger_age < CHILD_AGE_LIMIT:
        return CHILD_FARE
    if passenger_age >= SENIOR_AGE_LIMIT:
        return SENIOR_FARE
    return ADULT_FARE


def ticket_prices(age_list):
    passenger_count = len(age_list)
    discount_per_ticket = GROUP_DISCOUNT_AMOUNT if passenger_count > GROUP_SIZE_THRESHOLD else 0
    return [base_ticket_price(single_age) - discount_per_ticket for single_age in age_list]


def ferry(passengers):
    validated_ages = validate_ages(passengers)
    return sum(ticket_prices(validated_ages))


def fare_category(passenger_age):
    if passenger_age < CHILD_AGE_LIMIT:
        return "child"
    if passenger_age >= SENIOR_AGE_LIMIT:
        return "senior"
    return "adult"


def category_breakdown(age_list):
    count_by_category = {"child": 0, "adult": 0, "senior": 0}
    for single_age in age_list:
        count_by_category[fare_category(single_age)] += 1
    return count_by_category


def format_trip_report(passengers):
    validated_ages = validate_ages(passengers)
    price_list = ticket_prices(validated_ages)
    count_by_category = category_breakdown(validated_ages)
    total_revenue = sum(price_list)
    report_lines = ["Passengers: %d" % len(validated_ages)]
    for category_name in ("child", "adult", "senior"):
        report_lines.append("  %-6s x %d" % (category_name, count_by_category[category_name]))
    if len(validated_ages) > GROUP_SIZE_THRESHOLD:
        report_lines.append("  group discount: -%d per ticket" % GROUP_DISCOUNT_AMOUNT)
    report_lines.append("Ticket prices: %s" % ", ".join(str(single_price) for single_price in price_list))
    report_lines.append("Total revenue: %d dollars" % total_revenue)
    return "\n".join(report_lines)


def main():
    trip_manifests = [
        [10, 30, 70],
        [8, 11, 20, 33, 41, 45, 52, 64, 66, 70, 71],
        [],
    ]
    for trip_number, manifest_ages in enumerate(trip_manifests, start=1):
        print("Trip %d" % trip_number)
        print(format_trip_report(manifest_ages))
        print()
    grand_total = sum(ferry(manifest_ages) for manifest_ages in trip_manifests)
    print("Revenue for all trips: %d dollars" % grand_total)


if __name__ == "__main__":
    main()

