GALLONS_PER_POINT = 5
MAX_GALLONS_PER_ZONE = 100


def validate_zone(zone_index, zone_pair):
    """Check one zone entry and return its current and optimal percentages."""
    if len(zone_pair) != 2:
        raise ValueError("zone %d must have exactly two percentages" % zone_index)
    current_moisture, optimal_moisture = zone_pair
    for label, percentage_value in (("current", current_moisture), ("optimal", optimal_moisture)):
        if not isinstance(percentage_value, (int, float)) or isinstance(percentage_value, bool):
            raise TypeError("zone %d %s moisture must be numeric" % (zone_index, label))
        if percentage_value < 0 or percentage_value > 100:
            raise ValueError("zone %d %s moisture must be 0-100" % (zone_index, label))
    return current_moisture, optimal_moisture


def moisture_deficit(current_moisture, optimal_moisture):
    """Percentage points of moisture missing, never below zero."""
    raw_deficit = optimal_moisture - current_moisture
    if raw_deficit < 0:
        return 0
    return raw_deficit


def gallons_for_deficit(deficit_points):
    """Convert a deficit into gallons, capped to avoid flooding the zone."""
    requested_gallons = deficit_points * GALLONS_PER_POINT
    if requested_gallons > MAX_GALLONS_PER_ZONE:
        return MAX_GALLONS_PER_ZONE
    return requested_gallons


def water(zones):
    """Gallons of water to dispense for each (current, optimal) moisture zone."""
    gallons_per_zone = []
    for zone_index, zone_pair in enumerate(zones):
        current_moisture, optimal_moisture = validate_zone(zone_index, zone_pair)
        deficit_points = moisture_deficit(current_moisture, optimal_moisture)
        gallons_per_zone.append(gallons_for_deficit(deficit_points))
    return gallons_per_zone


def format_watering_report(zones, gallons_per_zone):
    """Build a human readable line per zone plus a summary line."""
    report_lines = []
    for zone_index, (zone_pair, zone_gallons) in enumerate(zip(zones, gallons_per_zone), start=1):
        current_moisture, optimal_moisture = zone_pair
        capped_note = " (capped)" if zone_gallons == MAX_GALLONS_PER_ZONE else ""
        report_lines.append(
            "Zone %d: %g%% -> %g%%, dispense %g gal%s"
            % (zone_index, current_moisture, optimal_moisture, zone_gallons, capped_note)
        )
    total_gallons = sum(gallons_per_zone)
    dry_zone_count = sum(1 for zone_gallons in gallons_per_zone if zone_gallons > 0)
    report_lines.append(
        "Total: %g gal across %d of %d zones" % (total_gallons, dry_zone_count, len(gallons_per_zone))
    )
    return "\n".join(report_lines)


def main():
    garden_zones = [(40, 60), (55, 60), (70, 65), (30, 48), (12.5, 20)]
    gallons_per_zone = water(garden_zones)
    print(gallons_per_zone)
    print(format_watering_report(garden_zones, gallons_per_zone))


if __name__ == "__main__":
    main()

