BASELINE_TEMPERATURE = 68
WATTS_PER_DEGREE = 50
CRITICAL_THRESHOLD = 85
EMERGENCY_MULTIPLIER = 1.5


def validate_readings(raw_readings):
    """Convert a list of raw rack readings into a list of numeric temperatures."""
    clean_readings = []
    for rack_index, raw_value in enumerate(raw_readings):
        if isinstance(raw_value, bool) or not isinstance(raw_value, (int, float)):
            raise TypeError(
                "rack %d has a non-numeric temperature: %r" % (rack_index, raw_value)
            )
        clean_readings.append(float(raw_value))
    return clean_readings


def rack_power(rack_temperature):
    """Watts needed to cool a single rack back down to the baseline."""
    degrees_over = rack_temperature - BASELINE_TEMPERATURE
    if degrees_over <= 0:
        return 0.0
    base_power = degrees_over * WATTS_PER_DEGREE
    if rack_temperature > CRITICAL_THRESHOLD:
        return base_power * EMERGENCY_MULTIPLIER
    return base_power


def cool(racks):
    """Total cooling watts required for every rack in the room."""
    rack_temperatures = validate_readings(racks)
    total_watts = 0.0
    for rack_temperature in rack_temperatures:
        total_watts += rack_power(rack_temperature)
    return total_watts


def count_rack_states(rack_temperatures):
    """Count how many racks are idle, actively cooled or in the critical zone."""
    idle_count = 0
    active_count = 0
    critical_count = 0
    for rack_temperature in rack_temperatures:
        if rack_temperature > CRITICAL_THRESHOLD:
            critical_count += 1
        elif rack_temperature > BASELINE_TEMPERATURE:
            active_count += 1
        else:
            idle_count += 1
    return idle_count, active_count, critical_count


def format_report(racks):
