        hottest_rack = max(rack_temperatures)
        report_lines.append("hottest reading      : %.1f F" % hottest_rack)
    report_lines.append("cooling power        : %.1f W" % cool(rack_temperatures))
    return "\n".join(report_lines)


def main():
