MAX_TAKEOFF_WEIGHT = 4000
EMPTY_HELICOPTER_WEIGHT = 2500


def available_capacity():
    return MAX_TAKEOFF_WEIGHT - EMPTY_HELICOPTER_WEIGHT


def validate_cargo(cargo):
    clean_weights = []
    for item_index, item_weight in enumerate(cargo):
        if not isinstance(item_weight, (int, float)) or isinstance(item_weight, bool):
            raise TypeError("cargo item %d is not a weight: %r" % (item_index, item_weight))
        if item_weight < 0:
            raise ValueError("cargo item %d has negative weight: %r" % (item_index, item_weight))
        clean_weights.append(item_weight)
    return clean_weights


def payload(cargo):
    weight_limit = available_capacity()
    item_weights = validate_cargo(cargo)
    loaded_weight = 0
    loaded_count = 0
    for current_weight in item_weights:
        if loaded_weight + current_weight > weight_limit:
            break
        loaded_weight += current_weight
        loaded_count += 1
    items_left_behind = len(item_weights) - loaded_count
    return (loaded_weight, items_left_behind)


def loading_report(cargo):
    total_loaded, left_behind = payload(cargo)
    weight_limit = available_capacity()
    remaining_capacity = weight_limit - total_loaded
    takeoff_weight = EMPTY_HELICOPTER_WEIGHT + total_loaded
    report_lines = [
        "cargo manifest: %s" % (list(cargo),),
        "loaded weight: %d lb of %d lb allowed" % (total_loaded, weight_limit),
        "spare capacity: %d lb" % remaining_capacity,
        "takeoff weight: %d lb" % takeoff_weight,
    ]
    if left_behind:
        report_lines.append("items left behind: %d" % left_behind)
    else:
        report_lines.append("entire manifest loaded")
    return "\n".join(report_lines)


def main():
    sample_manifests = [
        [500, 600, 800],
        [1500],
        [200, 200, 200, 200, 200, 200, 200, 200],
        [1600, 100, 100],
        [],
    ]
    for manifest_number, cargo_manifest in enumerate(sample_manifests, start=1):
        print("flight %d" % manifest_number)
        print(loading_report(cargo_manifest))
        print()

    bad_manifest = [300, -50, 400]
    try:
        payload(bad_manifest)
    except ValueError as validation_error:
        print("rejected manifest %s: %s" % (bad_manifest, validation_error))


if __name__ == "__main__":
    main()

