SEAT_CAPACITY = 50
SHOW_LENGTH_MINUTES = 40
CLEANING_LENGTH_MINUTES = 15


def validate_requests(requests):
    validated_groups = []
    for position_index, group_size in enumerate(requests):
        if not isinstance(group_size, int) or isinstance(group_size, bool):
            raise TypeError("group at index %d is not an integer" % position_index)
        if group_size <= 0:
            raise ValueError("group at index %d must be positive" % position_index)
        if group_size > SEAT_CAPACITY:
            raise ValueError(
                "group at index %d needs %d seats, capacity is %d"
                % (position_index, group_size, SEAT_CAPACITY)
            )
        validated_groups.append(group_size)
    return validated_groups


def group_into_shows(group_list):
    show_batches = []
    current_batch = []
    current_seat_usage = 0
    for group_size in group_list:
        if current_seat_usage + group_size > SEAT_CAPACITY:
            show_batches.append(current_batch)
            current_batch = []
            current_seat_usage = 0
        current_batch.append(group_size)
        current_seat_usage += group_size
    if current_batch:
        show_batches.append(current_batch)
    return show_batches


def total_running_time(show_count):
    if show_count == 0:
        return 0
    return show_count * SHOW_LENGTH_MINUTES + (show_count - 1) * CLEANING_LENGTH_MINUTES


def build_schedule_lines(show_batches):
    schedule_lines = []
    start_minute = 0
    for show_number, batch_groups in enumerate(show_batches, start=1):
        seats_taken = sum(batch_groups)
        end_minute = start_minute + SHOW_LENGTH_MINUTES
        schedule_lines.append(
            "show %d: %d-%d min, groups %s, %d/%d seats"
            % (show_number, start_minute, end_minute, batch_groups, seats_taken, SEAT_CAPACITY)
        )
        start_minute = end_minute + CLEANING_LENGTH_MINUTES
    return schedule_lines


def timetable(requests):
    validated_groups = validate_requests(requests)
    show_batches = group_into_shows(validated_groups)
    return total_running_time(len(show_batches))


def main():
    sample_request_sets = [[30, 25, 10], [50, 50, 50], [1], [], [20, 20, 20, 20, 20]]
    for request_list in sample_request_sets:
        elapsed_minutes = timetable(request_list)
        show_batches = group_into_shows(validate_requests(request_list))
        print("requests %s -> %d minutes" % (request_list, elapsed_minutes))
        for schedule_line in build_schedule_lines(show_batches):
            print("    " + schedule_line)


if __name__ == "__main__":
    main()

