BASE_TOLL_AMOUNT = 4
PER_EXTRA_AXLE_FEE = 2
HEAVY_TRANSPORT_AXLES = 18
HEAVY_TRANSPORT_FLAT_RATE = 40


def toll_for_vehicle(axle_count):
    if axle_count == HEAVY_TRANSPORT_AXLES:
        return HEAVY_TRANSPORT_FLAT_RATE
    extra_axles = max(0, axle_count - 2)
    return BASE_TOLL_AMOUNT + PER_EXTRA_AXLE_FEE * extra_axles


def validate_passes(passes):
    validated_list = []
    for position_index, axle_value in enumerate(passes):
        if isinstance(axle_value, bool) or not isinstance(axle_value, int):
            raise TypeError(
                "pass at index {} is not an integer: {!r}".format(position_index, axle_value)
            )
        if axle_value < 2:
            raise ValueError(
                "pass at index {} has too few axles: {}".format(position_index, axle_value)
            )
        validated_list.append(axle_value)
    return validated_list


def revenue(passes):
    validated_list = validate_passes(passes)
    total_revenue = 0
    for axle_count in validated_list:
        total_revenue += toll_for_vehicle(axle_count)
    return total_revenue


def summarize_passes(passes):
    validated_list = validate_passes(passes)
    axle_summary = {}
    for axle_count in validated_list:
        current_count, current_amount = axle_summary.get(axle_count, (0, 0))
        axle_summary[axle_count] = (
            current_count + 1,
            current_amount + toll_for_vehicle(axle_count),
        )
    return axle_summary


def format_report(passes):
    axle_summary = summarize_passes(passes)
    report_lines = ["axles  vehicles  collected"]
    for axle_count in sorted(axle_summary):
        vehicle_count, collected_amount = axle_summary[axle_count]
        report_lines.append(
            "{:>5}  {:>8}  {:>8}".format(axle_count, vehicle_count, "$" + str(collected_amount))
        )
    report_lines.append("total collected: ${}".format(revenue(passes)))
    return "\n".join(report_lines)


def main():
    daily_passes = [2, 4, 18, 2, 2, 5, 18, 3]
    print(format_report(daily_passes))
    busiest_axle_count = max(summarize_passes(daily_passes), key=lambda axles: axles)
    print("widest vehicle seen had {} axles".format(busiest_axle_count))
    try:
        revenue([2, 1])
    except ValueError as validation_error:
        print("rejected batch: {}".format(validation_error))


if __name__ == "__main__":
    main()

