    return parsed_values


def error_margin(measured_force, baseline_force=BASELINE_DRAG_FORCE):
    """Absolute difference between a measured force and the model prediction."""
    return abs(measured_force - baseline_force)


def is_stable_test(measured_force, margin_limit=MAX_ERROR_MARGIN):
    """A test is stable while its error margin stays within the limit."""
    return error_margin(measured_force) <= margin_limit


def split_tests_by_stability(tests):
    """Return the stable readings and the discarded readings separately."""
    stable_forces = []
    discarded_forces = []
    for measured_force in tests:
        if is_stable_test(measured_force):
            stable_forces.append(measured_force)
        else:
