    """Average of the measured forces whose error margin is acceptable."""
    stable_forces, _discarded = split_tests_by_stability(tests)
    if not stable_forces:
        return 0.0
    total_stable_force = sum(stable_forces)
    return total_stable_force / len(stable_forces)


