def validate_months(months_registered):
    """Return the membership duration as an int, rejecting invalid values."""
    if isinstance(months_registered, bool) or not isinstance(months_registered, int):
        raise TypeError("membership duration must be an integer number of months")
    if months_registered < 0:
        raise ValueError("membership duration cannot be negative")
    return months_registered


def member_fee(months_registered):
    """Renewal fee owed by a single member."""
    total_fee = BASE_RENEWAL_FEE
    if months_registered > LOYALTY_THRESHOLD_MONTHS:
        total_fee -= LOYALTY_DISCOUNT
    elif months_registered < NEW_MEMBER_THRESHOLD_MONTHS:
        total_fee += NEW_MEMBER_FEE
    return total_fee


def renewals(members):
    """Total renewal fees expected from every member in the list."""
    total_fees = 0
    for months_registered in members:
        total_fees += member_fee(validate_months(months_registered))
    return total_fees


