FUEL_RATE_PER_METER_PER_SECOND = 4
COOLANT_BLAST_THRESHOLD = 50
COOLANT_BLAST_PENALTY = 20


def validate_burn_list(burn_list):
    """Return the burn list as floats, rejecting non-numeric or negative entries."""
    validated_burns = []
    for burn_index, burn_value in enumerate(burn_list):
        if isinstance(burn_value, bool) or not isinstance(burn_value, (int, float)):
            raise TypeError(
                "burn %d is not a numeric velocity change: %r" % (burn_index, burn_value)
            )
        if burn_value < 0:
            raise ValueError(
                "burn %d has a negative velocity change: %r" % (burn_index, burn_value)
            )
        validated_burns.append(float(burn_value))
    return validated_burns


def needs_coolant_blast(velocity_change):
    return velocity_change > COOLANT_BLAST_THRESHOLD


def fuel_for_single_burn(velocity_change):
    burn_fuel_mass = velocity_change * FUEL_RATE_PER_METER_PER_SECOND
    if needs_coolant_blast(velocity_change):
        burn_fuel_mass += COOLANT_BLAST_PENALTY
    return burn_fuel_mass


def maneuver(burns):
    """Total fuel mass in kilograms consumed by the given sequence of burns."""
    checked_burns = validate_burn_list(burns)
    total_fuel_mass = 0.0
    for velocity_change in checked_burns:
        total_fuel_mass += fuel_for_single_burn(velocity_change)
    return total_fuel_mass


def burn_report_lines(burns):
    """Build one human readable line per burn plus a closing total line."""
    checked_burns = validate_burn_list(burns)
    report_lines = []
    for burn_number, velocity_change in enumerate(checked_burns, start=1):
        burn_fuel_mass = fuel_for_single_burn(velocity_change)
        coolant_note = " (coolant blast)" if needs_coolant_blast(velocity_change) else ""
        report_lines.append(
            "burn %d: %g m/s -> %g kg%s"
            % (burn_number, velocity_change, burn_fuel_mass, coolant_note)
        )
    report_lines.append("total fuel mass: %g kg" % maneuver(checked_burns))
    return report_lines


def main():
    mission_profiles = {
        "orbit insertion": [10, 60],
        "station rendezvous": [5, 12.5, 50, 50.5],
        "deorbit": [120],
    }
    grand_total_mass = 0.0
    for profile_name, burn_schedule in mission_profiles.items():
        print(profile_name)
        for report_line in burn_report_lines(burn_schedule):
            print("  " + report_line)
        grand_total_mass += maneuver(burn_schedule)
    print("all missions combined: %g kg" % grand_total_mass)


if __name__ == "__main__":
