import math


SPINE_GLUE_GRAMS_PER_BLOCK = 2
PAGES_PER_GLUE_BLOCK = 50
COVER_GLUE_GRAMS = 3
WASTE_FRACTION = 0.10


def validate_page_counts(page_count_list):
    validated_counts = []
    for list_position, raw_page_count in enumerate(page_count_list):
        if not isinstance(raw_page_count, (int, float)) or isinstance(raw_page_count, bool):
            raise TypeError("page count at index %d is not a number" % list_position)
        if raw_page_count < 0:
            raise ValueError("page count at index %d is negative" % list_position)
        validated_counts.append(raw_page_count)
    return validated_counts


def compute_spine_glue(page_count):
    glue_blocks_needed = page_count / PAGES_PER_GLUE_BLOCK
    return glue_blocks_needed * SPINE_GLUE_GRAMS_PER_BLOCK


def compute_book_glue(page_count):
    base_glue_amount = compute_spine_glue(page_count) + COVER_GLUE_GRAMS
    wasted_glue_amount = base_glue_amount * WASTE_FRACTION
    return base_glue_amount + wasted_glue_amount


def bind(books):
    validated_counts = validate_page_counts(books)
    total_glue_amount = 0.0
    for single_page_count in validated_counts:
        total_glue_amount += compute_book_glue(single_page_count)
    return math.floor(total_glue_amount)


def build_glue_breakdown(page_count_list):
    breakdown_rows = []
    for single_page_count in validate_page_counts(page_count_list):
        exact_glue_amount = compute_book_glue(single_page_count)
        breakdown_rows.append((single_page_count, exact_glue_amount))
    return breakdown_rows


def format_glue_report(page_count_list):
    report_lines = []
    breakdown_rows = build_glue_breakdown(page_count_list)
    for book_number, (single_page_count, exact_glue_amount) in enumerate(breakdown_rows, start=1):
        report_lines.append(
            "Book %d: %g pages -> %.2f g" % (book_number, single_page_count, exact_glue_amount)
        )
    required_total_glue = bind(page_count_list)
    report_lines.append("Total glue required: %d g" % required_total_glue)
    return "\n".join(report_lines)


def main():
