RING_TABLE = ((10, 10), (20, 5), (30, 2))
BULLSEYE_POINTS = 10
STREAK_LENGTH = 3
STREAK_BONUS = 15


def score_for_distance(distance_in_cm):
    """Return the points earned by a single shot at the given distance."""
    for ring_limit, ring_points in RING_TABLE:
        if distance_in_cm <= ring_limit:
            return ring_points
    return 0


def validate_shot_list(raw_shots):
    """Return the shots as a list of non-negative numbers, rejecting bad input."""
    validated_shots = []
    for shot_index, raw_distance in enumerate(raw_shots):
        if isinstance(raw_distance, bool) or not isinstance(raw_distance, (int, float)):
            raise TypeError(
                "shot %d is not a distance: %r" % (shot_index, raw_distance)
            )
        if raw_distance < 0:
            raise ValueError(
                "shot %d has a negative distance: %r" % (shot_index, raw_distance)
            )
        validated_shots.append(raw_distance)
    return validated_shots


def archery(shots):
    """Total the archer's score, including bullseye streak bonuses."""
    shot_distances = validate_shot_list(shots)
    total_score = 0
    current_streak = 0
    for distance_in_cm in shot_distances:
        shot_points = score_for_distance(distance_in_cm)
        total_score += shot_points
        if shot_points == BULLSEYE_POINTS:
            current_streak += 1
            if current_streak == STREAK_LENGTH:
                total_score += STREAK_BONUS
                current_streak = 0
        else:
            current_streak = 0
    return total_score


def count_bullseye_streaks(shots):
    """Return how many complete bullseye streaks the archer achieved."""
    streak_count = 0
    running_streak = 0
    for distance_in_cm in validate_shot_list(shots):
        if score_for_distance(distance_in_cm) == BULLSEYE_POINTS:
            running_streak += 1
            if running_streak == STREAK_LENGTH:
                streak_count += 1
                running_streak = 0
        else:
            running_streak = 0
    return streak_count


def format_score_report(archer_name, shots):
    """Build a one-line summary of an archer's round."""
    shot_distances = validate_shot_list(shots)
    missed_shots = sum(1 for distance in shot_distances if score_for_distance(distance) == 0)
    final_score = archery(shot_distances)
    bonus_count = count_bullseye_streaks(shot_distances)
    return "%-8s %3d points | %d shots | %d misses | %d streak bonus" % (
        archer_name,
        final_score,
        len(shot_distances),
        missed_shots,
        bonus_count,
    )


def main():
    round_results = [
        ("Robin", [5, 8, 9, 25]),
        ("Marian", [0, 3, 7, 10, 2, 4, 45]),
        ("Tuck", [31, 40, 22, 18]),
    ]
    for archer_name, shot_distances in round_results:
        print(format_score_report(archer_name, shot_distances))
    best_archer, best_shots = max(round_results, key=lambda entry: archery(entry[1]))
    print("Winner: %s with %d points" % (best_archer, archery(best_shots)))


if __name__ == "__main__":
    main()

