    """Total the archer's score, including bullseye streak bonuses."""
    shotDistances = validateShotList(shots)
    totalScore = 0
    currentStreak = 0
    for distanceInCm in shotDistances:
        shotPoints = scoreForDistance(distanceInCm)
        totalScore += shotPoints
        if shotPoints == BULLSEYE_POINTS:
            currentStreak += 1
            if currentStreak == STREAK_LENGTH:
                totalScore += STREAK_BONUS
                currentStreak = 0
        else:
            currentStreak = 0
    return totalScore


def countBullseyeStreaks(shots):
    """Return how many complete bullseye streaks the archer achieved."""
    streakCount = 0
    runningStreak = 0
    for distanceInCm in validateShotList(shots):
        if scoreForDistance(distanceInCm) == BULLSEYE_POINTS:
            runningStreak += 1
            if runningStreak == STREAK_LENGTH:
                streakCount += 1
                runningStreak = 0
        else:
            runningStreak = 0
    return streakCount


def formatScoreReport(archerName, shots):
    """Build a one-line summary of an archer's round."""
    shotDistances = validateShotList(shots)
    missedShots = sum(1 for distance in shotDistances if scoreForDistance(distance) == 0)
    finalScore = archery(shotDistances)
    bonusCount = countBullseyeStreaks(shotDistances)
    return "%-8s %3d points | %d shots | %d misses | %d streak bonus" % (
        archerName,
        finalScore,
        len(shotDistances),
        missedShots,
        bonusCount,
    )


def main():
    roundResults = [
        ("Robin", [5, 8, 9, 25]),
        ("Marian", [0, 3, 7, 10, 2, 4, 45]),
        ("Tuck", [31, 40, 22, 18]),
    ]
    for archerName, shotDistances in roundResults:
        print(formatScoreReport(archerName, shotDistances))
    bestArcher, bestShots = max(roundResults, key=lambda entry: archery(entry[1]))
    print("Winner: %s with %d points" % (bestArcher, archery(bestShots)))


if __name__ == "__main__":
    main()

