def validate_cart(cart_entry, cart_index):
    if len(cart_entry) != 2:
        raise ValueError("cart %d must hold a weight and a purity" % cart_index)
    raw_weight, purity_percentage = cart_entry
    if raw_weight < 0:
        raise ValueError("cart %d has a negative raw weight" % cart_index)
    if not 0.0 <= purity_percentage <= 1.0:
        raise ValueError("cart %d has a purity outside 0..1" % cart_index)
    return float(raw_weight), float(purity_percentage)


def compute_refined_weight(raw_weight, purity_percentage):
