import math


def handicap_factor(boat_length):
    """Return the handicap factor for a boat of the given length in feet."""
    return math.sqrt(boat_length) * 0.5


def adjusted_time(boat_length, unadjusted_time):
    """Subtract the boat's handicap factor from its unadjusted race time."""
    return unadjusted_time - handicap_factor(boat_length)


def validate_entry(entry):
    """Check one (length, time) tuple and return it as floats."""
    if len(entry) != 2:
        raise ValueError("each boat needs a length and a time, got: %r" % (entry,))
    boat_length, unadjusted_time = entry
    if boat_length <= 0:
        raise ValueError("boat length must be positive, got: %r" % (boat_length,))
    if unadjusted_time < 0:
        raise ValueError("race time cannot be negative, got: %r" % (unadjusted_time,))
    return float(boat_length), float(unadjusted_time)


def handicap(boats):
    """Return the lowest adjusted race time among all boats."""
    if not boats:
        raise ValueError("at least one boat is required")
    best_time = None
    for entry in boats:
        boat_length, unadjusted_time = validate_entry(entry)
        candidate_time = adjusted_time(boat_length, unadjusted_time)
        if best_time is None or candidate_time < best_time:
            best_time = candidate_time
    return best_time


def build_result_table(boats):
    """Return rows of (length, raw time, factor, adjusted time) sorted by result."""
    result_rows = []
    for entry in boats:
        boat_length, unadjusted_time = validate_entry(entry)
        result_rows.append((
            boat_length,
            unadjusted_time,
            handicap_factor(boat_length),
            adjusted_time(boat_length, unadjusted_time),
        ))
    result_rows.sort(key=lambda row: row[3])
    return result_rows


def format_result_table(boats):
    """Render the race standings as a printable, line-oriented report."""
    report_lines = ["rank  length   raw     factor  adjusted"]
    for rank_position, row in enumerate(build_result_table(boats), start=1):
        boat_length, unadjusted_time, factor_value, final_time = row
        report_lines.append(
            "%4d  %6.1f  %6.2f  %6.3f  %8.3f"
            % (rank_position, boat_length, unadjusted_time, factor_value, final_time)
        )
    winning_time = handicap(boats)
    report_lines.append("winning adjusted time: %.3f" % winning_time)
    return "\n".join(report_lines)


def main():
    single_boat_race = [(36, 60)]
    print(handicap(single_boat_race))

    club_race_entries = [(25, 58.5), (36, 60), (49, 61.2), (16, 55.0)]
    print(format_result_table(club_race_entries))

    for bad_entries in ([], [(0, 10)], [(30, 40, 50)]):
        try:
            handicap(bad_entries)
        except ValueError as validation_error:
            print("rejected: %s" % validation_error)


if __name__ == "__main__":
    main()

