MINIMUM_HARVEST_HEIGHT = 10.0
KNOTTY_BASE_LENGTH = 5.0
VOLUME_PER_METER = 0.8


def validate_tree_heights(raw_heights):
    """Convert the incoming heights to floats, rejecting invalid entries."""
    clean_heights = []
    for entry_index, raw_height in enumerate(raw_heights):
        if isinstance(raw_height, bool) or not isinstance(raw_height, (int, float)):
            raise TypeError("tree height at position %d is not a number: %r" % (entry_index, raw_height))
        height_value = float(raw_height)
        if height_value < 0:
            raise ValueError("tree height at position %d is negative: %r" % (entry_index, raw_height))
        clean_heights.append(height_value)
    return clean_heights


def is_harvestable(tree_height):
    return tree_height >= MINIMUM_HARVEST_HEIGHT


def trunk_volume(tree_height):
    """Usable timber volume of a single trunk, ignoring the knotty base."""
    usable_length = tree_height - KNOTTY_BASE_LENGTH
    return usable_length * VOLUME_PER_METER


def timber(trees):
    """Usable timber volumes for every tree tall enough to be harvested."""
    tree_heights = validate_tree_heights(trees)
    harvested_volumes = []
    for tree_height in tree_heights:
        if is_harvestable(tree_height):
            harvested_volumes.append(trunk_volume(tree_height))
    return harvested_volumes


def summarize_harvest(trees):
    """Group the stand into skipped saplings and harvested trunks."""
    tree_heights = validate_tree_heights(trees)
    skipped_heights = [height for height in tree_heights if not is_harvestable(height)]
    harvested_volumes = timber(tree_heights)
    total_volume = sum(harvested_volumes)
    return {
        "harvested_count": len(harvested_volumes),
        "skipped_count": len(skipped_heights),
        "skippedHeights": skipped_heights,
        "harvestedVolumes": harvested_volumes,
        "totalVolume": total_volume,
    }


def format_harvest_report(trees):
    harvest_summary = summarize_harvest(trees)
    report_lines = ["Stand of %d tree(s)" % (harvest_summary["harvested_count"] + harvest_summary["skipped_count"])]
    for volume_value in harvest_summary["harvestedVolumes"]:
        report_lines.append("  harvested: %.1f m3" % volume_value)
    for sapling_height in harvest_summary["skippedHeights"]:
        report_lines.append("  too young: %.1f m tall" % sapling_height)
    report_lines.append("Total usable timber: %.1f m3" % harvest_summary["totalVolume"])
    return "\n".join(report_lines)


