text_nat:
FAST_PASS_PENALTY = 0.20
MINUTES_PER_HOUR = 60


def validate_ride(ride_entry, ride_index):
    if not isinstance(ride_entry, (tuple, list)) or len(ride_entry) != 2:
        raise ValueError("ride %d must be a pair of queue length and hourly capacity" % ride_index)
    people_in_line, hourly_capacity = ride_entry
    if not isinstance(people_in_line, (int, float)) or not isinstance(hourly_capacity, (int, float)):
        raise TypeError("ride %d must contain numeric values" % ride_index)
    if people_in_line < 0:
        raise ValueError("ride %d cannot have a negative queue length" % ride_index)
    if hourly_capacity <= 0:
        raise ValueError("ride %d must have a positive hourly capacity" % ride_index)
    return people_in_line, hourly_capacity


def estimate_single_wait(people_in_line, hourly_capacity):
    base_minutes = (people_in_line / hourly_capacity) * MINUTES_PER_HOUR
    penalised_minutes = base_minutes * (1 + FAST_PASS_PENALTY)
    return round(penalised_minutes)


def wait(rides):
    wait_times = []
    for ride_index, ride_entry in enumerate(rides):
        people_in_line, hourly_capacity = validate_ride(ride_entry, ride_index)
        wait_times.append(estimate_single_wait(people_in_line, hourly_capacity))
    return wait_times


def build_wait_report(ride_names, wait_times):
    report_lines = []
    for ride_name, minutes_waited in zip(ride_names, wait_times):
        report_lines.append("%-22s %4d min" % (ride_name, minutes_waited))
    return report_lines


def find_shortest_ride(ride_names, wait_times):
    best_name = ride_names[0]
    lowest_wait = wait_times[0]
    for ride_name, minutes_waited in zip(ride_names[1:], wait_times[1:]):
        if minutes_waited < lowest_wait:
            lowest_wait = minutes_waited
            best_name = ride_name
    return best_name, lowest_wait


def average_wait(wait_times):
    total_minutes = sum(wait_times)
    return total_minutes / len(wait_times)


def main():
    ride_names = ["Looping Coaster", "River Rapids", "Haunted Mansion", "Sky Tower"]
    ride_queues = [(100, 300), (450, 600), (240, 900), (60, 240)]
    wait_times = wait(ride_queues)
    for report_line in build_wait_report(ride_names, wait_times):
        print(report_line)
    shortest_name, shortest_wait = find_shortest_ride(ride_names, wait_times)
    print("Shortest line: %s at %d min" % (shortest_name, shortest_wait))
    print("Park average: %.1f min" % average_wait(wait_times))


if __name__ == "__main__":
    main()

