def validateRide(rideEntry, rideIndex):
    if not isinstance(rideEntry, (tuple, list)) or len(rideEntry) != 2:
        raise ValueError("ride %d must be a pair of queue length and hourly capacity" % rideIndex)
    peopleInLine, hourlyCapacity = rideEntry
    if not isinstance(peopleInLine, (int, float)) or not isinstance(hourlyCapacity, (int, float)):
        raise TypeError("ride %d must contain numeric values" % rideIndex)
    if peopleInLine < 0:
        raise ValueError("ride %d cannot have a negative queue length" % rideIndex)
    if hourlyCapacity <= 0:
        raise ValueError("ride %d must have a positive hourly capacity" % rideIndex)
    return peopleInLine, hourlyCapacity


def estimateSingleWait(peopleInLine, hourlyCapacity):
    baseMinutes = (peopleInLine / hourlyCapacity) * MINUTES_PER_HOUR
    penalisedMinutes = baseMinutes * (1 + FAST_PASS_PENALTY)
    return round(penalisedMinutes)


def wait(rides):
    waitTimes = []
    for rideIndex, rideEntry in enumerate(rides):
        peopleInLine, hourlyCapacity = validateRide(rideEntry, rideIndex)
        waitTimes.append(estimateSingleWait(peopleInLine, hourlyCapacity))
    return waitTimes


def buildWaitReport(rideNames, waitTimes):
    reportLines = []
    for rideName, minutesWaited in zip(rideNames, waitTimes):
        reportLines.append("%-22s %4d min" % (rideName, minutesWaited))
    return reportLines


def findShortestRide(rideNames, waitTimes):
    bestName = rideNames[0]
    lowestWait = waitTimes[0]
    for rideName, minutesWaited in zip(rideNames[1:], waitTimes[1:]):
        if minutesWaited < lowestWait:
            lowestWait = minutesWaited
            bestName = rideName
    return bestName, lowestWait


def averageWait(waitTimes):
    totalMinutes = sum(waitTimes)
    return totalMinutes / len(waitTimes)


def main():
    rideNames = ["Looping Coaster", "River Rapids", "Haunted Mansion", "Sky Tower"]
    rideQueues = [(100, 300), (450, 600), (240, 900), (60, 240)]
    waitTimes = wait(rideQueues)
    for reportLine in buildWaitReport(rideNames, waitTimes):
        print(reportLine)
    shortestName, shortestWait = findShortestRide(rideNames, waitTimes)
    print("Shortest line: %s at %d min" % (shortestName, shortestWait))
    print("Park average: %.1f min" % averageWait(waitTimes))


if __name__ == "__main__":
    main()

