def meets_age_requirement(donor_age):
    return MIN_AGE_ALLOWED <= donor_age < MAX_AGE_ALLOWED


def meets_weight_requirement(donor_weight_kg):
    return donor_weight_kg >= MIN_WEIGHT_KG


def meets_rest_requirement(days_since_donation):
    return days_since_donation >= MIN_REST_DAYS


def collect_failure_reasons(donor_record):
    donor_id, donor_age, donor_weight_kg, days_since_donation = donor_record
    failure_reasons = []
    if not meets_age_requirement(donor_age):
        failure_reasons.append("age %d outside %d-%d" % (donor_age, MIN_AGE_ALLOWED, MAX_AGE_ALLOWED - 1))
    if not meets_weight_requirement(donor_weight_kg):
        failure_reasons.append("weight %d kg below %d kg" % (donor_weight_kg, MIN_WEIGHT_KG))
    if not meets_rest_requirement(days_since_donation):
        failure_reasons.append("only %d days since last donation" % days_since_donation)
    return failure_reasons


def screen(donors):
    accepted_identifiers = []
    for donor_record in donors:
        if not collect_failure_reasons(donor_record):
            accepted_identifiers.append(donor_record[0])
