    validated_records = []
    for record_index, donor_record in enumerate(donors):
        if len(donor_record) != 4:
            raise ValueError("record %d must have 4 fields" % record_index)
        donor_id, donor_age, donor_weight_kg, days_since_donation = donor_record
        for numeric_field in (donor_age, donor_weight_kg, days_since_donation):
            if not isinstance(numeric_field, (int, float)) or numeric_field < 0:
                raise ValueError("record %r has an invalid measurement" % (donor_id,))
        validated_records.append((str(donor_id), donor_age, donor_weight_kg, days_since_donation))
    return validated_records


def build_screening_report(donors):
    report_lines = []
    for donor_record in donors:
        failure_reasons = collect_failure_reasons(donor_record)
        if failure_reasons:
            report_lines.append("%s: DEFERRED (%s)" % (donor_record[0], "; ".join(failure_reasons)))
        else:
            report_lines.append("%s: ACCEPTED" % donor_record[0])
    return report_lines


