    permit_fee, fuel_cost = costs
    return permit_fee + fuel_cost


def validate_locations(locations):
    if not locations:
        raise ValueError("at least one candidate location is required")
    for candidate_spot in locations:
        if len(candidate_spot) != 3:
            raise ValueError("each location needs an id, foot traffic and average spend")
        location_id, foot_traffic, average_spend = candidate_spot
        if foot_traffic < 0 or average_spend < 0:
            raise ValueError("negative figures are invalid for " + str(location_id))


def build_profit_report(locations, costs):
    validate_locations(locations)
    daily_expenses = compute_daily_expenses(costs)
    profit_report = []
    for location_id, foot_traffic, average_spend in locations:
        gross_revenue = compute_gross_revenue(foot_traffic, average_spend)
        net_profit = gross_revenue - daily_expenses
        profit_report.append((location_id, gross_revenue, net_profit))
    return profit_report


def evaluate(locations, costs):
    profit_report = build_profit_report(locations, costs)
    best_location_id = None
    max_net_profit = None
    for location_id, gross_revenue, net_profit in profit_report:
        if max_net_profit is None or net_profit > max_net_profit:
            max_net_profit = net_profit
            best_location_id = location_id
    return best_location_id


