SECONDS_PER_PERCENT = 5
SEVERE_DEFICIT_THRESHOLD = 20
SEVERE_DRYNESS_PENALTY = 30


def compute_spray_duration(current_percentage, target_percentage):
    humidity_deficit = target_percentage - current_percentage
    if humidity_deficit <= 0:
        return 0
    base_duration = humidity_deficit * SECONDS_PER_PERCENT
    if humidity_deficit > SEVERE_DEFICIT_THRESHOLD:
        return base_duration + SEVERE_DRYNESS_PENALTY
    return base_duration


def regulate(readings):
    spray_schedule = []
    for time_stamp, current_percentage, target_percentage in readings:
        total_seconds = compute_spray_duration(current_percentage, target_percentage)
        spray_schedule.append((time_stamp, total_seconds))
    return spray_schedule


def parse_reading_line(raw_line):
    field_values = [field.strip() for field in raw_line.split(",")]
    if len(field_values) != 3:
        raise ValueError("expected 'time,current,target' but got: " + raw_line)
    time_stamp = field_values[0]
    current_percentage = int(field_values[1])
    target_percentage = int(field_values[2])
    for percentage_value in (current_percentage, target_percentage):
        if not 0 <= percentage_value <= 100:
            raise ValueError("humidity out of range in line: " + raw_line)
    return (time_stamp, current_percentage, target_percentage)


def load_readings(raw_lines):
    parsed_readings = []
    for raw_line in raw_lines:
        if raw_line.strip():
            parsed_readings.append(parse_reading_line(raw_line))
    return parsed_readings


def format_schedule_report(spray_schedule):
    report_lines = []
    running_total = 0
    for time_stamp, total_seconds in spray_schedule:
        if total_seconds:
            action_text = "mist for {0}s".format(total_seconds)
        else:
            action_text = "idle"
        running_total += total_seconds
        report_lines.append("{0}  {1}".format(time_stamp, action_text))
    report_lines.append("total mister runtime: {0}s".format(running_total))
    return "\n".join(report_lines)


