def validate_note_entry(note_entry):
    if len(note_entry) != 3:
        raise ValueError("each note needs an identifier, a concentration and a note type")
    ingredient_name, concentration_percentage, note_type = note_entry
    if not isinstance(ingredient_name, str) or not ingredient_name.strip():
        raise ValueError("ingredient identifier must be a non-empty string")
    if not isinstance(concentration_percentage, (int, float)) or isinstance(concentration_percentage, bool):
        raise ValueError("concentration percentage must be numeric")
    if concentration_percentage < 0 or concentration_percentage > 100:
        raise ValueError("concentration percentage must fall between 0 and 100")
    if note_type not in (1, 2, 3):
        raise ValueError("note type must be 1 (top), 2 (heart) or 3 (base)")
    return ingredient_name.strip(), float(concentration_percentage), int(note_type)


def compute_liquid_volume(concentration_percentage):
    standard_volume = concentration_percentage * 10
    if concentration_percentage > 50:
        return standard_volume * 1.2
    return standard_volume


def blend(notes):
    volume_totals = [0.0, 0.0, 0.0]
    for raw_entry in notes:
        _, concentration_percentage, note_type = validate_note_entry(raw_entry)
        final_volume = compute_liquid_volume(concentration_percentage)
        volume_totals[note_type - 1] += final_volume
    return tuple(volume_totals)


def describe_blend(notes):
    top_volume, heart_volume, base_volume = blend(notes)
    total_volume = top_volume + heart_volume + base_volume
    category_labels = ("Top", "Heart", "Base")
    report_lines = []
    for label_index, category_label in enumerate(category_labels):
        category_volume = (top_volume, heart_volume, base_volume)[label_index]
        if total_volume > 0:
            share_percentage = category_volume / total_volume * 100
        else:
            share_percentage = 0.0
        report_lines.append(
            "{:<6} {:>9.1f} mL  ({:>5.1f}%)".format(category_label, category_volume, share_percentage)
        )
    report_lines.append("{:<6} {:>9.1f} mL".format("Total", total_volume))
    return "\n".join(report_lines)


def ingredient_breakdown(notes):
    breakdown_rows = []
    for raw_entry in notes:
        ingredient_name, concentration_percentage, note_type = validate_note_entry(raw_entry)
        final_volume = compute_liquid_volume(concentration_percentage)
        is_overpowering = concentration_percentage > 50
        breakdown_rows.append((ingredient_name, note_type, final_volume, is_overpowering))
    breakdown_rows.sort(key=lambda row_data: (row_data[1], -row_data[2]))
    return breakdown_rows


def main():
    sample_notes = [
        ("Bergamot", 30, 1),
        ("Lemon Zest", 55, 1),
        ("Rose", 60, 2),
        ("Jasmine", 20, 2),
        ("Sandalwood", 45, 3),
    ]
    for ingredient_name, note_type, final_volume, is_overpowering in ingredient_breakdown(sample_notes):
        penalty_marker = " *overpowering*" if is_overpowering else ""
        print("[{}] {:<12} {:>8.1f} mL{}".format(note_type, ingredient_name, final_volume, penalty_marker))
    print()
    print(describe_blend(sample_notes))
    print()
    print("blend result:", blend([("Rose", 60, 2)]))


if __name__ == "__main__":
    main()

