vibration_frequency = 300.0


def core_factor(scale_length):
    """Return the squared product of twice the scale length and the frequency."""
    doubled_length = 2.0 * scale_length
    raw_factor = doubled_length * vibration_frequency
    return raw_factor * raw_factor


def validate_profile(string_profile):
    """Unpack and check one (identifier, unit weight, scale length) tuple."""
    if len(string_profile) != 3:
        raise ValueError("each string profile needs 3 fields: %r" % (string_profile,))
    string_id, unit_weight, scale_length = string_profile
    if not isinstance(string_id, str) or not string_id.strip():
        raise ValueError("string identifier must be a non-empty text label")
    if unit_weight <= 0:
        raise ValueError("unit weight for %s must be positive" % string_id)
    if scale_length <= 0:
        raise ValueError("scale length for %s must be positive" % string_id)
    return string_id.strip(), float(unit_weight), float(scale_length)


def tension(strings):
    """Compute the required tension for every string profile in the list."""
    tension_table = []
    for string_profile in strings:
        string_id, unit_weight, scale_length = validate_profile(string_profile)
        raw_tension = core_factor(scale_length) * unit_weight
        tension_table.append((string_id, round(raw_tension, 4)))
    return tension_table


def tension_summary(tension_table):
    """Return the heaviest entry, lightest entry and mean of a computed table."""
    tension_values = [entry_value for entry_label, entry_value in tension_table]
    max_entry = max(tension_table, key=lambda table_entry: table_entry[1])
    min_entry = min(tension_table, key=lambda table_entry: table_entry[1])
    average_tension = sum(tension_values) / len(tension_values)
    return max_entry, min_entry, round(average_tension, 4)


def format_report(tension_table):
    """Build a printable, aligned report of the tension table."""
    if not tension_table:
        return "no string profiles supplied"
    label_width = max(len(entry_label) for entry_label, entry_value in tension_table)
    report_lines = ["%-*s  %12s" % (label_width, "STRING", "TENSION")]
    for string_id, required_tension in tension_table:
        report_lines.append("%-*s  %12.3f" % (label_width, string_id, required_tension))
    max_entry, min_entry, average_tension = tension_summary(tension_table)
    report_lines.append("heaviest: %s (%.3f)" % (max_entry[0], max_entry[1]))
    report_lines.append("lightest: %s (%.3f)" % (min_entry[0], min_entry[1]))
    report_lines.append("average : %.3f" % average_tension)
    return "\n".join(report_lines)


def main():
    string_set = [
        ("E", 0.005, 0.6),
        ("A", 0.0075, 0.6),
        ("D", 0.011, 0.635),
        ("G", 0.018, 0.648),
    ]
    computed_table = tension(string_set)
    print(format_report(computed_table))


if __name__ == "__main__":
    main()

