SIGNAL_TARGET_CEILING = 100
ADEQUATE_SIGNAL_THRESHOLD = 80


def validate_measurement(measurement_tuple):
    """Unpack one telemetry record and check it is usable for alignment."""
    if len(measurement_tuple) != 3:
        raise ValueError("each measurement needs azimuth, elevation and strength")
    azimuth_angle, elevation_angle, signal_strength = measurement_tuple
    if elevation_angle == 0 and signal_strength < ADEQUATE_SIGNAL_THRESHOLD:
        raise ValueError(
            "elevation angle of 0 cannot be used to correct azimuth {0}".format(azimuth_angle)
        )
    return azimuth_angle, elevation_angle, signal_strength


def compute_adjustment_factor(elevation_angle, signal_strength):
    """Return the correction factor derived from the signal shortfall."""
    signal_shortfall = SIGNAL_TARGET_CEILING - signal_strength
    if signal_strength < ADEQUATE_SIGNAL_THRESHOLD:
        adjustment_factor = signal_shortfall / elevation_angle
    else:
        adjustment_factor = 0
    return round(adjustment_factor, 2)


def align(measurements):
    """Evaluate telemetry and report the azimuth corrections required."""
    alignment_results = []
    for measurement_tuple in measurements:
        azimuth_angle, elevation_angle, signal_strength = validate_measurement(measurement_tuple)
        adjustment_factor = compute_adjustment_factor(elevation_angle, signal_strength)
        alignment_results.append((azimuth_angle, adjustment_factor))
    return alignment_results


def summarise_alignment(alignment_results):
    """Condense the alignment output into headline numbers."""
    correction_count = 0
    largest_adjustment = 0.0
    worst_azimuth = None
    for azimuth_angle, adjustment_factor in alignment_results:
        if adjustment_factor > 0:
            correction_count += 1
        if adjustment_factor > largest_adjustment:
            largest_adjustment = adjustment_factor
            worst_azimuth = azimuth_angle
    return correction_count, largest_adjustment, worst_azimuth


def format_report(alignment_results):
    """Build the printable telemetry report lines."""
    report_lines = ["azimuth   adjustment"]
    for azimuth_angle, adjustment_factor in alignment_results:
        report_lines.append("{0:>7}   {1:>10.2f}".format(azimuth_angle, adjustment_factor))
    correction_count, largest_adjustment, worst_azimuth = summarise_alignment(alignment_results)
    report_lines.append(
        "{0} records, {1} needing correction".format(len(alignment_results), correction_count)
    )
    if worst_azimuth is not None:
        report_lines.append(
            "largest adjustment {0:.2f} at azimuth {1}".format(largest_adjustment, worst_azimuth)
        )
    return "\n".join(report_lines)


def main():
    telemetry_log = [(180, 45, 70), (90, 30, 85), (270, 60, 52), (0, 15, 79)]
    alignment_results = align(telemetry_log)
    print(alignment_results)
    print(format_report(alignment_results))


if __name__ == "__main__":
