TEST_DURATION_MINUTES = 5
CHARACTERS_PER_WORD = 5


def validate_entry(test_entry):
    if len(test_entry) != 3:
        raise ValueError("each test entry needs a name, a char count and an error count")
    user_identifier, total_characters, error_count = test_entry
    if not isinstance(user_identifier, str) or not user_identifier.strip():
        raise ValueError("user identifier must be a non-empty string")
    if total_characters < 0 or error_count < 0:
        raise ValueError("character and error counts cannot be negative")
    return user_identifier.strip(), total_characters, error_count


def compute_net_speed(total_characters, error_count):
    gross_word_count = total_characters / CHARACTERS_PER_WORD
    net_valid_words = gross_word_count - error_count
    final_speed = net_valid_words / TEST_DURATION_MINUTES
    if final_speed < 0:
        return 0
    return final_speed


def analyze(tests):
    speed_results = []
    for test_entry in tests:
        user_identifier, total_characters, error_count = validate_entry(test_entry)
        speed_results.append((user_identifier, compute_net_speed(total_characters, error_count)))
    return speed_results


def rank_results(speed_results):
    return sorted(speed_results, key=lambda result_pair: (-result_pair[1], result_pair[0]))


def average_speed(speed_results):
    if not speed_results:
        return 0.0
    speed_total = sum(measured_speed for _name, measured_speed in speed_results)
    return speed_total / len(speed_results)


def format_report(speed_results):
    ranked_results = rank_results(speed_results)
    name_column_width = max((len(name) for name, _speed in ranked_results), default=4)
    report_lines = ["{:<{}}  {:>8}".format("USER", name_column_width, "WPM")]
    for placement_index, (user_identifier, measured_speed) in enumerate(ranked_results, start=1):
        report_lines.append(
            "{:<{}}  {:>8.2f}  #{}".format(
                user_identifier, name_column_width, measured_speed, placement_index
            )
        )
    report_lines.append("{:<{}}  {:>8.2f}".format("MEAN", name_column_width, average_speed(ranked_results)))
    return "\n".join(report_lines)


def main():
    raw_tests = [
        ("Tim", 1000, 10),
        ("Dana", 1240, 4),
        ("Omar", 860, 12),
        ("Beth", 300, 75),
    ]
    speed_results = analyze(raw_tests)
    print(speed_results)
    print(format_report(speed_results))
    fastest_name, fastest_speed = rank_results(speed_results)[0]
    print("Fastest typist: {} at {:.2f} WPM".format(fastest_name, fastest_speed))


if __name__ == "__main__":
    main()

