def compute_depth_penalty(depth_in_inches):
    if depth_in_inches > DEPTH_THRESHOLD_INCHES:
        return DEPTH_PENALTY_VALUE
    return 0


def adjust_conductivity(conductivity_reading, depth_in_inches):
    depth_penalty = compute_depth_penalty(depth_in_inches)
    return conductivity_reading - depth_penalty


def assign_category(adjusted_conductivity):
    if adjusted_conductivity < IRON_UPPER_LIMIT:
        return "iron"
    if adjusted_conductivity <= GOLD_UPPER_LIMIT:
        return "gold"
    return "silver"


def validate_find_record(find_record):
    if len(find_record) != 3:
        raise ValueError("each find needs an identifier, a reading and a depth")
    find_identifier, conductivity_reading, depth_in_inches = find_record
    if not isinstance(find_identifier, str) or not find_identifier:
        raise ValueError("find identifier must be a non-empty string")
    if not isinstance(conductivity_reading, (int, float)):
        raise ValueError("conductivity reading must be numeric")
    if not isinstance(depth_in_inches, (int, float)) or depth_in_inches < 0:
        raise ValueError("depth must be a non-negative number")
    return find_identifier, conductivity_reading, depth_in_inches


def classify(finds):
    classified_finds = []
    for find_record in finds:
        find_identifier, conductivity_reading, depth_in_inches = validate_find_record(find_record)
        adjusted_conductivity = adjust_conductivity(conductivity_reading, depth_in_inches)
        classified_finds.append((find_identifier, assign_category(adjusted_conductivity)))
    return classified_finds


def summarize_categories(classified_finds):
    category_totals = {}
    for _, material_category in classified_finds:
        category_totals[material_category] = category_totals.get(material_category, 0) + 1
