def parse_lap_record(lap_record):
    driver_identifier = lap_record[0]
    lap_time_values = [float(raw_time) for raw_time in lap_record[1:]]
    if len(lap_time_values) != 3:
        raise ValueError("each record needs exactly three lap times: " + str(driver_identifier))
    return driver_identifier, lap_time_values


def collect_personal_bests(laps):
    personal_best_table = []
    fastest_overall_time = None
    for lap_record in laps:
        driver_identifier, lap_time_values = parse_lap_record(lap_record)
        personal_best_time = min(lap_time_values)
        personal_best_table.append((driver_identifier, personal_best_time))
        if fastest_overall_time is None or personal_best_time < fastest_overall_time:
            fastest_overall_time = personal_best_time
    return personal_best_table, fastest_overall_time


def normalize_time_value(time_value):
    rounded_value = round(time_value, 3)
    if rounded_value == int(rounded_value):
        return int(rounded_value)
    return rounded_value


def rank(laps):
    personal_best_table, fastest_overall_time = collect_personal_bests(laps)
    leaderboard_rows = []
    for driver_identifier, personal_best_time in personal_best_table:
        gap_to_leader = round(personal_best_time - fastest_overall_time, 3)
        leaderboard_rows.append((
            driver_identifier,
            normalize_time_value(personal_best_time),
            normalize_time_value(gap_to_leader),
        ))
    leaderboard_rows.sort(key=lambda result_row: result_row[2])
    return leaderboard_rows


def format_leaderboard(leaderboard_rows):
    name_column_width = max(len(str(result_row[0])) for result_row in leaderboard_rows)
    formatted_lines = ["POS  " + "DRIVER".ljust(name_column_width) + "   BEST      GAP"]
    for position_index, result_row in enumerate(leaderboard_rows, start=1):
        driver_identifier, best_time, gap_to_leader = result_row
        gap_display_text = "leader" if gap_to_leader == 0 else "+{0}".format(gap_to_leader)
        formatted_lines.append("{0:<5}{1}   {2:<9} {3}".format(
            position_index,
            str(driver_identifier).ljust(name_column_width),
            best_time,
            gap_display_text,
        ))
    return "\n".join(formatted_lines)


def main():
    timing_records = [
        ("Racer1", 45, 46, 44),
        ("Racer2", 48, 47, 49),
        ("Racer3", 44.512, 43.987, 45.1),
        ("Racer4", 43.9, 44.25, 43.987),
    ]
    leaderboard_rows = rank(timing_records)
    print(format_leaderboard(leaderboard_rows))
    print()
    print("raw result:", leaderboard_rows)


if __name__ == "__main__":
