BASE_INK_PER_WORD = 0.02
MIN_FLOURISH_LEVEL = 1
MAX_FLOURISH_LEVEL = 5


def validate_document_entry(document_entry):
    if len(document_entry) != 3:
        raise ValueError("each document needs an id, a word count and a flourish level")
    document_id, word_count, flourish_level = document_entry
    if not isinstance(document_id, str) or not document_id.strip():
        raise ValueError("document identifier must be a non-empty string")
    if not isinstance(word_count, int) or word_count < 0:
        raise ValueError("word count for %r must be a non-negative integer" % (document_id,))
    if not isinstance(flourish_level, int):
        raise ValueError("flourish level for %r must be an integer" % (document_id,))
    if not MIN_FLOURISH_LEVEL <= flourish_level <= MAX_FLOURISH_LEVEL:
        raise ValueError(
            "flourish level for %r must be between %d and %d"
            % (document_id, MIN_FLOURISH_LEVEL, MAX_FLOURISH_LEVEL)
        )
    return document_id.strip(), word_count, flourish_level


def standard_ink_volume(word_count):
    return word_count * BASE_INK_PER_WORD


def decorative_multiplier(flourish_level):
    return flourish_level / 10 + 1


def estimate(documents):
    estimated_volumes = []
    for document_entry in documents:
        document_id, word_count, flourish_level = validate_document_entry(document_entry)
        base_volume = standard_ink_volume(word_count)
        total_consumption = base_volume * decorative_multiplier(flourish_level)
        estimated_volumes.append((document_id, round(total_consumption, 2)))
    return estimated_volumes


def summarise_order(estimated_volumes):
    total_ink_needed = sum(pair[1] for pair in estimated_volumes)
    heaviest_document = None
    if estimated_volumes:
        heaviest_document = max(estimated_volumes, key=lambda pair: pair[1])[0]
    return {
        "document_count": len(estimated_volumes),
        "totalInkNeeded": round(total_ink_needed, 2),
        "heaviestDocument": heaviest_document,
    }


def format_report(estimated_volumes):
    label_width = max([len(pair[0]) for pair in estimated_volumes] + [8])
