def validate_pattern_entry(pattern_entry):
    if len(pattern_entry) != 3:
        raise ValueError("each pattern entry needs an identifier, prop count and throw rate")
    pattern_identifier, prop_count, throw_rate = pattern_entry
    if not isinstance(pattern_identifier, str) or not pattern_identifier.strip():
        raise ValueError("pattern identifier must be a non-empty string")
    if prop_count <= 0:
        raise ValueError("prop count must be positive for %s" % pattern_identifier)
    if throw_rate <= 0:
        raise ValueError("throw rate must be positive for %s" % pattern_identifier)
    return pattern_identifier.strip(), prop_count, throw_rate


def compute_air_time(prop_count, throw_rate):
    cycle_duration = prop_count / throw_rate
    return cycle_duration - HAND_DWELL_TIME


def compute_peak_height(air_time_value):
    if air_time_value <= 0:
        return 0.0
    return (GRAVITY_CONSTANT / 8.0) * air_time_value ** 2


def height(patterns):
    flight_results = []
    for pattern_entry in patterns:
        pattern_identifier, prop_count, throw_rate = validate_pattern_entry(pattern_entry)
        air_time_value = compute_air_time(prop_count, throw_rate)
        peak_height_value = compute_peak_height(air_time_value)
        flight_results.append((pattern_identifier, round(peak_height_value, 3)))
    return flight_results


def build_report_lines(patterns):
    report_lines = []
    computed_heights = dict(height(patterns))
    for pattern_entry in patterns:
        pattern_identifier, prop_count, throw_rate = validate_pattern_entry(pattern_entry)
        air_time_value = compute_air_time(prop_count, throw_rate)
        peak_height_value = computed_heights[pattern_identifier]
        report_lines.append(
            "%-12s props=%-3d rate=%-4s air_time=%6.3f s  peak=%6.3f m"
            % (pattern_identifier, prop_count, throw_rate, max(air_time_value, 0.0), peak_height_value)
        )
    return report_lines


def find_highest_pattern(patterns):
    height_pairs = height(patterns)
    if not height_pairs:
        return None
    best_pattern, best_height = height_pairs[0]
    for pattern_identifier, peak_height_value in height_pairs[1:]:
        if peak_height_value > best_height:
            best_pattern, best_height = pattern_identifier, peak_height_value
    return best_pattern, best_height


