def validate_article_entry(article_entry):
    if len(article_entry) != 3:
        raise ValueError("each article needs an id, a word count and a base rate")
    article_identifier, word_count, base_rate = article_entry
    if not isinstance(article_identifier, str) or not article_identifier.strip():
        raise ValueError("article identifier must be a non-empty string")
    if not isinstance(word_count, int) or word_count < 0:
        raise ValueError("word count for %r must be a non-negative integer" % article_identifier)
    if base_rate < 0:
        raise ValueError("base rate for %r must not be negative" % article_identifier)
    return article_identifier.strip(), word_count, float(base_rate)


def compute_standard_fee(word_count, base_rate):
    return word_count * base_rate


def apply_length_modifiers(standard_fee, word_count):
    adjusted_payment = standard_fee
    if word_count > LONGFORM_WORD_THRESHOLD:
        adjusted_payment += LONGFORM_BONUS_AMOUNT
    if word_count < SHORTFORM_WORD_THRESHOLD:
        adjusted_payment -= SHORTFORM_PENALTY_AMOUNT
    return max(adjusted_payment, 0.0)


