    for article_entry in articles:
        article_identifier, word_count, base_rate = validate_article_entry(article_entry)
        standard_fee = compute_standard_fee(word_count, base_rate)
        final_payment = apply_length_modifiers(standard_fee, word_count)
        payment_lines.append((article_identifier, round(final_payment, 2)))
