        raise ValueError("each unit record needs 4 fields, got %d" % len(unit_record))
    unit_identifier, unit_height, obstacle_height, distance_to_target = unit_record
    if not isinstance(unit_identifier, str) or not unit_identifier:
        raise ValueError("unit identifier must be a non-empty string")
    for field_name, field_value in (
        ("unit height", unit_height),
        ("obstacle height", obstacle_height),
        ("distance to target", distance_to_target),
    ):
        if not isinstance(field_value, (int, float)) or isinstance(field_value, bool):
            raise ValueError("%s of %s must be numeric" % (field_name, unit_identifier))
        if field_value < 0:
            raise ValueError("%s of %s must not be negative" % (field_name, unit_identifier))
    return unit_identifier, unit_height, obstacle_height, distance_to_target


