ADMIN_MAX_AGE = 30
USER_MAX_AGE = 90


def max_allowed_age(privilege_level):
    """Return the maximum password age tolerated for a privilege level."""
    normalized_level = privilege_level.strip().lower()
    if normalized_level == "admin":
        return ADMIN_MAX_AGE
    if normalized_level == "user":
        return USER_MAX_AGE
    raise ValueError("unknown privilege level: " + privilege_level)


def is_clock_anomaly(days_since_change):
    """A negative age can only come from a broken system clock."""
    return days_since_change < 0


def audit(accounts):
    """Return the usernames of accounts that fail the password age policy."""
    flagged_users = []
    for user_name, days_since_change, privilege_level in accounts:
        age_threshold = max_allowed_age(privilege_level)
        if is_clock_anomaly(days_since_change) or days_since_change > age_threshold:
            flagged_users.append(user_name)
    return flagged_users


def describe_account(account_record):
    """Build a human readable verdict for a single account tuple."""
    user_name, days_since_change, privilege_level = account_record
    age_threshold = max_allowed_age(privilege_level)
    if is_clock_anomaly(days_since_change):
        verdict_text = "CLOCK ANOMALY"
    elif days_since_change > age_threshold:
        overdue_days = days_since_change - age_threshold
        verdict_text = "EXPIRED by {} day(s)".format(overdue_days)
    else:
        remaining_days = age_threshold - days_since_change
        verdict_text = "OK for {} more day(s)".format(remaining_days)
    return "{:<10} {:<6} age={:<5} limit={:<4} {}".format(
        user_name, privilege_level, days_since_change, age_threshold, verdict_text
    )


def build_report(accounts):
    """Produce the full scanner report as a list of output lines."""
    report_lines = ["Password age audit", "-" * 58]
    for account_record in accounts:
        report_lines.append(describe_account(account_record))
    flagged_users = audit(accounts)
    total_scanned = len(accounts)
    report_lines.append("-" * 58)
    report_lines.append(
        "{} of {} account(s) flagged".format(len(flagged_users), total_scanned)
    )
    if flagged_users:
        report_lines.append("Action required for: " + ", ".join(flagged_users))
    return report_lines


def main():
    account_records = [
        ("root", 35, "admin"),
        ("guest", 40, "user"),
        ("backup_svc", -3, "admin"),
        ("deploy", 120, "user"),
        ("audit_bot", 12, "admin"),
    ]
    for report_line in build_report(account_records):
        print(report_line)
    print("audit() ->", audit(account_records))


if __name__ == "__main__":
    main()

