ELIMINATION_POINT_VALUE = 5
FLAG_CAPTURE_POINT_VALUE = 50
DOMINANCE_FLAG_THRESHOLD = 3
OVERWHELMING_VICTORY_BONUS = 20


def validate_match_record(match_record):
    if len(match_record) != 3:
        raise ValueError("each match record needs an identifier, eliminations and captures")
    team_identifier, players_eliminated, flag_captures = match_record
    if not isinstance(team_identifier, str) or not team_identifier.strip():
        raise ValueError("team identifier must be a non-empty string")
    for tally_name, tally_value in (("eliminations", players_eliminated), ("captures", flag_captures)):
        if not isinstance(tally_value, int) or isinstance(tally_value, bool):
            raise TypeError("%s tally for %s must be an integer" % (tally_name, team_identifier))
        if tally_value < 0:
            raise ValueError("%s tally for %s cannot be negative" % (tally_name, team_identifier))
    return team_identifier.strip(), players_eliminated, flag_captures


def elimination_subtotal(players_eliminated):
    return players_eliminated * ELIMINATION_POINT_VALUE


def objective_subtotal(flag_captures):
    return flag_captures * FLAG_CAPTURE_POINT_VALUE


def dominance_bonus(flag_captures):
    if flag_captures > DOMINANCE_FLAG_THRESHOLD:
        return OVERWHELMING_VICTORY_BONUS
    return 0


def score(matches):
    scored_results = []
    for match_record in matches:
        team_identifier, players_eliminated, flag_captures = validate_match_record(match_record)
        final_match_score = (
            elimination_subtotal(players_eliminated)
            + objective_subtotal(flag_captures)
            + dominance_bonus(flag_captures)
        )
        scored_results.append((team_identifier, final_match_score))
    return scored_results


def rank_scored_results(scored_results):
    return sorted(scored_results, key=lambda scored_entry: (-scored_entry[1], scored_entry[0]))


def format_score_report(matches):
    scored_results = rank_scored_results(score(matches))
    capture_lookup = {}
    for match_record in matches:
        team_identifier, _eliminations, flag_captures = validate_match_record(match_record)
        capture_lookup[team_identifier] = flag_captures
    report_lines = ["RANK  TEAM        SCORE  NOTE"]
    for rank_position, (team_identifier, team_score) in enumerate(scored_results, start=1):
        dominance_note = "dominance" if capture_lookup[team_identifier] > DOMINANCE_FLAG_THRESHOLD else ""
        report_lines.append(
            "%-5d %-11s %5d  %s" % (rank_position, team_identifier, team_score, dominance_note)
        )
    return "\n".join(report_lines)


def main():
    match_results = [
        ("Red", 10, 4),
        ("Blue", 22, 2),
        ("Green", 3, 0),
        ("Yellow", 8, 5),
    ]
    print(score(match_results))
    print(format_score_report(match_results))
    total_points_awarded = sum(team_score for _team, team_score in score(match_results))
    print("total points awarded: %d" % total_points_awarded)


if __name__ == "__main__":
    main()

