OVERWHELMING_VICTORY_BONUS = 20


def validateMatchRecord(matchRecord):
    if len(matchRecord) != 3:
        raise ValueError("each match record needs an identifier, eliminations and captures")
    teamIdentifier, playersEliminated, flagCaptures = matchRecord
    if not isinstance(teamIdentifier, str) or not teamIdentifier.strip():
        raise ValueError("team identifier must be a non-empty string")
    for tallyName, tallyValue in (("eliminations", playersEliminated), ("captures", flagCaptures)):
        if not isinstance(tallyValue, int) or isinstance(tallyValue, bool):
            raise TypeError("%s tally for %s must be an integer" % (tallyName, teamIdentifier))
        if tallyValue < 0:
            raise ValueError("%s tally for %s cannot be negative" % (tallyName, teamIdentifier))
    return teamIdentifier.strip(), playersEliminated, flagCaptures


def eliminationSubtotal(playersEliminated):
    return playersEliminated * ELIMINATION_POINT_VALUE


def objectiveSubtotal(flagCaptures):
    return flagCaptures * FLAG_CAPTURE_POINT_VALUE


def dominanceBonus(flagCaptures):
    if flagCaptures > DOMINANCE_FLAG_THRESHOLD:
        return OVERWHELMING_VICTORY_BONUS
    return 0


def score(matches):
    scoredResults = []
    for matchRecord in matches:
        teamIdentifier, playersEliminated, flagCaptures = validateMatchRecord(matchRecord)
        finalMatchScore = (
            eliminationSubtotal(playersEliminated)
            + objectiveSubtotal(flagCaptures)
            + dominanceBonus(flagCaptures)
        )
        scoredResults.append((teamIdentifier, finalMatchScore))
    return scoredResults


def rankScoredResults(scoredResults):
    return sorted(scoredResults, key=lambda scoredEntry: (-scoredEntry[1], scoredEntry[0]))


def formatScoreReport(matches):
    scoredResults = rankScoredResults(score(matches))
    captureLookup = {}
    for matchRecord in matches:
        teamIdentifier, _eliminations, flagCaptures = validateMatchRecord(matchRecord)
        captureLookup[teamIdentifier] = flagCaptures
    reportLines = ["RANK  TEAM        SCORE  NOTE"]
    for rankPosition, (teamIdentifier, teamScore) in enumerate(scoredResults, start=1):
        dominanceNote = "dominance" if captureLookup[teamIdentifier] > DOMINANCE_FLAG_THRESHOLD else ""
        reportLines.append(
            "%-5d %-11s %5d  %s" % (rankPosition, teamIdentifier, teamScore, dominanceNote)
        )
    return "\n".join(reportLines)


def main():
    matchResults = [
        ("Red", 10, 4),
        ("Blue", 22, 2),
        ("Green", 3, 0),
        ("Yellow", 8, 5),
    ]
    print(score(matchResults))
    print(formatScoreReport(matchResults))
    totalPointsAwarded = sum(teamScore for _team, teamScore in score(matchResults))
    print("total points awarded: %d" % totalPointsAwarded)


if __name__ == "__main__":
    main()

