THERMAL_HEADROOM_WATTS = 10
STANDARD_LOAD_FACTOR = 1.2
EXTREME_LOAD_FACTOR = 1.5
PSU_SAFETY_MARGIN = 1.25


def validate_component(component_entry):
    if len(component_entry) != 3:
        raise ValueError("each component needs an id, a wattage and an overclock flag")
    component_id, base_power_draw, is_overclocked = component_entry
    if not isinstance(component_id, str) or not component_id:
        raise ValueError("component identifier must be a non-empty string")
    if isinstance(base_power_draw, bool) or not isinstance(base_power_draw, (int, float)):
        raise ValueError("base power draw must be numeric for %r" % (component_id,))
    if base_power_draw < 0:
        raise ValueError("base power draw cannot be negative for %r" % (component_id,))
    if not isinstance(is_overclocked, bool):
        raise ValueError("overclock flag must be a boolean for %r" % (component_id,))
    return component_id, float(base_power_draw), is_overclocked


def peak_power_for(base_power_draw, is_overclocked):
    load_factor = EXTREME_LOAD_FACTOR if is_overclocked else STANDARD_LOAD_FACTOR
    return base_power_draw * load_factor + THERMAL_HEADROOM_WATTS


def calculate(components):
    peak_power_table = []
    for component_entry in components:
        component_id, base_power_draw, is_overclocked = validate_component(component_entry)
        maximum_power_draw = peak_power_for(base_power_draw, is_overclocked)
        peak_power_table.append((component_id, maximum_power_draw))
    return peak_power_table


def recommend_supply_size(peak_power_table, step_size=50):
    total_peak_draw = sum(maximum_power_draw for _id, maximum_power_draw in peak_power_table)
    required_capacity = total_peak_draw * PSU_SAFETY_MARGIN
    rounded_capacity = step_size * int(required_capacity / step_size)
    if rounded_capacity < required_capacity:
        rounded_capacity += step_size
    return total_peak_draw, rounded_capacity


def format_sizing_report(peak_power_table):
    if not peak_power_table:
        return "No components supplied."
    widest_label = max(len(component_id) for component_id, _draw in peak_power_table)
    report_lines = []
    for component_id, maximum_power_draw in peak_power_table:
        report_lines.append("%-*s %8.1f W" % (widest_label, component_id, maximum_power_draw))
    total_peak_draw, recommended_capacity = recommend_supply_size(peak_power_table)
    report_lines.append("-" * (widest_label + 11))
    report_lines.append("%-*s %8.1f W" % (widest_label, "TOTAL", total_peak_draw))
    report_lines.append("Recommended PSU: %d W" % recommended_capacity)
    return "\n".join(report_lines)


def main():
    build_components = [
        ("CPU", 100, True),
        ("GPU", 320, True),
        ("Motherboard", 55, False),
        ("RAM", 12, False),
        ("NVMe SSD", 8, False),
        ("Case Fans", 9, False),
    ]
    peak_power_table = calculate(build_components)
    print(format_sizing_report(peak_power_table))


