PLATE_PRICE_TABLE = {"green": 2, "blue": 3, "red": 5}
SPECIAL_REQUEST_FEE = 1
DISCOUNT_PLATE_THRESHOLD = 15
DISCOUNT_RATE = 0.10


def plate_unit_price(plate_color):
    normalized_color = plate_color.strip().lower()
    if normalized_color not in PLATE_PRICE_TABLE:
        raise ValueError("unknown plate color: {!r}".format(plate_color))
    return PLATE_PRICE_TABLE[normalized_color]


def plate_line_cost(plate_entry):
    plate_color, stack_height, special_request = plate_entry
    if not isinstance(stack_height, int) or stack_height < 1:
        raise ValueError("stack height must be a positive integer, got {!r}".format(stack_height))
    line_cost = plate_unit_price(plate_color) * stack_height
    if special_request:
        line_cost += SPECIAL_REQUEST_FEE
    return line_cost


def count_individual_plates(plate_list):
    total_plate_count = 0
    for plate_entry in plate_list:
        total_plate_count += plate_entry[1]
    return total_plate_count


def bill(plates):
    running_total = 0
    for plate_entry in plates:
        running_total += plate_line_cost(plate_entry)
    total_plate_count = count_individual_plates(plates)
    if total_plate_count > DISCOUNT_PLATE_THRESHOLD:
        running_total = running_total * (1 - DISCOUNT_RATE)
    return round(running_total)


def format_receipt(plates, table_label):
    receipt_lines = ["Table {}".format(table_label)]
    for plate_entry in plates:
        plate_color, stack_height, special_request = plate_entry
        request_marker = " (special)" if special_request else ""
        receipt_lines.append(
            "  {:<5} x{}{:<10} {:>3}".format(
                plate_color, stack_height, request_marker, plate_line_cost(plate_entry)
            )
        )
    total_plate_count = count_individual_plates(plates)
    final_amount_due = bill(plates)
    receipt_lines.append("  plates counted: {}".format(total_plate_count))
    if total_plate_count > DISCOUNT_PLATE_THRESHOLD:
        receipt_lines.append("  bulk discount applied: {:.0f}%".format(DISCOUNT_RATE * 100))
    receipt_lines.append("  total due: {}".format(final_amount_due))
    return "\n".join(receipt_lines)


def main():
    small_order = [("blue", 2, True), ("red", 1, False)]
    large_order = [
        ("green", 6, False),
        ("blue", 5, True),
        ("red", 4, True),
        ("green", 2, False),
    ]
    for table_label, plate_list in (("A1", small_order), ("B7", large_order)):
        print(format_receipt(plate_list, table_label))
        print()


if __name__ == "__main__":
    main()

