BASE_REPAIR_MINUTES = 10


def validate_component(component):
    part_name, rust_percentage, is_moving_gear = component
    if not isinstance(part_name, str) or not part_name.strip():
        raise ValueError("part name must be a non-empty string")
    if not isinstance(rust_percentage, (int, float)):
        raise TypeError("rust percentage must be numeric for %r" % (part_name,))
    if rust_percentage < 0 or rust_percentage > 100:
        raise ValueError("rust percentage out of range for %r" % (part_name,))
    return part_name.strip(), float(rust_percentage), bool(is_moving_gear)


def extra_minutes_for(rust_percentage, is_moving_gear):
    if is_moving_gear:
        if rust_percentage > 50:
            return 20
        if rust_percentage >= 20:
            return 10
        return 0
    if rust_percentage > 50:
        return 5
    return 0


def estimate(components):
    repair_schedule = []
    for raw_component in components:
        part_name, rust_percentage, is_moving_gear = validate_component(raw_component)
        total_minutes = BASE_REPAIR_MINUTES + extra_minutes_for(rust_percentage, is_moving_gear)
        repair_schedule.append((part_name, total_minutes))
    return repair_schedule


def total_repair_time(repair_schedule):
    return sum(part_minutes for _part_name, part_minutes in repair_schedule)


def format_duration(minutes_value):
    whole_hours = minutes_value // 60
    leftover_minutes = minutes_value % 60
    if whole_hours:
        return "%dh %02dm" % (whole_hours, leftover_minutes)
    return "%dm" % leftover_minutes


def build_report(repair_schedule):
    name_column_width = max(len(part_name) for part_name, _minutes in repair_schedule)
    report_lines = []
    for part_name, part_minutes in repair_schedule:
        report_lines.append(
            "%-*s  %s" % (name_column_width, part_name, format_duration(part_minutes))
        )
    grand_total = total_repair_time(repair_schedule)
    report_lines.append("%-*s  %s" % (name_column_width, "TOTAL", format_duration(grand_total)))
    return "\n".join(report_lines)


def main():
    parts_to_restore = [
        ("escapement wheel", 60, True),
        ("mainspring barrel", 35, True),
        ("balance staff", 10, True),
        ("dial plate", 80, False),
        ("case back", 15, False),
    ]
    repair_schedule = estimate(parts_to_restore)
    print(repair_schedule)
    print(build_report(repair_schedule))
    longest_job_name, longest_job_minutes = max(repair_schedule, key=lambda entry: entry[1])
    print("Longest single job: %s (%s)" % (longest_job_name, format_duration(longest_job_minutes)))


if __name__ == "__main__":
    main()

