import math


def compute_wind_lift(surface_area):
    return surface_area * 50


def is_stable(surface_area, tail_length):
    required_tail_length = 2 * math.sqrt(surface_area)
    return tail_length >= required_tail_length


def compute_net_force(surface_area, structural_weight):
    wind_lift = compute_wind_lift(surface_area)
    return wind_lift - structural_weight / 10


def validate_kite(kite_spec):
    if len(kite_spec) != 3:
        raise ValueError("each kite needs surface area, tail length and weight")
    surface_area, tail_length, structural_weight = kite_spec
    for field_name, field_value in (
        ("surface area", surface_area),
        ("tail length", tail_length),
        ("structural weight", structural_weight),
    ):
        if not isinstance(field_value, (int, float)) or isinstance(field_value, bool):
            raise TypeError("%s must be numeric" % field_name)
        if field_value < 0:
            raise ValueError("%s cannot be negative" % field_name)
    return surface_area, tail_length, structural_weight


def stable_kite_forces(kites):
    force_list = []
    for kite_spec in kites:
        surface_area, tail_length, structural_weight = validate_kite(kite_spec)
        if is_stable(surface_area, tail_length):
            force_list.append(compute_net_force(surface_area, structural_weight))
    return force_list


def evaluate(kites):
    force_list = stable_kite_forces(kites)
    if not force_list:
        return None
    return max(force_list)


def format_kite_report(kites):
    report_lines = []
    for kite_index, kite_spec in enumerate(kites, start=1):
        surface_area, tail_length, structural_weight = validate_kite(kite_spec)
        net_force = compute_net_force(surface_area, structural_weight)
        stability_label = "stable" if is_stable(surface_area, tail_length) else "unstable"
        report_lines.append(
            "Kite %d: area=%gm2 tail=%gm weight=%gg -> %s, net force %.1fN"
            % (kite_index, surface_area, tail_length, structural_weight,
               stability_label, net_force)
        )
    best_force = evaluate(kites)
    if best_force is None:
        report_lines.append("No stable kite in this batch.")
    else:
        report_lines.append("Best net upward force: %.1fN" % best_force)
    return "\n".join(report_lines)


def main():
    kite_batch = [
        (4, 5, 200),
        (9, 4, 500),
        (16, 8, 1200),
        (2.25, 3, 100),
    ]
    print(format_kite_report(kite_batch))


if __name__ == "__main__":
    main()

