STANDARD_COURSE_TIME = 50
FAST_RUN_TIME_LIMIT = 40
KNOCKED_BAR_PENALTY = 5
MISSED_CONTACT_PENALTY = 10
FAST_RUN_BONUS = -5


def time_fault_points(base_time):
    seconds_over_standard = base_time - STANDARD_COURSE_TIME
    if seconds_over_standard > 0:
        return seconds_over_standard
    return 0


def obstacle_fault_points(knocked_bars, missed_contacts):
    bar_faults = knocked_bars * KNOCKED_BAR_PENALTY
    contact_faults = missed_contacts * MISSED_CONTACT_PENALTY
    return bar_faults + contact_faults


def score_single_run(base_time, knocked_bars, missed_contacts):
    total_penalty = time_fault_points(base_time) + obstacle_fault_points(
        knocked_bars, missed_contacts
    )
    if total_penalty == 0 and base_time < FAST_RUN_TIME_LIMIT:
        return FAST_RUN_BONUS
    return total_penalty


def validate_run(run_tuple):
    if len(run_tuple) != 3:
        raise ValueError("each run needs a time, a bar count and a contact count")
    base_time, knocked_bars, missed_contacts = run_tuple
    if base_time <= 0:
        raise ValueError("base time must be positive")
    if knocked_bars < 0 or missed_contacts < 0:
        raise ValueError("fault counts cannot be negative")
    return base_time, knocked_bars, missed_contacts


def score(runs):
    final_scores = []
    for single_run in runs:
        base_time, knocked_bars, missed_contacts = validate_run(single_run)
        final_scores.append(score_single_run(base_time, knocked_bars, missed_contacts))
    return final_scores


def rank_runs(runs):
    score_list = score(runs)
    indexed_scores = list(enumerate(score_list))
    indexed_scores.sort(key=lambda pair: (pair[1], runs[pair[0]][0]))
    return [dog_index for dog_index, _score_value in indexed_scores]


def format_report(runs, dog_names):
    score_list = score(runs)
    placement_order = rank_runs(runs)
    report_lines = []
    for placement_number, dog_index in enumerate(placement_order, start=1):
        dog_name = dog_names[dog_index]
        dog_score = score_list[dog_index]
        run_time = runs[dog_index][0]
        report_lines.append(
            "{0}. {1}: {2} points ({3}s)".format(
                placement_number, dog_name, dog_score, run_time
            )
        )
    return "\n".join(report_lines)


def main():
    trial_runs = [(45, 1, 0), (38, 0, 0), (54, 0, 1), (50, 2, 2)]
    competitor_names = ["Rex", "Pip", "Nala", "Bolt"]
    print(score(trial_runs))
    print(format_report(trial_runs, competitor_names))
    clean_round_count = sum(1 for points in score(trial_runs) if points <= 0)
    print("Clean rounds: {0} of {1}".format(clean_round_count, len(trial_runs)))


if __name__ == "__main__":
    main()

