BASE_SCOOP_PRICE = 2.0
EXTRA_SCOOP_PRICE = 1.5
WAFFLE_BOWL_PRICE = 1.0
TOPPING_UNIT_PRICE = 0.5
FREE_TOPPING_THRESHOLD = 3
FREE_TOPPING_ALLOWANCE = 2


def validate_order(sundae_order):
    scoop_count, wants_waffle_bowl, topping_list = sundae_order
    if not isinstance(scoop_count, int) or scoop_count < 1:
        raise ValueError("a sundae needs at least one scoop, got %r" % (scoop_count,))
    if not isinstance(wants_waffle_bowl, bool):
        raise ValueError("the waffle bowl flag must be a boolean")
    for topping_name in topping_list:
        if not isinstance(topping_name, str) or not topping_name.strip():
            raise ValueError("invalid topping name: %r" % (topping_name,))
    return scoop_count, wants_waffle_bowl, list(topping_list)


def count_billable_toppings(scoop_count, topping_list):
    topping_total = len(topping_list)
    if scoop_count >= FREE_TOPPING_THRESHOLD:
        return max(topping_total - FREE_TOPPING_ALLOWANCE, 0)
    return topping_total


def price_single_sundae(sundae_order):
    scoop_count, wants_waffle_bowl, topping_list = validate_order(sundae_order)
    scoop_price = BASE_SCOOP_PRICE + EXTRA_SCOOP_PRICE * (scoop_count - 1)
    bowl_price = WAFFLE_BOWL_PRICE if wants_waffle_bowl else 0.0
    billable_toppings = count_billable_toppings(scoop_count, topping_list)
    return scoop_price + bowl_price + billable_toppings * TOPPING_UNIT_PRICE


def calculate(sundaes):
    running_total = 0.0
    for sundae_order in sundaes:
        running_total += price_single_sundae(sundae_order)
    return running_total


def describe_sundae(sundae_order):
    scoop_count, wants_waffle_bowl, topping_list = validate_order(sundae_order)
    container_label = "waffle bowl" if wants_waffle_bowl else "paper cup"
    if topping_list:
        topping_summary = ", ".join(sorted(topping_list))
    else:
        topping_summary = "no toppings"
    return "%d scoop(s) in a %s with %s" % (scoop_count, container_label, topping_summary)


def build_receipt(sundaes):
    receipt_lines = []
    for line_number, sundae_order in enumerate(sundaes, start=1):
        line_price = price_single_sundae(sundae_order)
        receipt_lines.append(
