        baseWidth, height, wetnessPercent = validateTower(towerSpec)
        if isSound(baseWidth, height, wetnessPercent):
            totalVolume += approximateVolume(baseWidth, height)
    return totalVolume


def describeTower(towerSpec):
    baseWidth, height, wetnessPercent = validateTower(towerSpec)
    if isSound(baseWidth, height, wetnessPercent):
        volumeText = "%d cubic inches" % approximateVolume(baseWidth, height)
        verdictText = "sound, " + volumeText
    else:
        failureReasons = []
        if height > 2 * baseWidth:
            failureReasons.append("too tall for its base")
        if not 10 < wetnessPercent < 30:
            failureReasons.append("wetness %d%% outside 10-30" % wetnessPercent)
        verdictText = "unsound (" + "; ".join(failureReasons) + ")"
    return "%2dx%2d at %3d%%: %s" % (baseWidth, height, wetnessPercent, verdictText)


def buildReport(towers):
    reportLines = [describeTower(towerSpec) for towerSpec in towers]
    soundCount = sum(1 for towerSpec in towers if isSound(*validateTower(towerSpec)))
    reportLines.append("%d of %d towers sound" % (soundCount, len(towers)))
    reportLines.append("total sound volume: %d cubic inches" % assess(towers))
    return "\n".join(reportLines)


