    blockers_passed, lap_count, went_to_box = jam_record
    if not isinstance(blockers_passed, int) or isinstance(blockers_passed, bool):
        raise ValueError(f"jam {record_index}: blockers passed must be an int")
    if not isinstance(lap_count, int) or isinstance(lap_count, bool):
        raise ValueError(f"jam {record_index}: lap count must be an int")
    if not isinstance(went_to_box, bool):
        raise ValueError(f"jam {record_index}: penalty flag must be a bool")
    if blockers_passed < 0 or lap_count < 0:
        raise ValueError(f"jam {record_index}: counts must not be negative")
    return blockers_passed, lap_count, went_to_box


def score_single_jam(blockers_passed, lap_count, went_to_box):
    if lap_count < 2:
