SHUFFLE_ROUND_COUNT = 3
OUTER_SWAP_SIZE = 3


def validate_deck(deck):
    if not isinstance(deck, list):
        raise TypeError("deck must be a list of integer card values")
    validated_deck = []
    for card_position, card_value in enumerate(deck):
        if isinstance(card_value, bool) or not isinstance(card_value, int):
            raise TypeError(f"card at position {card_position} is not an integer")
        validated_deck.append(card_value)
    return validated_deck


def cut_in_half(deck):
    total_card_count = len(deck)
    top_half_size = (total_card_count + 1) // 2
    return deck[:top_half_size], deck[top_half_size:]


def faro_interleave(deck):
    top_half, bottom_half = cut_in_half(deck)
    interleaved_deck = []
    for card_index in range(len(top_half)):
        interleaved_deck.append(top_half[card_index])
        if card_index < len(bottom_half):
            interleaved_deck.append(bottom_half[card_index])
    return interleaved_deck


def faro_round_history(deck, round_count):
    current_deck = list(deck)
    round_history = []
    rounds_completed = 0
    while rounds_completed < round_count:
        current_deck = faro_interleave(current_deck)
        round_history.append(current_deck)
        rounds_completed += 1
    return round_history


def swap_outer_triples(deck):
    swapped_deck = list(deck)
    swap_size = min(OUTER_SWAP_SIZE, len(swapped_deck) // 2)
    for swap_offset in range(swap_size):
        top_index = swap_offset
        bottom_index = len(swapped_deck) - swap_size + swap_offset
        swapped_deck[top_index], swapped_deck[bottom_index] = (
            swapped_deck[bottom_index],
            swapped_deck[top_index],
        )
    return swapped_deck


def shuffle(deck):
    validated_deck = validate_deck(deck)
    if not validated_deck:
        return validated_deck
    round_history = faro_round_history(validated_deck, SHUFFLE_ROUND_COUNT)
    return swap_outer_triples(round_history[-1])


def format_deck_line(label_text, deck_state):
    card_text = " ".join(str(card_value) for card_value in deck_state)
    return f"{label_text:>8}: {card_text}"


def main():
    sample_decks = [[1, 2, 3, 4], list(range(1, 11))]
    for deck_number, original_deck in enumerate(sample_decks, start=1):
        print(f"Deck {deck_number} ({len(original_deck)} cards)")
        print(format_deck_line("start", original_deck))
        round_history = faro_round_history(original_deck, SHUFFLE_ROUND_COUNT)
        for round_number, round_state in enumerate(round_history, start=1):
            print(format_deck_line(f"faro {round_number}", round_state))
        print(format_deck_line("final", shuffle(original_deck)))
        print()


if __name__ == "__main__":
