BASE_SCORE = 100
WIND_BONUS_THRESHOLD = 15
ACCURACY_BONUS_RADIUS = 5
DIFFICULTY_BONUS_POINTS = 10
MINIMUM_SAFE_ALTITUDE = 2000
SAFETY_PENALTY_POINTS = 20


def validate_jump(jump_record):
    if len(jump_record) != 3:
        raise ValueError("each jump needs distance, wind speed and altitude")
    center_distance, wind_speed, opening_altitude = jump_record
    if center_distance < 0:
        raise ValueError("distance from the center cannot be negative")
    if wind_speed < 0:
        raise ValueError("wind speed cannot be negative")
    if opening_altitude <= 0:
        raise ValueError("opening altitude must be positive")
    return center_distance, wind_speed, opening_altitude


def difficulty_bonus(center_distance, wind_speed):
    if wind_speed > WIND_BONUS_THRESHOLD and center_distance <= ACCURACY_BONUS_RADIUS:
        return DIFFICULTY_BONUS_POINTS
    return 0


def safety_penalty(opening_altitude):
    if opening_altitude < MINIMUM_SAFE_ALTITUDE:
        return SAFETY_PENALTY_POINTS
    return 0


def score_single_jump(jump_record):
    center_distance, wind_speed, opening_altitude = validate_jump(jump_record)
    accuracy_score = BASE_SCORE - center_distance
    bonus_points = difficulty_bonus(center_distance, wind_speed)
    penalty_points = safety_penalty(opening_altitude)
    return accuracy_score + bonus_points - penalty_points


def score(jumps):
    return [score_single_jump(jump_record) for jump_record in jumps]


def format_jump_report(jump_record, final_score):
    center_distance, wind_speed, opening_altitude = jump_record
    return (
        "{:>5.1f} m  {:>4.1f} kt  {:>6d} ft  ->  {:>6.1f}".format(
            float(center_distance),
