BOUT_POINT_LIMIT = 15
YELLOW_CARD_TOKENS = {'yellow-left': 'left', 'yellow-right': 'right'}


def normalize_priority(priority_value):
    if not isinstance(priority_value, str):
        raise TypeError('priority must be given as a string')
    cleaned_priority = priority_value.strip().lower().replace('_', '-')
    return cleaned_priority.replace(' ', '-')


def parse_exchange(exchange_tuple):
    if len(exchange_tuple) != 3:
        raise ValueError('each exchange needs two hits and a priority')
    raw_left_hit, raw_right_hit, raw_priority = exchange_tuple
    priority_token = normalize_priority(raw_priority)
    return bool(raw_left_hit), bool(raw_right_hit), priority_token


def resolve_exchange(left_hit_flag, right_hit_flag, priority_token):
    penalized_side = YELLOW_CARD_TOKENS.get(priority_token)
    if penalized_side == 'left':
        return -1, 0
    if penalized_side == 'right':
        return 0, -1
    if left_hit_flag and right_hit_flag:
        if priority_token == 'left':
            return 1, 0
        if priority_token == 'right':
            return 0, 1
        return 0, 0
    if left_hit_flag:
        return 1, 0
    if right_hit_flag:
        return 0, 1
    return 0, 0


def referee(actions):
    left_score = 0
    right_score = 0
    for exchange_tuple in actions:
        left_hit_flag, right_hit_flag, priority_token = parse_exchange(exchange_tuple)
        left_delta, right_delta = resolve_exchange(left_hit_flag, right_hit_flag, priority_token)
        left_score = max(0, left_score + left_delta)
        right_score = max(0, right_score + right_delta)
        if left_score >= BOUT_POINT_LIMIT or right_score >= BOUT_POINT_LIMIT:
            break
    return left_score, right_score


def describe_result(left_score, right_score):
