def compute_difficulty(crease_count, paper_thickness):
    return crease_count * paper_thickness ** 2


def classify_difficulty(difficulty_score):
    if difficulty_score > 50:
        return 'advanced'
    if difficulty_score >= 20:
        return 'intermediate'
    return 'beginner'


def validate_model(model_entry):
    if len(model_entry) != 3:
        raise ValueError('each model needs a name, crease count and thickness')
    model_name, crease_count, paper_thickness = model_entry
    if not isinstance(model_name, str) or not model_name:
        raise ValueError('model name must be a non-empty string')
    if crease_count < 0:
        raise ValueError('crease count of %s must not be negative' % model_name)
    if paper_thickness <= 0:
        raise ValueError('paper thickness of %s must be positive' % model_name)
    return model_name, crease_count, paper_thickness


def analyze(models):
    beginner_count = 0
    intermediate_count = 0
    advanced_count = 0
    for model_entry in models:
        _, crease_count, paper_thickness = validate_model(model_entry)
        difficulty_score = compute_difficulty(crease_count, paper_thickness)
        category_name = classify_difficulty(difficulty_score)
        if category_name == 'advanced':
            advanced_count += 1
        elif category_name == 'intermediate':
            intermediate_count += 1
        else:
            beginner_count += 1
    return beginner_count, intermediate_count, advanced_count


def build_detail_rows(models):
    detail_rows = []
    for model_entry in models:
        model_name, crease_count, paper_thickness = validate_model(model_entry)
        difficulty_score = compute_difficulty(crease_count, paper_thickness)
        detail_rows.append((model_name, difficulty_score, classify_difficulty(difficulty_score)))
    detail_rows.sort(key=lambda detail_row: detail_row[1], reverse=True)
    return detail_rows


