ALTITUDE_RATES = {
    "burner blast": 10,
    "vent": -5,
    "glide": -1,
}

MINIMUM_ALTITUDE = 0


def normalize_action(raw_action):
    cleaned_action = " ".join(str(raw_action).strip().lower().split())
    if cleaned_action not in ALTITUDE_RATES:
        known_actions = ", ".join(sorted(ALTITUDE_RATES))
        raise ValueError(
            "unknown action %r (expected one of: %s)" % (raw_action, known_actions)
        )
    return cleaned_action


def parse_duration(raw_duration):
    if isinstance(raw_duration, bool) or not isinstance(raw_duration, int):
        raise TypeError("duration must be an integer number of seconds")
    if raw_duration < 0:
        raise ValueError("duration cannot be negative")
    return raw_duration


def apply_command(start_altitude, action, duration):
    rate_per_second = ALTITUDE_RATES[action]
    current_altitude = start_altitude
    segment_peak = start_altitude
    for _second in range(duration):
        current_altitude = max(MINIMUM_ALTITUDE, current_altitude + rate_per_second)
        if current_altitude > segment_peak:
            segment_peak = current_altitude
    return current_altitude, segment_peak


def run_flight(commands):
    current_altitude = MINIMUM_ALTITUDE
    peak_altitude = MINIMUM_ALTITUDE
    for raw_action, raw_duration in commands:
        action_name = normalize_action(raw_action)
        duration_seconds = parse_duration(raw_duration)
        current_altitude, segment_peak = apply_command(
            current_altitude, action_name, duration_seconds
        )
        if segment_peak > peak_altitude:
            peak_altitude = segment_peak
        yield action_name, duration_seconds, current_altitude, peak_altitude


def simulate(commands):
    peak_altitude = MINIMUM_ALTITUDE
    final_altitude = MINIMUM_ALTITUDE
    for _action, _duration, current_altitude, running_peak in run_flight(commands):
        final_altitude = current_altitude
        peak_altitude = running_peak
    return peak_altitude, final_altitude


def flight_log(commands):
    log_lines = []
    for action_name, duration_seconds, current_altitude, peak_altitude in run_flight(
        commands
    ):
        log_lines.append(
            "%-13s %4ds -> %5d ft (peak %5d ft)"
            % (action_name, duration_seconds, current_altitude, peak_altitude)
        )
    return log_lines


def main():
    flight_plan = [
        ("burner blast", 10),
        ("glide", 30),
        ("vent", 10),
        ("burner blast", 5),
        ("glide", 120),
    ]
    for log_line in flight_log(flight_plan):
        print(log_line)
    peak_altitude, final_altitude = simulate(flight_plan)
    print("peak altitude: %d ft" % peak_altitude)
    print("final altitude: %d ft" % final_altitude)


if __name__ == "__main__":
    main()

