def score_pairing(wine_acidity, dish_richness, has_flavor_contrast):
    raw_score = BASE_SYNERGY_SCORE - abs(wine_acidity - dish_richness)
    if has_flavor_contrast:
        raw_score += CONTRAST_BONUS
    return max(raw_score, 0)


def validate_pairing(pairing, pairing_index):
    if len(pairing) != 3:
        raise ValueError(
            "pairing %d must have exactly 3 elements" % pairing_index
        )
