    if not isinstance(wine_acidity, (int, float)):
        raise TypeError("pairing %d: wine acidity must be numeric" % pairing_index)
    if not isinstance(dish_richness, (int, float)):
        raise TypeError("pairing %d: dish richness must be numeric" % pairing_index)
    if not isinstance(has_flavor_contrast, bool):
        raise TypeError("pairing %d: contrast flag must be boolean" % pairing_index)
    return wine_acidity, dish_richness, has_flavor_contrast


def rate(pairings):
    total_score = 0
    exceptional_count = 0
    pairing_count = 0
    for pairing_index, pairing in enumerate(pairings):
        wine_acidity, dish_richness, has_flavor_contrast = validate_pairing(
            pairing, pairing_index
