BASE_MODIFIER = 32
RATING_SCALE_FACTOR = 400


def expected_win_probability(player_rating, opponent_rating):
    rating_difference = opponent_rating - player_rating
    return 1.0 / (1.0 + 10 ** (rating_difference / RATING_SCALE_FACTOR))


def validate_match_entry(match_entry, entry_index):
    if len(match_entry) != 3:
        raise ValueError("match %d must hold three values" % entry_index)
    player_rating, opponent_rating, match_result = match_entry
    if match_result not in (0, 1):
        raise ValueError("match %d has an invalid result: %r" % (entry_index, match_result))
    for rating_value in (player_rating, opponent_rating):
        if rating_value < 0:
            raise ValueError("match %d has a negative rating" % entry_index)
    return player_rating, opponent_rating, match_result


def rate(matches):
    updated_ratings = []
    for entry_index, match_entry in enumerate(matches):
        player_rating, opponent_rating, match_result = validate_match_entry(match_entry, entry_index)
        win_probability = expected_win_probability(player_rating, opponent_rating)
        rating_change = BASE_MODIFIER * (match_result - win_probability)
        updated_ratings.append(int(player_rating + rating_change))
    return updated_ratings


def build_tournament_report(matches, updated_ratings):
    report_lines = []
    for match_entry, new_rating in zip(matches, updated_ratings):
        starting_rating, opponent_rating, match_result = match_entry
        result_label = "win" if match_result == 1 else "loss"
        point_difference = new_rating - starting_rating
        report_lines.append(
            "%4d vs %4d (%4s): %4d -> %4d (%+d)"
            % (starting_rating, opponent_rating, result_label, starting_rating, new_rating, point_difference)
        )
