WINDOW_SIZE = 6
STABILITY_THRESHOLD = 0.5
FIRST_SCANNED_INDEX = 1
VALID_BASES = frozenset("ACGT")


def normalize_sequence(raw_sequence):
    cleaned_sequence = raw_sequence.strip().upper()
    invalid_bases = sorted(set(cleaned_sequence) - VALID_BASES)
    if invalid_bases:
        raise ValueError("unexpected bases: " + ", ".join(invalid_bases))
    return cleaned_sequence


def stability_score(substring):
    gc_count = 0
    for single_base in substring:
        if single_base in ("G", "C"):
            gc_count += 1
    return gc_count / len(substring)


def find(sequence):
    target_sequence = normalize_sequence(sequence)
    last_start_index = len(target_sequence) - WINDOW_SIZE
    promising_regions = []
    for start_index in range(FIRST_SCANNED_INDEX, last_start_index + 1):
        candidate_substring = target_sequence[start_index:start_index + WINDOW_SIZE]
        if stability_score(candidate_substring) > STABILITY_THRESHOLD:
            promising_regions.append((candidate_substring, start_index))
    return promising_regions


def summarize_regions(region_list):
    if not region_list:
        return {"region_count": 0, "mean_score": 0.0, "best_region": None}
    scored_regions = [(region, stability_score(region[0])) for region in region_list]
    total_score = sum(pair[1] for pair in scored_regions)
    best_pair = max(scored_regions, key=lambda pair: (pair[1], -pair[0][1]))
    return {
        "region_count": len(region_list),
        "mean_score": total_score / len(region_list),
        "best_region": best_pair[0],
    }


def format_report(sequence_name, region_list):
    report_lines = ["{}: {} promising region(s)".format(sequence_name, len(region_list))]
    for region_substring, start_index in region_list:
        report_lines.append(
            "  index {:>3}  {}  score={:.3f}".format(
                start_index, region_substring, stability_score(region_substring)
            )
        )
    region_summary = summarize_regions(region_list)
    if region_summary["best_region"] is not None:
        best_substring, best_index = region_summary["best_region"]
        report_lines.append(
            "  mean score {:.3f}, best {} at index {}".format(
                region_summary["mean_score"], best_substring, best_index
            )
        )
    return "\n".join(report_lines)


