WINDOW_SIZE = 6
STABILITY_THRESHOLD = 0.5
FIRST_SCANNED_INDEX = 1
VALID_BASES = frozenset("ACGT")


def normalizeSequence(rawSequence):
    cleanedSequence = rawSequence.strip().upper()
    invalidBases = sorted(set(cleanedSequence) - VALID_BASES)
    if invalidBases:
        raise ValueError("unexpected bases: " + ", ".join(invalidBases))
    return cleanedSequence


def stabilityScore(substring):
    gcCount = 0
    for singleBase in substring:
        if singleBase in ("G", "C"):
            gcCount += 1
    return gcCount / len(substring)


def find(sequence):
    targetSequence = normalizeSequence(sequence)
    lastStartIndex = len(targetSequence) - WINDOW_SIZE
    promisingRegions = []
    for startIndex in range(FIRST_SCANNED_INDEX, lastStartIndex + 1):
        candidateSubstring = targetSequence[startIndex:startIndex + WINDOW_SIZE]
        if stabilityScore(candidateSubstring) > STABILITY_THRESHOLD:
            promisingRegions.append((candidateSubstring, startIndex))
    return promisingRegions


def summarizeRegions(regionList):
    if not regionList:
        return {"region_count": 0, "mean_score": 0.0, "best_region": None}
    scoredRegions = [(region, stabilityScore(region[0])) for region in regionList]
    totalScore = sum(pair[1] for pair in scoredRegions)
    bestPair = max(scoredRegions, key=lambda pair: (pair[1], -pair[0][1]))
    return {
        "region_count": len(regionList),
        "mean_score": totalScore / len(regionList),
        "best_region": bestPair[0],
    }


def formatReport(sequenceName, regionList):
    reportLines = ["{}: {} promising region(s)".format(sequenceName, len(regionList))]
    for regionSubstring, startIndex in regionList:
        reportLines.append(
            "  index {:>3}  {}  score={:.3f}".format(
                startIndex, regionSubstring, stabilityScore(regionSubstring)
            )
        )
    regionSummary = summarizeRegions(regionList)
    if regionSummary["best_region"] is not None:
        bestSubstring, bestIndex = regionSummary["best_region"]
        reportLines.append(
            "  mean score {:.3f}, best {} at index {}".format(
                regionSummary["mean_score"], bestSubstring, bestIndex
            )
        )
    return "\n".join(reportLines)


def main():
    sampleSequences = {
        "sample_one": "ATGCGCAT",
        "sample_two": "aaattttaaa",
        "sample_three": "GGCCGGCCATATGCGCGC",
    }
    for sequenceName in sorted(sampleSequences):
        foundRegions = find(sampleSequences[sequenceName])
        print(formatReport(sequenceName, foundRegions))


if __name__ == "__main__":
    main()

