def validate_readings(reading_sequence):
    """Return the readings as a list of ints, rejecting malformed input."""
    if not isinstance(reading_sequence, (list, tuple)):
        raise TypeError("decibels must be a list of integer readings")
    validated_readings = []
    for minute_index, raw_reading in enumerate(reading_sequence):
        if isinstance(raw_reading, bool) or not isinstance(raw_reading, int):
            raise TypeError(
                "reading at minute {} is not an integer: {!r}".format(minute_index, raw_reading)
            )
        validated_readings.append(raw_reading)
    return validated_readings


def find_violation_spans(reading_list):
    """Locate half-open [start, end) spans that stay strictly above the threshold."""
    violation_spans = []
    span_start_index = None
    for current_minute, current_level in enumerate(reading_list):
        if current_level > VIOLATION_THRESHOLD:
            if span_start_index is None:
                span_start_index = current_minute
        elif span_start_index is not None:
            violation_spans.append((span_start_index, current_minute))
            span_start_index = None
    if span_start_index is not None:
        violation_spans.append((span_start_index, len(reading_list)))
    return violation_spans


