    for span_start, span_end in find_violation_spans(reading_list):
        span_duration = span_end - span_start
        if span_duration >= MIN_VIOLATION_LENGTH:
            peak_volumes.append(max(reading_list[span_start:span_end]))
    return peak_volumes


