        if span_duration < MIN_VIOLATION_LENGTH:
            continue
        span_readings = reading_list[span_start:span_end]
        peak_volume = max(span_readings)
        average_volume = sum(span_readings) / span_duration
        report_lines.append(
            "minutes {}-{} ({} min): peak {} dB, average {:.1f} dB".format(
                span_start, span_end - 1, span_duration, peak_volume, average_volume
            )
