def validate_amplitudes(raw_amplitudes):
    """Return the readings as a list of ints, rejecting malformed input."""
    if isinstance(raw_amplitudes, (str, bytes)):
        raise TypeError("amplitudes must be a sequence of integers, not text")
    checked_readings = []
    for reading_index, reading_value in enumerate(raw_amplitudes):
        if isinstance(reading_value, bool) or not isinstance(reading_value, int):
            raise TypeError(
                "reading at position {0} is not an integer: {1!r}".format(
                    reading_index, reading_value
                )
            )
        checked_readings.append(reading_value)
    return checked_readings


def rolling_average(window_readings):
    """Arithmetic mean of one window of preceding readings."""
    return sum(window_readings) / len(window_readings)


def find_spike_indices(checked_readings):
    """Positions whose value exceeds SPIKE_FACTOR times the rolling average."""
    spike_positions = []
    for current_index in range(WINDOW_SIZE, len(checked_readings)):
        preceding_window = checked_readings[current_index - WINDOW_SIZE:current_index]
        window_average = rolling_average(preceding_window)
        current_reading = checked_readings[current_index]
        if current_reading > SPIKE_FACTOR * window_average:
            spike_positions.append(current_index)
    return spike_positions


def analyze(amplitudes):
    """Count tremor spikes in a sequence of vibration amplitudes."""
    checked_readings = validate_amplitudes(amplitudes)
    return len(find_spike_indices(checked_readings))


def format_spike_report(amplitudes):
    """Human readable summary of every tremor spike in the series."""
    checked_readings = validate_amplitudes(amplitudes)
    spike_positions = find_spike_indices(checked_readings)
    report_lines = [
        "readings: {0}".format(len(checked_readings)),
        "tremor spikes: {0}".format(len(spike_positions)),
    ]
    for spike_index in spike_positions:
        window_average = rolling_average(
            checked_readings[spike_index - WINDOW_SIZE:spike_index]
        )
        report_lines.append(
            "  index {0}: amplitude {1} vs rolling average {2:.2f}".format(
                spike_index, checked_readings[spike_index], window_average
            )
        )
    return "\n".join(report_lines)


