from collections import deque

STRESS_THRESHOLD_CELSIUS = 30.0
ROLLING_WINDOW_WEEKS = 12
CRITICAL_SUM_LIMIT = 8.0
FLOAT_TOLERANCE = 1e-9


def validate_temperature_readings(raw_readings):
    """Convert the incoming sequence into a clean list of float readings."""
    if isinstance(raw_readings, (str, bytes)):
        raise TypeError("temperatures must be a sequence of numbers, not text")
    cleaned_readings = []
    for reading_position, raw_value in enumerate(raw_readings):
        if isinstance(raw_value, bool) or not isinstance(raw_value, (int, float)):
            raise TypeError(
                "temperature at week {0} is not numeric: {1!r}".format(reading_position, raw_value)
            )
        cleaned_readings.append(float(raw_value))
    return cleaned_readings


def compute_weekly_excess(temperature_value):
    """Degrees above the stress threshold for a single week (0 if at or below)."""
    excess_degrees = temperature_value - STRESS_THRESHOLD_CELSIUS
    if excess_degrees <= 0.0:
        return 0.0
    return excess_degrees


def evaluate(temperatures):
    """Return the week indices where the rolling 12-week stress sum is critical."""
    weekly_readings = validate_temperature_readings(temperatures)
    recent_excess_values = deque()
    rolling_excess_sum = 0.0
    critical_week_indices = []
    for week_index, temperature_value in enumerate(weekly_readings):
        weekly_excess = compute_weekly_excess(temperature_value)
        recent_excess_values.append(weekly_excess)
        rolling_excess_sum += weekly_excess
        if len(recent_excess_values) > ROLLING_WINDOW_WEEKS:
            expired_excess_value = recent_excess_values.popleft()
            rolling_excess_sum -= expired_excess_value
        if rolling_excess_sum >= CRITICAL_SUM_LIMIT - FLOAT_TOLERANCE:
            critical_week_indices.append(week_index)
    return critical_week_indices


def format_warning_report(temperatures, critical_week_indices):
    """Build a human readable report for one reef monitoring season."""
    weekly_readings = validate_temperature_readings(temperatures)
    total_weeks_observed = len(weekly_readings)
    report_lines = [
        "Weeks observed: {0}".format(total_weeks_observed),
        "Critical warnings: {0}".format(len(critical_week_indices)),
    ]
    if critical_week_indices:
        first_warning_week = critical_week_indices[0]
        report_lines.append("First warning at week index {0}".format(first_warning_week))
        for warning_index in critical_week_indices:
            warning_temperature = weekly_readings[warning_index]
            report_lines.append(
                "  week {0:>2}: {1:.1f} C (+{2:.1f})".format(
                    warning_index, warning_temperature, compute_weekly_excess(warning_temperature)
                )
            )
    else:
        report_lines.append("No critical stress accumulation detected")
    return "\n".join(report_lines)


def main():
    steady_hot_season = [31.0] * 12
    mixed_season = [29.5, 30.0, 31.5, 32.0, 28.0, 30.5, 33.0, 31.0, 30.0, 29.0, 34.0, 32.5, 31.0]
    for season_name, season_readings in (("steady hot", steady_hot_season), ("mixed", mixed_season)):
        warning_week_indices = evaluate(season_readings)
        print("=== {0} season ===".format(season_name))
        print(format_warning_report(season_readings, warning_week_indices))
        print()


if __name__ == "__main__":
    main()

