        if len(recentExcessValues) > ROLLING_WINDOW_WEEKS:
            expiredExcessValue = recentExcessValues.popleft()
            rollingExcessSum -= expiredExcessValue
        if rollingExcessSum >= CRITICAL_SUM_LIMIT - FLOAT_TOLERANCE:
            criticalWeekIndices.append(weekIndex)
    return criticalWeekIndices


def formatWarningReport(temperatures, criticalWeekIndices):
    """Build a human readable report for one reef monitoring season."""
    weeklyReadings = validateTemperatureReadings(temperatures)
    totalWeeksObserved = len(weeklyReadings)
    reportLines = [
        "Weeks observed: {0}".format(totalWeeksObserved),
        "Critical warnings: {0}".format(len(criticalWeekIndices)),
    ]
    if criticalWeekIndices:
        firstWarningWeek = criticalWeekIndices[0]
        reportLines.append("First warning at week index {0}".format(firstWarningWeek))
        for warningIndex in criticalWeekIndices:
            warningTemperature = weeklyReadings[warningIndex]
            reportLines.append(
                "  week {0:>2}: {1:.1f} C (+{2:.1f})".format(
                    warningIndex, warningTemperature, computeWeeklyExcess(warningTemperature)
                )
            )
    else:
        reportLines.append("No critical stress accumulation detected")
    return "\n".join(reportLines)


def main():
