    mixedSeason = [29.5, 30.0, 31.5, 32.0, 28.0, 30.5, 33.0, 31.0, 30.0, 29.0, 34.0, 32.5, 31.0]
    for seasonName, seasonReadings in (("steady hot", steadyHotSeason), ("mixed", mixedSeason)):
        warningWeekIndices = evaluate(seasonReadings)
        print("=== {0} season ===".format(seasonName))
        print(formatWarningReport(seasonReadings, warningWeekIndices))
        print()


