def classify_instrument(raw_instrument_name):
    normalized_name = normalize_instrument_name(raw_instrument_name)
    if normalized_name in FRONT_ROW_INSTRUMENTS:
        return "front"
    if normalized_name in MIDDLE_ROW_INSTRUMENTS:
        return "middle"
    if normalized_name in BACK_ROW_INSTRUMENTS:
        return "back"
    return "unassigned"


def count_by_row(musicians):
