    for single_instrument in musicians:
        target_row = classify_instrument(single_instrument)
        row_totals[target_row] += 1
    return row_totals


def split_row_overflow(row_member_count):
    if row_member_count > ROW_CAPACITY_LIMIT:
        excess_count = row_member_count - ROW_CAPACITY_LIMIT
        return ROW_CAPACITY_LIMIT, excess_count
    return row_member_count, 0


