    front_count, middle_count, back_count, overflow_count = arrange(musicians)
    report_lines = [
        "%s (%d players)" % (orchestra_name, len(musicians)),
        "  front row : %d" % front_count,
        "  middle row: %d" % middle_count,
        "  back row  : %d" % back_count,
        "  overflow  : %d" % overflow_count,
    ]
    return "\n".join(report_lines)


