MAX_SAFE_DESCENT_RATE = 15


def validate_readings(pressures):
    """Return the readings as a list of ints, rejecting malformed input."""
    if pressures is None:
        raise ValueError("no pressure readings supplied")
    validated_readings = []
    for reading_index, raw_reading in enumerate(pressures):
        if isinstance(raw_reading, bool) or not isinstance(raw_reading, int):
            raise TypeError(
                "reading %d is not an integer: %r" % (reading_index, raw_reading)
            )
        validated_readings.append(raw_reading)
    return validated_readings


def compute_descent_rates(pressures):
    """Difference between each consecutive pair of readings, one per minute."""
    descent_rate_list = []
    for minute_index in range(1, len(pressures)):
        previous_reading = pressures[minute_index - 1]
        current_reading = pressures[minute_index]
        descent_rate_list.append(current_reading - previous_reading)
    return descent_rate_list


def find_speed_violations(descent_rate_list):
    """Minute numbers (1-based) whose descent rate exceeds the safe limit."""
    violation_minutes = []
    for rate_index, descent_rate in enumerate(descent_rate_list):
        if descent_rate > MAX_SAFE_DESCENT_RATE:
            violation_minutes.append(rate_index + 1)
    return violation_minutes


def log(pressures):
    """Return (number of speed violations, maximum depth reached)."""
    validated_readings = validate_readings(pressures)
    if not validated_readings:
        return (0, 0)
    descent_rate_list = compute_descent_rates(validated_readings)
    violation_minutes = find_speed_violations(descent_rate_list)
    maximum_depth_reached = max(validated_readings)
    return (len(violation_minutes), maximum_depth_reached)


def format_dive_report(pressures):
    """Human readable summary of a single dive log."""
    validated_readings = validate_readings(pressures)
    violation_total, maximum_depth_reached = log(validated_readings)
    descent_rate_list = compute_descent_rates(validated_readings)
    violation_minutes = find_speed_violations(descent_rate_list)
    report_lines = [
        "readings taken: %d" % len(validated_readings),
        "maximum depth reached: %d atm" % maximum_depth_reached,
        "speed violations: %d" % violation_total,
    ]
    for violation_minute in violation_minutes:
        offending_rate = descent_rate_list[violation_minute - 1]
        report_lines.append(
            "  minute %d descended %d atm" % (violation_minute, offending_rate)
        )
    return "\n".join(report_lines)


def main():
    dive_logs = {
        "shallow survey": [1, 5, 10, 20, 35, 30],
        "trench run": [0, 10, 40, 80, 79, 100, 98],
        "station keeping": [12, 12, 12, 12],
    }
    for dive_name, pressure_readings in dive_logs.items():
        print(dive_name)
        print(format_dive_report(pressure_readings))
        print()


if __name__ == "__main__":
    main()

