def split_into_words(sentence_text):
    return [word_token for word_token in sentence_text.split(" ") if word_token != ""]


def count_positional_matches(new_words, reference_words):
    comparable_length = min(len(new_words), len(reference_words))
    matching_count = 0
    for word_index in range(comparable_length):
        if new_words[word_index] == reference_words[word_index]:
            matching_count += 1
    return matching_count


def similarity_ratio(new_sentence, reference_sentence):
    new_words = split_into_words(new_sentence)
    reference_words = split_into_words(reference_sentence)
    total_new_words = len(new_words)
    if total_new_words == 0:
        return 0.0
    matching_count = count_positional_matches(new_words, reference_words)
    return matching_count / total_new_words


def match(segments):
    ratio_list = []
    for segment_pair in segments:
        new_sentence, reference_sentence = segment_pair
        ratio_list.append(similarity_ratio(new_sentence, reference_sentence))
    return ratio_list


def classify_ratio(ratio_value):
    if ratio_value >= 1.0:
        return "exact"
    if ratio_value >= 0.75:
        return "high"
    if ratio_value > 0.0:
        return "partial"
    return "none"


def build_report_lines(segments, ratio_list):
    report_lines = []
    for segment_index, ratio_value in enumerate(ratio_list):
        new_sentence = segments[segment_index][0]
        percentage_value = ratio_value * 100
        match_label = classify_ratio(ratio_value)
        report_lines.append(
            "{0:>2}. {1:6.2f}%  {2:<8} {3}".format(
                segment_index + 1, percentage_value, match_label, new_sentence
            )
        )
    return report_lines


def average_ratio(ratio_list):
    if len(ratio_list) == 0:
        return 0.0
    return sum(ratio_list) / len(ratio_list)


def main():
    segment_pairs = [
        ("the cat sat on the mat", "the cat sat on the mat"),
        ("the cat sat on the mat", "the dog sat on the rug"),
        ("a brand new sentence here", "nothing alike at all here"),
        ("short line", "a completely different line entirely"),
    ]
    ratio_list = match(segment_pairs)
    for report_line in build_report_lines(segment_pairs, ratio_list):
        print(report_line)
    overall_average = average_ratio(ratio_list)
    print("average similarity: {0:.4f}".format(overall_average))


if __name__ == "__main__":
