import math

LAUNCH_VELOCITY = 50.0
GRAVITY_CONSTANT = 9.8


def maximum_theoretical_range(launch_velocity=LAUNCH_VELOCITY, gravity_constant=GRAVITY_CONSTANT):
    """Greatest distance reachable, obtained at a forty-five degree elevation."""
    return (launch_velocity ** 2) / gravity_constant


def required_launch_angle(target_distance, launch_velocity=LAUNCH_VELOCITY, gravity_constant=GRAVITY_CONSTANT):
    """Return the low-arc firing angle in degrees for a single target distance."""
    sine_of_double_angle = (target_distance * gravity_constant) / (launch_velocity ** 2)
    angle_in_radians = 0.5 * math.asin(sine_of_double_angle)
    return math.degrees(angle_in_radians)


def is_reachable_target(target_distance, max_range_value):
    """A target counts as reachable when it lies between the muzzle and the maximum range."""
    return 0 <= target_distance <= max_range_value


def shoot(targets):
    max_range_value = maximum_theoretical_range()
    valid_angle_list = []
    for target_distance in targets:
        if is_reachable_target(target_distance, max_range_value):
            exact_angle = required_launch_angle(target_distance)
            valid_angle_list.append(int(round(exact_angle)))
    return valid_angle_list


def parse_target_input(raw_input_text):
    """Turn a whitespace or comma separated string of distances into a list of floats."""
    normalised_text = raw_input_text.replace(",", " ")
    parsed_distance_list = []
    for distance_token in normalised_text.split():
        parsed_distance_list.append(float(distance_token))
    return parsed_distance_list


def build_firing_report(target_list):
    """Pair each requested distance with its firing solution, or a rejection note."""
    max_range_value = maximum_theoretical_range()
    report_line_list = []
    for target_distance in target_list:
        if is_reachable_target(target_distance, max_range_value):
            firing_angle = int(round(required_launch_angle(target_distance)))
            report_line_list.append("{:8.1f} m -> {:3d} degrees".format(target_distance, firing_angle))
        else:
            report_line_list.append("{:8.1f} m -> out of bounds".format(target_distance))
    return report_line_list


def main():
    raw_input_text = "0, 120, 200, 255.1, 254, 300, -40"
    requested_target_list = parse_target_input(raw_input_text)
    max_range_value = maximum_theoretical_range()

    print("Maximum theoretical range: {:.2f} m".format(max_range_value))
    for report_line in build_firing_report(requested_target_list):
        print(report_line)

    resolved_angle_list = shoot(requested_target_list)
    rejected_count = len(requested_target_list) - len(resolved_angle_list)
    print("Firing solutions: {}".format(resolved_angle_list))
    print("Targets ignored as out of bounds: {}".format(rejected_count))


if __name__ == "__main__":
    main()

