import math


oxygen_burn_rate = 2.0


def validate_segment(segment_entry, segment_index):
    if len(segment_entry) != 2:
        raise ValueError(
            "segment {0} must hold an angle and a length".format(segment_index)
        )
    angle_degrees, section_length = segment_entry
    if section_length < 0:
        raise ValueError(
            "segment {0} has a negative length".format(segment_index)
        )
    return float(angle_degrees), float(section_length)


def descent_for_segment(angle_degrees, section_length):
    return math.sin(math.radians(angle_degrees)) * section_length


def oxygen_for_segment(section_length):
    return section_length * oxygen_burn_rate


def explore(segments):
    cumulative_depth = 0.0
    total_oxygen_used = 0.0
    for segment_index, segment_entry in enumerate(segments):
        angle_degrees, section_length = validate_segment(segment_entry, segment_index)
        cumulative_depth += descent_for_segment(angle_degrees, section_length)
        total_oxygen_used += oxygen_for_segment(section_length)
    return int(cumulative_depth), total_oxygen_used


def build_dive_report(segments):
    report_lines = []
    running_depth = 0.0
    for segment_index, segment_entry in enumerate(segments, start=1):
        angle_degrees, section_length = validate_segment(segment_entry, segment_index)
        segment_descent = descent_for_segment(angle_degrees, section_length)
        running_depth += segment_descent
        report_lines.append(
            "section {0:>2}: {1:5.1f} deg over {2:6.1f} m -> descent {3:7.2f} m, "
            "depth {4:7.2f} m".format(
                segment_index,
                angle_degrees,
