import math


oxygenBurnRate = 2.0


def validateSegment(segmentEntry, segmentIndex):
    if len(segmentEntry) != 2:
        raise ValueError(
            "segment {0} must hold an angle and a length".format(segmentIndex)
        )
    angleDegrees, sectionLength = segmentEntry
    if sectionLength < 0:
        raise ValueError(
            "segment {0} has a negative length".format(segmentIndex)
        )
    return float(angleDegrees), float(sectionLength)


def descentForSegment(angleDegrees, sectionLength):
    return math.sin(math.radians(angleDegrees)) * sectionLength


def oxygenForSegment(sectionLength):
    return sectionLength * oxygenBurnRate


def explore(segments):
    cumulativeDepth = 0.0
    totalOxygenUsed = 0.0
    for segmentIndex, segmentEntry in enumerate(segments):
        angleDegrees, sectionLength = validateSegment(segmentEntry, segmentIndex)
        cumulativeDepth += descentForSegment(angleDegrees, sectionLength)
        totalOxygenUsed += oxygenForSegment(sectionLength)
    return int(cumulativeDepth), totalOxygenUsed


def buildDiveReport(segments):
    reportLines = []
    runningDepth = 0.0
    for segmentIndex, segmentEntry in enumerate(segments, start=1):
        angleDegrees, sectionLength = validateSegment(segmentEntry, segmentIndex)
        segmentDescent = descentForSegment(angleDegrees, sectionLength)
        runningDepth += segmentDescent
        reportLines.append(
            "section {0:>2}: {1:5.1f} deg over {2:6.1f} m -> descent {3:7.2f} m, "
            "depth {4:7.2f} m".format(
