GAME_END_SECONDS = 3600


def track(events):
    """Return total playtime per player, ordered by player identification number."""
    active_start_times = {}
    accumulated_totals = {}

    for player_id, action_name, time_stamp in events:
        accumulated_totals.setdefault(player_id, 0)
        if action_name == "on":
            active_start_times[player_id] = time_stamp
        elif action_name == "off":
            shift_start_time = active_start_times.pop(player_id, None)
            if shift_start_time is None:
                raise ValueError(
                    "player {0} went off without going on".format(player_id)
                )
            accumulated_totals[player_id] += time_stamp - shift_start_time
        else:
            raise ValueError("unknown action: {0}".format(action_name))

    for player_id, shift_start_time in active_start_times.items():
        accumulated_totals[player_id] += GAME_END_SECONDS - shift_start_time

    return [accumulated_totals[player_id] for player_id in sorted(accumulated_totals)]


def validate_events(event_list):
    """Check the raw event records and return them sorted by time stamp."""
    for event_record in event_list:
        if len(event_record) != 3:
            raise ValueError("each event needs an id, an action and a time")
        player_id, action_name, time_stamp = event_record
        if not isinstance(time_stamp, int) or time_stamp < 0:
            raise ValueError("bad time stamp for player {0}".format(player_id))
        if time_stamp > GAME_END_SECONDS:
            raise ValueError("time stamp beyond the end of the game")
    return sorted(event_list, key=lambda event_record: event_record[2])


def format_duration(total_seconds):
    """Render a duration in seconds as minutes and seconds."""
    whole_minutes, leftover_seconds = divmod(total_seconds, 60)
    return "{0:d}:{1:02d}".format(whole_minutes, leftover_seconds)


def build_report(event_list):
    """Produce report lines pairing each player identification number with playtime."""
    checked_events = validate_events(event_list)
    player_ids = sorted({event_record[0] for event_record in checked_events})
    playtime_totals = track(checked_events)

    report_lines = []
    for player_id, total_seconds in zip(player_ids, playtime_totals):
        report_lines.append(
            "player {0}: {1} ({2} s)".format(
                player_id, format_duration(total_seconds), total_seconds
            )
        )
    return report_lines


def main():
    game_events = [
        (3, "on", 0),
        (7, "on", 0),
        (3, "off", 900),
        (11, "on", 900),
        (7, "off", 1800),
        (3, "on", 2400),
        (11, "off", 3000),
    ]

    for report_line in build_report(game_events):
        print(report_line)

    longest_total = max(track(game_events))
    print("longest shift total: {0}".format(format_duration(longest_total)))


if __name__ == "__main__":
    main()

