IDEAL_TEMPERATURE = 18
LOWER_COMFORT_LIMIT = 16
UPPER_COMFORT_LIMIT = 20
CRITICAL_THRESHOLD = 25
MINUTES_PER_READING = 60


def parse_reading_line(raw_line):
    parsed_readings = []
    for raw_token in raw_line.replace(",", " ").split():
        parsed_readings.append(int(raw_token))
    return parsed_readings


def validate_readings(temperatures):
    validated_readings = []
    for reading_index, single_reading in enumerate(temperatures):
        if isinstance(single_reading, bool) or not isinstance(single_reading, int):
            raise TypeError(
                "reading %d is not an integer: %r" % (reading_index, single_reading)
            )
        validated_readings.append(single_reading)
    return validated_readings


def control(temperatures):
    checked_readings = validate_readings(temperatures)
    heating_minutes = 0
    cooling_minutes = 0
    alert_fired = False
    for current_reading in checked_readings:
        if current_reading < LOWER_COMFORT_LIMIT:
            heating_minutes += MINUTES_PER_READING
        elif current_reading > UPPER_COMFORT_LIMIT:
            cooling_minutes += MINUTES_PER_READING
        if current_reading > CRITICAL_THRESHOLD:
            alert_fired = True
    return heating_minutes, cooling_minutes, alert_fired


def average_deviation(temperatures):
    deviation_sum = sum(abs(reading - IDEAL_TEMPERATURE) for reading in temperatures)
    reading_count = len(temperatures)
    if reading_count == 0:
        return 0.0
    return deviation_sum / reading_count


def format_report(temperatures):
    heating_minutes, cooling_minutes, alert_fired = control(temperatures)
    mean_deviation = average_deviation(temperatures)
    report_lines = [
        "readings analysed: %d" % len(temperatures),
        "heating minutes:   %d" % heating_minutes,
        "cooling minutes:   %d" % cooling_minutes,
        "mean deviation:    %.2f degrees" % mean_deviation,
    ]
    if alert_fired:
        report_lines.append("CRITICAL ALERT: temperature exceeded %d degrees"
                            % CRITICAL_THRESHOLD)
    else:
        report_lines.append("no critical alert raised")
    return "\n".join(report_lines)


def main():
    sample_batches = {
        "cellar north": "18 17 19 18 18 20",
        "cellar south": "15 14 18 21 22 18",
        "loft store": "18 19 24 26 27 21",
    }
    for batch_name, raw_line in sample_batches.items():
        hourly_readings = parse_reading_line(raw_line)
        print("=== %s ===" % batch_name)
        print(format_report(hourly_readings))
        print()


if __name__ == "__main__":
