def squad_name_for(player_identifier):
    if player_identifier % 2 == 0:
        return "blue"
    return "red"


def validate_hit_record(hit_record):
    shooter_identifier, target_identifier, zone_name = hit_record
    if not isinstance(shooter_identifier, int) or not isinstance(target_identifier, int):
        raise ValueError("player identifiers must be integers")
    if zone_name not in ZONE_POINT_TABLE:
        raise ValueError("unknown zone: {}".format(zone_name))
    return shooter_identifier, target_identifier, zone_name


def score(hits):
    score_by_player = {}
    for hit_record in hits:
        shooter_identifier, target_identifier, zone_name = validate_hit_record(hit_record)
        score_by_player.setdefault(shooter_identifier, 0)
        score_by_player.setdefault(target_identifier, 0)
        if squad_name_for(shooter_identifier) == squad_name_for(target_identifier):
            score_by_player[shooter_identifier] -= SAME_SQUAD_PENALTY
        else:
            score_by_player[shooter_identifier] += ZONE_POINT_TABLE[zone_name]
    sorted_player_ids = sorted(score_by_player)
    return [score_by_player[player_identifier] for player_identifier in sorted_player_ids]


def squad_totals(hits):
    player_scores = score(hits)
    sorted_player_ids = sorted({identifier for hit_record in hits for identifier in hit_record[:2]})
    totals_per_squad = {"blue": 0, "red": 0}
    for player_identifier, player_total in zip(sorted_player_ids, player_scores):
        totals_per_squad[squad_name_for(player_identifier)] += player_total
    return totals_per_squad


def format_scoreboard(hits):
    player_scores = score(hits)
    sorted_player_ids = sorted({identifier for hit_record in hits for identifier in hit_record[:2]})
    report_lines = ["id  squad  points"]
    for player_identifier, player_total in zip(sorted_player_ids, player_scores):
        report_lines.append(
            "{:<4}{:<7}{:>6}".format(player_identifier, squad_name_for(player_identifier), player_total)
        )
    totals_per_squad = squad_totals(hits)
    for squad_label in ("blue", "red"):
        report_lines.append("{} squad total: {}".format(squad_label, totals_per_squad[squad_label]))
