import math

WAVE_SPEED_KMPS = 5.0
GRID_MINIMUM = 0
GRID_MAXIMUM = 100
GRID_STEP = 0.5


def validate_stations(station_records):
    if len(station_records) < 3:
        raise ValueError("at least three stations are required for triangulation")
    validated_records = []
    for record_index, single_record in enumerate(station_records):
        if len(single_record) != 3:
            raise ValueError("station %d must have x, y and arrival time" % record_index)
        horizontal_coordinate, vertical_coordinate, arrival_time = single_record
        if arrival_time < 0:
            raise ValueError("station %d has a negative arrival time" % record_index)
        validated_records.append(
            (float(horizontal_coordinate), float(vertical_coordinate), float(arrival_time))
        )
    return validated_records


def compute_observed_delays(station_records):
    earliest_arrival = min(arrival_time for _, _, arrival_time in station_records)
    return [arrival_time - earliest_arrival for _, _, arrival_time in station_records]


def compute_theoretical_delays(candidate_x, candidate_y, station_records):
    travel_times = []
    for station_x, station_y, _ in station_records:
        distance_to_station = math.hypot(station_x - candidate_x, station_y - candidate_y)
        travel_times.append(distance_to_station / WAVE_SPEED_KMPS)
    fastest_travel_time = min(travel_times)
    return [travel_time - fastest_travel_time for travel_time in travel_times]


def residual_error(candidate_x, candidate_y, station_records, observed_delays):
    theoretical_delays = compute_theoretical_delays(candidate_x, candidate_y, station_records)
    error_total = 0.0
    for theoretical_delay, observed_delay in zip(theoretical_delays, observed_delays):
        error_total += abs(theoretical_delay - observed_delay)
    return error_total


def triangulate(stations):
    station_records = validate_stations(stations)
    observed_delays = compute_observed_delays(station_records)
    grid_point_count = int((GRID_MAXIMUM - GRID_MINIMUM) / GRID_STEP) + 1
    best_error_value = float("inf")
    best_x_coordinate = GRID_MINIMUM
    best_y_coordinate = GRID_MINIMUM
    for x_index in range(grid_point_count):
        candidate_x = GRID_MINIMUM + x_index * GRID_STEP
        for y_index in range(grid_point_count):
            candidate_y = GRID_MINIMUM + y_index * GRID_STEP
            current_error = residual_error(
                candidate_x, candidate_y, station_records, observed_delays
            )
            if current_error < best_error_value:
                best_error_value = current_error
                best_x_coordinate = candidate_x
                best_y_coordinate = candidate_y
    return (best_x_coordinate, best_y_coordinate)


def format_epicenter_report(station_records, estimated_origin):
    origin_x, origin_y = estimated_origin
    report_lines = ["estimated origin: (%.1f, %.1f)" % (origin_x, origin_y)]
    for station_x, station_y, arrival_time in station_records:
        distance_to_origin = math.hypot(station_x - origin_x, station_y - origin_y)
        predicted_travel_time = distance_to_origin / WAVE_SPEED_KMPS
        report_lines.append(
            "station (%.1f, %.1f): observed %.2fs, travel %.2fs"
            % (station_x, station_y, arrival_time, predicted_travel_time)
        )
    return "\n".join(report_lines)


def main():
    measured_stations = [
        (0.0, 0.0, 12.0),
        (100.0, 0.0, 10.0),
        (50.0, 100.0, 8.0),
        (0.0, 100.0, 11.0),
    ]
    estimated_origin = triangulate(measured_stations)
    print(format_epicenter_report(validate_stations(measured_stations), estimated_origin))


if __name__ == "__main__":
    main()

