        horizontalCoordinate, verticalCoordinate, arrivalTime = singleRecord
        if arrivalTime < 0:
            raise ValueError("station %d has a negative arrival time" % recordIndex)
        validatedRecords.append(
            (float(horizontalCoordinate), float(verticalCoordinate), float(arrivalTime))
        )
    return validatedRecords


def computeObservedDelays(stationRecords):
    earliestArrival = min(arrivalTime for _, _, arrivalTime in stationRecords)
    return [arrivalTime - earliestArrival for _, _, arrivalTime in stationRecords]


def computeTheoreticalDelays(candidateX, candidateY, stationRecords):
    travelTimes = []
    for stationX, stationY, _ in stationRecords:
        distanceToStation = math.hypot(stationX - candidateX, stationY - candidateY)
        travelTimes.append(distanceToStation / WAVE_SPEED_KMPS)
    fastestTravelTime = min(travelTimes)
    return [travelTime - fastestTravelTime for travelTime in travelTimes]


def residualError(candidateX, candidateY, stationRecords, observedDelays):
    theoreticalDelays = computeTheoreticalDelays(candidateX, candidateY, stationRecords)
    errorTotal = 0.0
    for theoreticalDelay, observedDelay in zip(theoreticalDelays, observedDelays):
        errorTotal += abs(theoreticalDelay - observedDelay)
    return errorTotal


def triangulate(stations):
    stationRecords = validateStations(stations)
    observedDelays = computeObservedDelays(stationRecords)
    gridPointCount = int((GRID_MAXIMUM - GRID_MINIMUM) / GRID_STEP) + 1
    bestErrorValue = float("inf")
    bestXCoordinate = GRID_MINIMUM
    bestYCoordinate = GRID_MINIMUM
    for xIndex in range(gridPointCount):
        candidateX = GRID_MINIMUM + xIndex * GRID_STEP
        for yIndex in range(gridPointCount):
            candidateY = GRID_MINIMUM + yIndex * GRID_STEP
            currentError = residualError(
                candidateX, candidateY, stationRecords, observedDelays
            )
            if currentError < bestErrorValue:
                bestErrorValue = currentError
                bestXCoordinate = candidateX
                bestYCoordinate = candidateY
    return (bestXCoordinate, bestYCoordinate)


def formatEpicenterReport(stationRecords, estimatedOrigin):
    originX, originY = estimatedOrigin
    reportLines = ["estimated origin: (%.1f, %.1f)" % (originX, originY)]
    for stationX, stationY, arrivalTime in stationRecords:
        distanceToOrigin = math.hypot(stationX - originX, stationY - originY)
        predictedTravelTime = distanceToOrigin / WAVE_SPEED_KMPS
        reportLines.append(
            "station (%.1f, %.1f): observed %.2fs, travel %.2fs"
            % (stationX, stationY, arrivalTime, predictedTravelTime)
        )
    return "\n".join(reportLines)


def main():
    measuredStations = [
        (0.0, 0.0, 12.0),
        (100.0, 0.0, 10.0),
        (50.0, 100.0, 8.0),
        (0.0, 100.0, 11.0),
    ]
    estimatedOrigin = triangulate(measuredStations)
    print(formatEpicenterReport(validateStations(measuredStations), estimatedOrigin))


if __name__ == "__main__":
    main()

