    return total_time / len(timestamp_list)


def compute_maneuver_penalty(timestamp_list):
    average_timestamp = compute_average_timestamp(timestamp_list)
    penalty_total = 0.0
    for athlete_timestamp in timestamp_list:
        penalty_total += abs(athlete_timestamp - average_timestamp)
    return penalty_total


def validate_maneuver(timestamp_list, maneuver_index):
    if len(timestamp_list) != 4:
        raise ValueError(
            "maneuver %d must contain exactly four timestamps" % maneuver_index
        )
    for athlete_number, athlete_timestamp in enumerate(timestamp_list, start=1):
        if not isinstance(athlete_timestamp, (int, float)):
            raise TypeError(
                "maneuver %d, athlete %d: timestamp is not numeric"
                % (maneuver_index, athlete_number)
            )
        if athlete_timestamp < 0:
            raise ValueError(
                "maneuver %d, athlete %d: timestamp is negative"
                % (maneuver_index, athlete_number)
            )


def judge(movements):
    starting_score = 100.0
    accumulated_penalty = 0.0
    for maneuver_index, timestamp_list in enumerate(movements, start=1):
        validate_maneuver(timestamp_list, maneuver_index)
        accumulated_penalty += compute_maneuver_penalty(timestamp_list)
    return starting_score - accumulated_penalty


