def extract_carrier_block(frequency_request):
    """Return the first three digits of a frequency request in megahertz."""
    digit_text = str(abs(frequency_request))
    leading_digits = digit_text[:3]
    return int(leading_digits)


def parse_request_text(raw_request_text):
    """Turn a whitespace or comma separated listing into integer requests."""
    normalised_text = raw_request_text.replace(",", " ")
    parsed_requests = []
    for token_text in normalised_text.split():
        stripped_token = token_text.strip()
        if not stripped_token.lstrip("-").isdigit():
            raise ValueError("not a frequency in megahertz: %s" % stripped_token)
        parsed_requests.append(int(stripped_token))
    return parsed_requests


def allocate(frequencies):
    """Sort transmission requests into low band, high band and interference."""
    low_band_count = 0
    high_band_count = 0
    interference_count = 0
    for frequency_request in frequencies:
        if not isinstance(frequency_request, int) or isinstance(frequency_request, bool):
            raise TypeError("frequency requests must be integers")
        if frequency_request == 0:
            interference_count += 1
            continue
        carrier_block = extract_carrier_block(frequency_request)
        if carrier_block < 500:
            low_band_count += 1
        else:
            high_band_count += 1
    return (low_band_count, high_band_count, interference_count)


def format_allocation_report(allocation_result, total_request_count):
    """Build a human readable summary of one allocation run."""
    low_band_count, high_band_count, interference_count = allocation_result
    assigned_count = low_band_count + high_band_count
    report_lines = [
        "requests received : %d" % total_request_count,
        "low band spectrum : %d" % low_band_count,
        "high band spectrum: %d" % high_band_count,
        "interference      : %d" % interference_count,
    ]
    if assigned_count:
        high_band_share = 100.0 * high_band_count / assigned_count
        report_lines.append("high band share   : %.1f%%" % high_band_share)
    return "\n".join(report_lines)


def main():
    raw_request_text = "123456, 750900, 499999, 0, 5001234, 86, 0, 320450, 612000"
    frequency_requests = parse_request_text(raw_request_text)
    allocation_result = allocate(frequency_requests)
    print(format_allocation_report(allocation_result, len(frequency_requests)))
    for frequency_request in frequency_requests:
        if frequency_request == 0:
            band_label = "invalid"
        elif extract_carrier_block(frequency_request) < 500:
            band_label = "low"
        else:
            band_label = "high"
        print("%9d MHz -> %s" % (frequency_request, band_label))


if __name__ == "__main__":
    main()

