def parse_note_sequence(raw_text):
    """Convert whitespace- or comma-separated key positions into a list of ints."""
    cleaned_text = raw_text.replace(",", " ")
    parsed_notes = []
    for token_value in cleaned_text.split():
        parsed_notes.append(int(token_value))
    return parsed_notes


def validate_note_positions(notes, lowest_key=1, highest_key=88):
    """Raise ValueError if any key position falls outside the keyboard range."""
    for note_index, key_position in enumerate(notes):
        if key_position < lowest_key or key_position > highest_key:
            raise ValueError(
                "key position %d at index %d is outside the range %d-%d"
                % (key_position, note_index, lowest_key, highest_key)
            )
    return notes


def evaluate(notes):
    """Count consecutive intervals wider than twelve keys and find the widest one."""
    wide_stretch_count = 0
    max_distance_found = 0
    for pair_index in range(1, len(notes)):
        previous_key = notes[pair_index - 1]
        current_key = notes[pair_index]
        interval_distance = abs(current_key - previous_key)
        if interval_distance > 12:
            wide_stretch_count += 1
        if interval_distance > max_distance_found:
            max_distance_found = interval_distance
    return wide_stretch_count, max_distance_found


def describe_difficulty(wide_stretch_count, max_distance_found):
    """Turn the evaluation result into a short human-readable verdict."""
    if max_distance_found > 16:
        return "extreme: requires jumping or redistribution"
    if wide_stretch_count > 0:
        return "demanding: contains %d wide stretch(es)" % wide_stretch_count
    return "comfortable: every interval fits within an octave plus a fourth"


def build_report(piece_title, notes):
    """Produce the formatted analysis lines for a single piece."""
    validate_note_positions(notes)
    wide_stretch_count, max_distance_found = evaluate(notes)
    report_lines = [
        "%s (%d notes)" % (piece_title, len(notes)),
        "  wide stretches : %d" % wide_stretch_count,
        "  widest interval: %d keys" % max_distance_found,
        "  verdict        : %s" % describe_difficulty(wide_stretch_count, max_distance_found),
    ]
    return "\n".join(report_lines)


def main():
    piece_catalogue = [
        ("Etude in C", "40 44 47 52 40 36"),
        ("Left-hand Waltz", "28, 40, 47, 28, 45, 52"),
        ("Chromatic Warm-up", "60 61 62 63 64 65"),
    ]
    for piece_title, raw_text in piece_catalogue:
        note_sequence = parse_note_sequence(raw_text)
        print(build_report(piece_title, note_sequence))


if __name__ == "__main__":
    main()

