PERFECT_LIMIT_MS = 10
GOOD_LIMIT_MS = 30
PERFECT_BASE_POINTS = 100
GOOD_BASE_POINTS = 50
HITS_PER_MULTIPLIER_STEP = 5


def classify_hit(timing_difference):
    """Return the hit category for a single note timing difference."""
    if timing_difference < PERFECT_LIMIT_MS:
        return "perfect"
    if timing_difference <= GOOD_LIMIT_MS:
        return "good"
    return "miss"


def base_points_for(hit_category):
    """Return the unmultiplied point value awarded by a hit category."""
    if hit_category == "perfect":
        return PERFECT_BASE_POINTS
    if hit_category == "good":
        return GOOD_BASE_POINTS
    return 0


def score(notes):
    total_score = 0
    current_multiplier = 1
    highest_multiplier = 1
    consecutive_hit_count = 0
    for timing_difference in notes:
        hit_category = classify_hit(abs(timing_difference))
        if hit_category == "miss":
            current_multiplier = 1
            consecutive_hit_count = 0
            continue
        awarded_points = base_points_for(hit_category) * current_multiplier
        total_score += awarded_points
        consecutive_hit_count += 1
        if consecutive_hit_count % HITS_PER_MULTIPLIER_STEP == 0:
            current_multiplier += 1
            if current_multiplier > highest_multiplier:
                highest_multiplier = current_multiplier
    return total_score, highest_multiplier


def parse_timing_input(raw_text):
    """Turn whitespace or comma separated numbers into a list of timings."""
    timing_list = []
    for raw_token in raw_text.replace(",", " ").split():
        try:
            timing_value = float(raw_token)
        except ValueError:
            raise ValueError("not a valid note timing: %r" % raw_token)
        timing_list.append(timing_value)
    return timing_list


def format_score_report(total_score, highest_multiplier, note_count):
    report_lines = [
        "notes played: %d" % note_count,
        "total score: %d" % total_score,
        "best multiplier: x%d" % highest_multiplier,
    ]
    return "\n".join(report_lines)


def main():
    import sys

    raw_input_text = sys.stdin.read()
    try:
        note_timings = parse_timing_input(raw_input_text)
    except ValueError as parse_error:
        print("input error: %s" % parse_error)
        return 1
    total_score, highest_multiplier = score(note_timings)
    print(format_score_report(total_score, highest_multiplier, len(note_timings)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

