def validate_comic_entry(comic_entry):
    """Check one appraisal record and return its normalised numeric fields."""
    if len(comic_entry) != 3:
        raise ValueError("each comic needs a base value, crease count and tear length")
    base_dollar_value, creased_page_count, cover_tear_length = comic_entry
    if base_dollar_value < 0:
        raise ValueError("base dollar value cannot be negative")
    if creased_page_count < 0:
        raise ValueError("creased page count cannot be negative")
    if cover_tear_length < 0:
        raise ValueError("cover tear length cannot be negative")
    return float(base_dollar_value), int(creased_page_count), float(cover_tear_length)


def compute_crease_deduction(base_dollar_value, creased_page_count):
    """Two percent of the base value for every creased page."""
    return base_dollar_value * 0.02 * creased_page_count


def compute_tear_deduction(base_dollar_value, cover_tear_length):
    """Five percent of the base value for every half inch of cover tear."""
    half_inch_units = cover_tear_length / 0.5
    return base_dollar_value * 0.05 * half_inch_units


def appraise(comics):
    total_appraisal_value = 0.0
    highest_condition_deduction = 0.0
    for comic_entry in comics:
        base_dollar_value, creased_page_count, cover_tear_length = validate_comic_entry(comic_entry)
        crease_deduction = compute_crease_deduction(base_dollar_value, creased_page_count)
        tear_deduction = compute_tear_deduction(base_dollar_value, cover_tear_length)
        total_condition_deduction = crease_deduction + tear_deduction
        if total_condition_deduction > base_dollar_value * 0.5:
            final_appraisal_value = 0.0
        else:
            final_appraisal_value = base_dollar_value - total_condition_deduction
        total_appraisal_value += final_appraisal_value
        if total_condition_deduction > highest_condition_deduction:
            highest_condition_deduction = total_condition_deduction
    return total_appraisal_value, highest_condition_deduction


def format_appraisal_report(comic_collection):
