def validateComicEntry(comicEntry):
    """Check one appraisal record and return its normalised numeric fields."""
    if len(comicEntry) != 3:
        raise ValueError("each comic needs a base value, crease count and tear length")
    baseDollarValue, creasedPageCount, coverTearLength = comicEntry
    if baseDollarValue < 0:
        raise ValueError("base dollar value cannot be negative")
    if creasedPageCount < 0:
        raise ValueError("creased page count cannot be negative")
    if coverTearLength < 0:
        raise ValueError("cover tear length cannot be negative")
    return float(baseDollarValue), int(creasedPageCount), float(coverTearLength)


def computeCreaseDeduction(baseDollarValue, creasedPageCount):
    """Two percent of the base value for every creased page."""
    return baseDollarValue * 0.02 * creasedPageCount


def computeTearDeduction(baseDollarValue, coverTearLength):
    """Five percent of the base value for every half inch of cover tear."""
    halfInchUnits = coverTearLength / 0.5
    return baseDollarValue * 0.05 * halfInchUnits


def appraise(comics):
    totalAppraisalValue = 0.0
    highestConditionDeduction = 0.0
    for comicEntry in comics:
        baseDollarValue, creasedPageCount, coverTearLength = validateComicEntry(comicEntry)
        creaseDeduction = computeCreaseDeduction(baseDollarValue, creasedPageCount)
        tearDeduction = computeTearDeduction(baseDollarValue, coverTearLength)
        totalConditionDeduction = creaseDeduction + tearDeduction
        if totalConditionDeduction > baseDollarValue * 0.5:
            finalAppraisalValue = 0.0
        else:
            finalAppraisalValue = baseDollarValue - totalConditionDeduction
        totalAppraisalValue += finalAppraisalValue
        if totalConditionDeduction > highestConditionDeduction:
            highestConditionDeduction = totalConditionDeduction
    return totalAppraisalValue, highestConditionDeduction


def formatAppraisalReport(comicCollection):
    """Build a per-comic breakdown plus the collection totals as text lines."""
    reportLines = []
    for entryIndex, comicEntry in enumerate(comicCollection, start=1):
        singleComicTotal, singleComicDeduction = appraise([comicEntry])
        reportLines.append(
            "Comic {0}: value ${1:.2f}, condition deduction ${2:.2f}".format(
                entryIndex, singleComicTotal, singleComicDeduction
            )
        )
    collectionValue, worstDeduction = appraise(comicCollection)
    reportLines.append("Collection value: ${0:.2f}".format(collectionValue))
    reportLines.append("Worst condition deduction: ${0:.2f}".format(worstDeduction))
    return reportLines


