SPEED_OF_SOUND_M_PER_S = 340.0


def validate_ping_record(ping_record):
    if len(ping_record) != 3:
        raise ValueError("each ping needs pulse frequency, echo frequency and delay")
    pulse_frequency_khz, echo_frequency_khz, echo_delay_ms = ping_record
    if pulse_frequency_khz <= 0 or echo_frequency_khz <= 0:
        raise ValueError("frequencies must be positive kilohertz values")
    if echo_delay_ms < 0:
        raise ValueError("echo delay cannot be negative")
    return float(pulse_frequency_khz), float(echo_frequency_khz), float(echo_delay_ms)


def one_way_travel_time_seconds(echo_delay_ms):
    round_trip_seconds = echo_delay_ms / 1000.0
    return round_trip_seconds / 2.0


def estimated_target_distance(echo_delay_ms):
    travel_time_seconds = one_way_travel_time_seconds(echo_delay_ms)
    return travel_time_seconds * SPEED_OF_SOUND_M_PER_S


def average_of(distance_values):
    if not distance_values:
        return 0.0
    return sum(distance_values) / len(distance_values)


def track(pings):
    receding_distances = []
    approaching_distances = []
    for ping_record in pings:
        pulse_frequency_khz, echo_frequency_khz, echo_delay_ms = validate_ping_record(ping_record)
        target_distance_m = estimated_target_distance(echo_delay_ms)
        if pulse_frequency_khz > echo_frequency_khz:
            receding_distances.append(target_distance_m)
        else:
            approaching_distances.append(target_distance_m)
    return average_of(receding_distances), average_of(approaching_distances)


def format_tracking_report(average_receding_distance, average_approaching_distance):
    report_lines = [
        "Sonar tracking summary",
        "  moving away  : {:.2f} m".format(average_receding_distance),
        "  approaching  : {:.2f} m".format(average_approaching_distance),
    ]
    distance_difference = average_receding_distance - average_approaching_distance
    if distance_difference > 0:
        report_lines.append("  receding contacts are farther by {:.2f} m".format(distance_difference))
    elif distance_difference < 0:
        report_lines.append("  approaching contacts are farther by {:.2f} m".format(-distance_difference))
    else:
        report_lines.append("  both groups sit at the same mean range")
    return "\n".join(report_lines)


def main():
    recorded_pings = [
        (24.0, 22.5, 120.0),
        (24.0, 26.1, 80.0),
        (18.5, 17.0, 250.0),
        (18.5, 19.4, 310.0),
        (30.0, 30.0, 60.0),
    ]
    average_receding_distance, average_approaching_distance = track(recorded_pings)
    print(format_tracking_report(average_receding_distance, average_approaching_distance))


if __name__ == "__main__":
    main()

