def validate_observation(observation_entry, entry_index):
    if len(observation_entry) != 3:
        raise ValueError(f"observation {entry_index} must have exactly three fields")
    skywatcher_count, clear_sky_percent, meteors_seen = observation_entry
    if skywatcher_count <= 0:
        raise ValueError(f"observation {entry_index} has a non-positive skywatcher count")
    if not 0 < clear_sky_percent <= 100:
        raise ValueError(f"observation {entry_index} has an out-of-range clear sky percentage")
    if meteors_seen < 0:
        raise ValueError(f"observation {entry_index} has a negative meteor count")
    return skywatcher_count, clear_sky_percent, meteors_seen


def effective_hourly_rate(skywatcher_count, clear_sky_percent, meteors_seen):
    clear_sky_fraction = clear_sky_percent / 100.0
    return (meteors_seen / clear_sky_fraction) / skywatcher_count


def forecast(observations):
    highest_rate = 0.0
    total_clear_meteors = 0
    peak_hour_index = 0
    for hour_index, observation_entry in enumerate(observations):
        watcher_count, clear_percent, meteors_seen = validate_observation(observation_entry, hour_index)
        hourly_rate = effective_hourly_rate(watcher_count, clear_percent, meteors_seen)
        if hourly_rate > highest_rate:
            highest_rate = hourly_rate
            peak_hour_index = hour_index
        if clear_percent > 80:
            total_clear_meteors += meteors_seen
    return highest_rate, total_clear_meteors, peak_hour_index


def parse_observation_line(raw_line):
    field_values = [field.strip() for field in raw_line.split(",")]
    watcher_count = int(field_values[0])
    clear_percent = float(field_values[1])
    meteors_seen = int(field_values[2])
    return watcher_count, clear_percent, meteors_seen


def load_observations(raw_lines):
    parsed_observations = []
    for raw_line in raw_lines:
        stripped_line = raw_line.strip()
        if stripped_line and not stripped_line.startswith("#"):
            parsed_observations.append(parse_observation_line(stripped_line))
    return parsed_observations


def format_forecast_report(peak_rate, clear_sky_total, peak_index):
    report_lines = [
        f"peak effective hourly rate : {peak_rate:.3f}",
        f"meteors under clear skies  : {clear_sky_total}",
        f"peak activity hour index   : {peak_index}",
    ]
    return "\n".join(report_lines)


