BODY_HARNESS_FEE = 25


def requires_heavy_cord(jumper_weight):
    return jumper_weight > HEAVY_CORD_WEIGHT_LIMIT


def requires_long_cord(preferred_height):
    return preferred_height > LONG_CORD_HEIGHT_LIMIT


def calculate_jumper_cost(jumper_weight, preferred_height, harness_needed):
    if requires_heavy_cord(jumper_weight):
        equipment_cost = HEAVY_CORD_COST
    else:
        equipment_cost = STANDARD_CORD_COST
    if requires_long_cord(preferred_height):
        equipment_cost += LONG_CORD_EXTENSION_FEE
    if harness_needed:
        equipment_cost += BODY_HARNESS_FEE
    return equipment_cost


def assign(jumpers):
    total_equipment_cost = 0
    heavy_cord_count = 0
    body_harness_count = 0
    for jumper_weight, preferred_height, harness_needed in jumpers:
        total_equipment_cost += calculate_jumper_cost(
            jumper_weight, preferred_height, harness_needed
        )
        if requires_heavy_cord(jumper_weight):
            heavy_cord_count += 1
        if harness_needed:
            body_harness_count += 1
