WET_FLOOR_PENALTY = 0.2
TIGHT_THRESHOLD = 0.8
CRAWL_HEIGHT_LIMIT = 1.5


def effective_height(raw_height, has_wet_floor):
    adjusted_height = raw_height
    if has_wet_floor:
        adjusted_height = raw_height - WET_FLOOR_PENALTY
    return adjusted_height


def validate_passage(passage_record, record_index):
    if len(passage_record) != 4:
        raise ValueError(
            "passage %d must contain length, width, height and wet floor flag"
            % record_index
        )
    passage_length, passage_width, passage_height, wet_floor_flag = passage_record
    for dimension_name, dimension_value in (
        ("length", passage_length),
        ("width", passage_width),
        ("height", passage_height),
    ):
        if not isinstance(dimension_value, (int, float)):
            raise TypeError(
                "passage %d has a non numeric %s" % (record_index, dimension_name)
            )
        if dimension_value <= 0:
            raise ValueError(
                "passage %d has a non positive %s" % (record_index, dimension_name)
            )
    if not isinstance(wet_floor_flag, bool):
        raise TypeError("passage %d has a non boolean wet floor flag" % record_index)
    return passage_length, passage_width, passage_height, wet_floor_flag


def rate(passages):
    tight_count = 0
    crawl_count = 0
    max_tight_length = 0
    for record_index, passage_record in enumerate(passages):
        length_value, width_value, height_value, wet_floor_flag = validate_passage(
            passage_record, record_index
        )
        usable_height = effective_height(height_value, wet_floor_flag)
        if width_value < TIGHT_THRESHOLD or usable_height < TIGHT_THRESHOLD:
            tight_count += 1
            if length_value > max_tight_length:
                max_tight_length = length_value
        elif usable_height < CRAWL_HEIGHT_LIMIT:
            crawl_count += 1
    return (tight_count, crawl_count, max_tight_length)


def format_rating_report(rating_result):
    tight_total, crawl_total, longest_tight_length = rating_result
    report_lines = [
        "extremely tight passages: %d" % tight_total,
        "standard crawl passages: %d" % crawl_total,
        "longest tight passage: %.2f m" % longest_tight_length,
    ]
    return "\n".join(report_lines)


def main():
    survey_passages = [
        (3.4, 0.7, 1.2, False),
        (5.0, 1.1, 1.4, False),
        (12.5, 0.9, 1.0, True),
        (2.2, 1.6, 2.0, True),
        (8.75, 1.2, 0.95, False),
    ]
    rating_result = rate(survey_passages)
    print(format_rating_report(rating_result))


if __name__ == "__main__":
    main()

