def validate_weapon_entry(weapon_entry, entry_index):
    if len(weapon_entry) != 4:
        raise ValueError(
            "weapon %d must have 4 values, got %d" % (entry_index, len(weapon_entry))
        )
    for measured_value in weapon_entry:
        if not isinstance(measured_value, (int, float)):
            raise TypeError("weapon %d contains a non-numeric value" % entry_index)
    heat_rate_per_minute = weapon_entry[2]
    weapon_mass = weapon_entry[3]
    if heat_rate_per_minute <= 0:
        raise ValueError("weapon %d has a non-positive heat rate" % entry_index)
    if weapon_mass < 0:
        raise ValueError("weapon %d has a negative mass" % entry_index)


def count_heating_cycles(start_temperature, target_temperature, heat_rate_per_minute, weapon_mass):
    current_metal_temperature = start_temperature
    cycle_count = 0
    while current_metal_temperature < target_temperature:
        current_metal_temperature += heat_rate_per_minute
        cycle_count += 1
        if current_metal_temperature >= target_temperature:
            break
        cooled_temperature = current_metal_temperature * 0.9 - weapon_mass
        if cooled_temperature >= current_metal_temperature:
            raise ValueError("cooling model diverges for this weapon")
        if cooled_temperature + heat_rate_per_minute <= current_metal_temperature - heat_rate_per_minute:
            raise ValueError("furnace heat rate cannot overcome cooling for this weapon")
        current_metal_temperature = cooled_temperature
    return cycle_count


def forge(weapons):
    total_required_cycles = 0
    highest_cycle_count = 0
    for entry_index, weapon_entry in enumerate(weapons):
        validate_weapon_entry(weapon_entry, entry_index)
        start_temperature, target_temperature, heat_rate_per_minute, weapon_mass = weapon_entry
        cycles_for_weapon = count_heating_cycles(
