def validate_pond_entry(pond_entry, entry_index):
    if len(pond_entry) != 4:
        raise ValueError(f"pond {entry_index} must have 4 fields, got {len(pond_entry)}")
    total_volume, fish_count, plant_coverage, has_deep_section = pond_entry
    if total_volume < 0:
        raise ValueError(f"pond {entry_index} has a negative volume")
    if fish_count < 0:
        raise ValueError(f"pond {entry_index} has a negative fish count")
    if not 0 <= plant_coverage <= 100:
        raise ValueError(f"pond {entry_index} coverage must be within 0-100")
    return total_volume, fish_count, plant_coverage, bool(has_deep_section)


def compute_single_flow_rate(total_volume, fish_count, plant_coverage, has_deep_section):
    baseline_flow_rate = total_volume / 2
    fish_flow_addition = fish_count * 50
    combined_flow_rate = baseline_flow_rate + fish_flow_addition
    if plant_coverage > 50:
        plant_reduction_factor = 0.9
        combined_flow_rate *= plant_reduction_factor
    if has_deep_section:
        deep_circulation_bonus = 100
        combined_flow_rate += deep_circulation_bonus
    return combined_flow_rate


def calculate(ponds):
    final_flow_rates = []
    highest_flow_rate = 0
    for entry_index, pond_entry in enumerate(ponds):
        total_volume, fish_count, plant_coverage, has_deep_section = validate_pond_entry(
            pond_entry, entry_index
        )
        required_flow_rate = compute_single_flow_rate(
            total_volume, fish_count, plant_coverage, has_deep_section
        )
        final_flow_rates.append(required_flow_rate)
        if required_flow_rate > highest_flow_rate:
            highest_flow_rate = required_flow_rate
    return final_flow_rates, highest_flow_rate


