import math


def validate_throw(throw_record, record_index):
    if len(throw_record) != 3:
        raise ValueError("throw %d must contain exactly three values" % record_index)
    target_distance, current_wind_speed, is_successful_hit = throw_record
    if not isinstance(target_distance, (int, float)):
        raise TypeError("throw %d has a non numeric target distance" % record_index)
    if not isinstance(current_wind_speed, (int, float)):
        raise TypeError("throw %d has a non numeric wind speed" % record_index)
    if not isinstance(is_successful_hit, bool):
        raise TypeError("throw %d has a non boolean hit flag" % record_index)
    if target_distance < 0:
        raise ValueError("throw %d has a negative target distance" % record_index)
    if current_wind_speed < 0:
        raise ValueError("throw %d has a negative wind speed" % record_index)
    return target_distance, current_wind_speed, is_successful_hit


def compute_throw_score(target_distance, current_wind_speed, is_successful_hit):
    base_accuracy_score = 10
    long_distance_bonus = 0
    crosswind_penalty_bonus = 0
    miss_penalty_value = 0
    if is_successful_hit:
        if target_distance > 15:
            long_distance_bonus = math.floor(target_distance / 5)
        if current_wind_speed > 5:
            crosswind_penalty_bonus = 3
        throw_total_score = base_accuracy_score + long_distance_bonus + crosswind_penalty_bonus
    else:
        miss_penalty_value = 2
        throw_total_score = -miss_penalty_value
    return throw_total_score, miss_penalty_value


def score(throws):
    accumulated_score = 0
    highest_throw_score = 0
    total_miss_penalties = 0
    for record_index, throw_record in enumerate(throws, start=1):
        target_distance, current_wind_speed, is_successful_hit = validate_throw(throw_record, record_index)
        throw_total_score, miss_penalty_value = compute_throw_score(
            target_distance, current_wind_speed, is_successful_hit
        )
        accumulated_score += throw_total_score
        total_miss_penalties += miss_penalty_value
        if record_index == 1 or throw_total_score > highest_throw_score:
            highest_throw_score = throw_total_score
    return accumulated_score, highest_throw_score, total_miss_penalties


def format_score_report(final_score, best_single_throw, penalty_total):
    report_lines = [
        "final accumulated score : %d" % final_score,
        "highest single throw    : %d" % best_single_throw,
        "total miss penalties    : %d" % penalty_total,
    ]
    return "\n".join(report_lines)


