def compute_aging_periods(total_aging_days):
    """Number of complete ten day aging periods in the given aging span."""
    return total_aging_days // 10


def select_weight_loss_rate(ambient_humidity_percentage, is_washed_rind):
    """Loss percentage per ten day period for the given cave conditions."""
    if ambient_humidity_percentage < 80:
        baseline_dry_loss_rate = 1.0
    elif ambient_humidity_percentage <= 90:
        baseline_dry_loss_rate = 0.5
    else:
        baseline_dry_loss_rate = 0.0
    if is_washed_rind:
        washed_rind_adjustment = 0.2
        return max(0.0, baseline_dry_loss_rate - washed_rind_adjustment)
    return baseline_dry_loss_rate


def project_final_weight(initial_cheese_weight, ambient_humidity_percentage,
                         total_aging_days, is_washed_rind):
    """Weight in kilograms left after the whole aging span."""
    aging_period_count = compute_aging_periods(total_aging_days)
    weight_loss_rate = select_weight_loss_rate(ambient_humidity_percentage,
                                               is_washed_rind)
    total_loss_fraction = (weight_loss_rate * aging_period_count) / 100.0
    if total_loss_fraction >= 1.0:
        return 0.0
    return initial_cheese_weight * (1.0 - total_loss_fraction)


def validate_reading(cheese_reading):
    """Unpack one reading, rejecting impossible cave or wheel values."""
    initial_cheese_weight, ambient_humidity_percentage, total_aging_days, is_washed_rind = cheese_reading
    if initial_cheese_weight <= 0:
        raise ValueError("initial cheese weight must be positive")
    if not 0 <= ambient_humidity_percentage <= 100:
        raise ValueError("ambient humidity percentage must be between 0 and 100")
    if total_aging_days < 0:
        raise ValueError("total aging days cannot be negative")
    return (initial_cheese_weight, ambient_humidity_percentage,
            total_aging_days, bool(is_washed_rind))


def monitor(readings):
    projected_weight_list = []
    for cheese_reading in readings:
        weight_value, humidity_value, aging_days_value, washed_rind_flag = validate_reading(cheese_reading)
        projected_final_weight = project_final_weight(weight_value, humidity_value,
                                                      aging_days_value, washed_rind_flag)
        projected_weight_list.append(round(projected_final_weight, 3))
    highest_projected_weight = max(projected_weight_list) if projected_weight_list else 0.0
    return (projected_weight_list, highest_projected_weight)


def format_monitor_report(readings, projected_weight_list, highest_projected_weight):
    """Human readable summary lines for the monitored cave batch."""
    report_lines = []
    for wheel_index, cheese_reading in enumerate(readings):
        starting_weight = cheese_reading[0]
        final_weight = projected_weight_list[wheel_index]
        lost_weight_amount = round(starting_weight - final_weight, 3)
        rind_label = "washed rind" if cheese_reading[3] else "natural rind"
        report_lines.append(
            f"wheel {wheel_index + 1} ({rind_label}): {starting_weight} kg -> "
            f"{final_weight} kg (lost {lost_weight_amount} kg)")
    report_lines.append(f"heaviest projected wheel: {highest_projected_weight} kg")
    return "\n".join(report_lines)


def main():
    cave_readings = [
        (12.0, 75, 95, False),
        (8.5, 85, 120, True),
        (20.0, 94, 200, False),
        (5.0, 78, 45, True),
    ]
    projected_weight_list, highest_projected_weight = monitor(cave_readings)
    print(format_monitor_report(cave_readings, projected_weight_list,
                                highest_projected_weight))


if __name__ == "__main__":
