        return COLD_POPPING_EFFICIENCY
    if oil_temperature_celsius > MAXIMUM_IDEAL_TEMPERATURE:
        return HOT_POPPING_EFFICIENCY
    return BASELINE_POPPING_EFFICIENCY


def active_efficiency(oil_temperature_celsius, kernel_moisture_percent):
    effective_efficiency = temperature_efficiency(oil_temperature_celsius)
    if kernel_moisture_percent < DRY_KERNEL_THRESHOLD:
