def compute_base_slip(terrain_slope, sand_looseness):
    return terrain_slope * sand_looseness / 2


def compute_speed_penalty(rover_speed):
    high_speed_penalty = 10
    if rover_speed > 5:
        return high_speed_penalty
    return 0


def compute_total_slip(terrain_slope, sand_looseness, rover_speed, wheel_wear_level):
    base_slip_percentage = compute_base_slip(terrain_slope, sand_looseness)
    total_slip_percentage = base_slip_percentage + compute_speed_penalty(rover_speed)
    return total_slip_percentage + wheel_wear_level


def validate_segment(segment_tuple, segment_index):
    if len(segment_tuple) != 4:
        raise ValueError(
            "segment %d must contain exactly 4 values" % segment_index
        )
    terrain_slope, sand_looseness, rover_speed, wheel_wear_level = segment_tuple
    if not 1 <= sand_looseness <= 10:
        raise ValueError(
            "segment %d sand looseness must be between 1 and 10" % segment_index
        )
    return terrain_slope, sand_looseness, rover_speed, wheel_wear_level


def predict(segments):
    stuck_slip_threshold = 40
    safe_segment_count = 0
    stuck_segment_count = 0
    for segment_index, segment_tuple in enumerate(segments):
        segment_values = validate_segment(segment_tuple, segment_index)
        total_slip_percentage = compute_total_slip(*segment_values)
        if total_slip_percentage > stuck_slip_threshold:
            stuck_segment_count += 1
        else:
            safe_segment_count += 1
    return safe_segment_count, stuck_segment_count


def build_segment_report(segments):
    report_lines = []
    for segment_index, segment_tuple in enumerate(segments):
        segment_values = validate_segment(segment_tuple, segment_index)
        total_slip_percentage = compute_total_slip(*segment_values)
        segment_status = "STUCK" if total_slip_percentage > 40 else "SAFE"
        report_lines.append(
            "segment %d: slip %.1f%% -> %s"
            % (segment_index, total_slip_percentage, segment_status)
        )
    return "\n".join(report_lines)


def main():
    route_segments = [
        (4, 6, 3, 2),
        (10, 8, 7, 5),
        (2, 3, 4, 1),
        (12, 5, 6, 8),
        (0, 1, 9, 0),
    ]
    print(build_segment_report(route_segments))
    safe_segment_count, stuck_segment_count = predict(route_segments)
    total_segment_count = safe_segment_count + stuck_segment_count
    print("safe segments: %d" % safe_segment_count)
    print("stuck segments: %d" % stuck_segment_count)
    stuck_ratio_percentage = 100.0 * stuck_segment_count / total_segment_count
    print("stuck ratio: %.1f%%" % stuck_ratio_percentage)


if __name__ == "__main__":
    main()

