def baseline_temperature_difference(water_temperature):
    temperature_gap = water_temperature - 80
    if temperature_gap < 0:
        return 0
    return temperature_gap


def astringency_score(water_temperature, steeping_minutes, leaf_mass_grams, mineral_hardness):
    temperature_difference = baseline_temperature_difference(water_temperature)
    base_score = temperature_difference * steeping_minutes
    if leaf_mass_grams > 5:
        base_score = base_score * 1.2
    final_score = base_score
    if mineral_hardness > 100:
        final_score = final_score + 5
    return final_score


def is_overly_bitter(final_score):
    return final_score > 50


def steep(teas):
    non_bitter_scores = []
    highest_score = 0
    for water_temperature, steeping_minutes, leaf_mass_grams, mineral_hardness in teas:
        current_score = astringency_score(
            water_temperature, steeping_minutes, leaf_mass_grams, mineral_hardness
        )
        if not is_overly_bitter(current_score):
            non_bitter_scores.append(current_score)
        if current_score > highest_score:
            highest_score = current_score
    if non_bitter_scores:
        average_non_bitter_score = sum(non_bitter_scores) / len(non_bitter_scores)
    else:
        average_non_bitter_score = 0
    return (average_non_bitter_score, highest_score)


def format_brew_report(teas):
    report_lines = []
    for brew_index, brew_parameters in enumerate(teas, start=1):
        water_temperature, steeping_minutes, leaf_mass_grams, mineral_hardness = brew_parameters
        brew_score = astringency_score(
            water_temperature, steeping_minutes, leaf_mass_grams, mineral_hardness
        )
        bitterness_label = "bitter" if is_overly_bitter(brew_score) else "balanced"
        report_lines.append(
            "Brew {0}: {1}C for {2}min, {3}g leaf, hardness {4} -> {5:.2f} ({6})".format(
                brew_index,
                water_temperature,
                steeping_minutes,
                leaf_mass_grams,
                mineral_hardness,
                brew_score,
                bitterness_label,
            )
        )
    return "\n".join(report_lines)


def main():
    tea_samples = [
        (95, 3, 4.0, 60),
        (100, 5, 6.5, 150),
        (80, 4, 3.0, 40),
        (90, 2, 5.5, 120),
        (98, 4, 4.5, 90),
    ]
    print(format_brew_report(tea_samples))
    average_score, maximum_score = steep(tea_samples)
    print("Average non-bitter astringency: {0:.2f}".format(average_score))
    print("Highest astringency overall: {0:.2f}".format(maximum_score))


if __name__ == "__main__":
    main()

