GRAVITY_ACCELERATION = 9.8
STANDARD_AIR_FACTOR = 50.0


def compute_gravitational_force(total_cart_mass):
    return total_cart_mass * GRAVITY_ACCELERATION


def compute_wind_resistance(frontal_surface_area, aerodynamic_drag_coefficient):
    return frontal_surface_area * aerodynamic_drag_coefficient * STANDARD_AIR_FACTOR


def compute_rolling_resistance(total_cart_mass, bearing_friction_factor):
    return total_cart_mass * bearing_friction_factor


def validate_cart_specification(cart_specification, cart_index):
    if len(cart_specification) != 4:
        raise ValueError(
            "cart %d must provide mass, area, drag coefficient and friction factor"
            % cart_index
        )
    for value_position, numeric_value in enumerate(cart_specification):
        if not isinstance(numeric_value, (int, float)):
            raise TypeError(
                "cart %d field %d is not numeric" % (cart_index, value_position)
            )
        if numeric_value < 0:
            raise ValueError(
                "cart %d field %d must not be negative" % (cart_index, value_position)
            )


def race(carts):
    net_force_list = []
    for cart_index, cart_specification in enumerate(carts):
        validate_cart_specification(cart_specification, cart_index)
        total_cart_mass, frontal_surface_area, drag_coefficient, friction_factor = cart_specification
        gravitational_forward_force = compute_gravitational_force(total_cart_mass)
        aerodynamic_wind_resistance = compute_wind_resistance(
            frontal_surface_area, drag_coefficient
        )
        mechanical_rolling_resistance = compute_rolling_resistance(
            total_cart_mass, friction_factor
        )
        net_forward_force = (
            gravitational_forward_force
            - aerodynamic_wind_resistance
            - mechanical_rolling_resistance
        )
        net_force_list.append(net_forward_force)
    highest_net_force = max(net_force_list) if net_force_list else None
    return (net_force_list, highest_net_force)


def format_race_report(carts, race_result):
    net_force_list, highest_net_force = race_result
    report_lines = []
    for cart_index, net_forward_force in enumerate(net_force_list):
        total_cart_mass = carts[cart_index][0]
        winner_marker = " <-- fastest" if net_forward_force == highest_net_force else ""
        report_lines.append(
            "cart %d (%.1f kg): %.2f N%s"
            % (cart_index, total_cart_mass, net_forward_force, winner_marker)
        )
    return "\n".join(report_lines)


def main():
    cart_entry_list = [
        (60.0, 0.6, 0.9, 0.02),
        (85.5, 0.75, 1.1, 0.015),
        (42.0, 0.45, 0.8, 0.03),
    ]
    race_result = race(cart_entry_list)
    print(format_race_report(cart_entry_list, race_result))
    print("winning net forward force: %.2f N" % race_result[1])


if __name__ == "__main__":
    main()

