def validate_scene(scene_entry, scene_index):
    if len(scene_entry) != 4:
        raise ValueError("scene %d must have exactly four fields" % scene_index)
    scene_duration, character_count, movement_complexity, uses_miniature_props = scene_entry
    if scene_duration <= 0:
        raise ValueError("scene %d has a non-positive duration" % scene_index)
    if character_count < 0:
        raise ValueError("scene %d has a negative character count" % scene_index)
    if movement_complexity < 0:
        raise ValueError("scene %d has a negative movement complexity" % scene_index)
    return scene_duration, character_count, movement_complexity, bool(uses_miniature_props)


def compute_scene_frames(scene_duration, character_count, movement_complexity, uses_miniature_props):
    base_frame_count = scene_duration * 24
    extra_setup_frames = 0
    if character_count > 2:
        extra_setup_frames = scene_duration * 10
    combined_frame_count = base_frame_count + extra_setup_frames
    if movement_complexity > 5:
        combined_frame_count = combined_frame_count * 1.1
    if uses_miniature_props:
        combined_frame_count = combined_frame_count + 20
    return combined_frame_count


def animate(scenes):
    total_required_frames = 0
    highest_scene_frames = 0
    for scene_index, scene_entry in enumerate(scenes, start=1):
        scene_duration, character_count, movement_complexity, uses_miniature_props = validate_scene(
            scene_entry, scene_index
        )
        scene_frame_count = compute_scene_frames(
            scene_duration, character_count, movement_complexity, uses_miniature_props
        )
        total_required_frames += scene_frame_count
        if scene_frame_count > highest_scene_frames:
            highest_scene_frames = scene_frame_count
    return (total_required_frames, highest_scene_frames)


def build_scene_report(scenes):
    report_lines = []
    for scene_index, scene_entry in enumerate(scenes, start=1):
        scene_duration, character_count, movement_complexity, uses_miniature_props = validate_scene(
            scene_entry, scene_index
        )
        scene_frame_count = compute_scene_frames(
            scene_duration, character_count, movement_complexity, uses_miniature_props
        )
        props_label = "miniatures" if uses_miniature_props else "full scale"
        report_lines.append(
