def validateScene(sceneEntry, sceneIndex):
    if len(sceneEntry) != 4:
        raise ValueError("scene %d must have exactly four fields" % sceneIndex)
    sceneDuration, characterCount, movementComplexity, usesMiniatureProps = sceneEntry
    if sceneDuration <= 0:
        raise ValueError("scene %d has a non-positive duration" % sceneIndex)
    if characterCount < 0:
        raise ValueError("scene %d has a negative character count" % sceneIndex)
    if movementComplexity < 0:
        raise ValueError("scene %d has a negative movement complexity" % sceneIndex)
    return sceneDuration, characterCount, movementComplexity, bool(usesMiniatureProps)


def computeSceneFrames(sceneDuration, characterCount, movementComplexity, usesMiniatureProps):
    baseFrameCount = sceneDuration * 24
    extraSetupFrames = 0
    if characterCount > 2:
        extraSetupFrames = sceneDuration * 10
    combinedFrameCount = baseFrameCount + extraSetupFrames
    if movementComplexity > 5:
        combinedFrameCount = combinedFrameCount * 1.1
    if usesMiniatureProps:
        combinedFrameCount = combinedFrameCount + 20
    return combinedFrameCount


def animate(scenes):
    totalRequiredFrames = 0
    highestSceneFrames = 0
    for sceneIndex, sceneEntry in enumerate(scenes, start=1):
        sceneDuration, characterCount, movementComplexity, usesMiniatureProps = validateScene(
            sceneEntry, sceneIndex
        )
        sceneFrameCount = computeSceneFrames(
            sceneDuration, characterCount, movementComplexity, usesMiniatureProps
        )
        totalRequiredFrames += sceneFrameCount
        if sceneFrameCount > highestSceneFrames:
            highestSceneFrames = sceneFrameCount
    return (totalRequiredFrames, highestSceneFrames)


def buildSceneReport(scenes):
    reportLines = []
    for sceneIndex, sceneEntry in enumerate(scenes, start=1):
