        raise ValueError(
            "session %d must contain exactly four values" % session_index
        )
    typing_speed, lubrication_percent, ribbon_wear, roller_hardness = session_record
    for field_name, field_value in (
        ("typing speed", typing_speed),
        ("lubrication percentage", lubrication_percent),
        ("ribbon wear level", ribbon_wear),
        ("roller hardness", roller_hardness),
    ):
        if not isinstance(field_value, (int, float)) or isinstance(field_value, bool):
            raise TypeError(
                "session %d: %s must be numeric" % (session_index, field_name)
            )
    return typing_speed, lubrication_percent, ribbon_wear, roller_hardness


def has_fast_typing_jam(typing_speed, lubrication_percent):
    return typing_speed > 60 and lubrication_percent < 50


def has_frayed_ribbon_snag(ribbon_wear, roller_hardness):
    return ribbon_wear > 8 or roller_hardness > 80


def typewrite(sessions):
    fast_jam_total = 0
    ribbon_snag_total = 0
    for session_index, session_record in enumerate(sessions, start=1):
        typing_speed, lubrication_percent, ribbon_wear, roller_hardness = (
            validate_session(session_record, session_index)
        )
        if has_fast_typing_jam(typing_speed, lubrication_percent):
            fast_jam_total += 1
        if has_frayed_ribbon_snag(ribbon_wear, roller_hardness):
            ribbon_snag_total += 1
