BASELINE_DROP_RATE = 2.0
FAST_SWING_THRESHOLD = 1.0
FAST_SWING_MULTIPLIER = 1.5
HEAVY_WEIGHT_GRAMS = 500.0
SLIPPAGE_PENALTY_HOURS = 1.0
DUSTY_LEVEL_THRESHOLD = 5
FRICTION_PENALTY_HOURS = 2.0


def validate_clock_entry(clock_entry, entry_index):
    if len(clock_entry) != 4:
        raise ValueError(
            "clock %d must have 4 fields, got %d" % (entry_index, len(clock_entry))
        )
    chain_length_cm, swing_rate_hz, weight_mass_g, dust_level = clock_entry
    if chain_length_cm < 0:
        raise ValueError("clock %d has negative chain length" % entry_index)
    if swing_rate_hz <= 0:
        raise ValueError("clock %d has a non-positive swing rate" % entry_index)
    if weight_mass_g <= 0:
        raise ValueError("clock %d has a non-positive brass weight" % entry_index)
    if dust_level < 0:
        raise ValueError("clock %d has a negative dust level" % entry_index)
    return chain_length_cm, swing_rate_hz, weight_mass_g, dust_level


def effective_drop_rate(swing_rate_hz):
    if swing_rate_hz > FAST_SWING_THRESHOLD:
        return BASELINE_DROP_RATE * FAST_SWING_MULTIPLIER
    return BASELINE_DROP_RATE


def running_hours_for_clock(chain_length_cm, swing_rate_hz, weight_mass_g, dust_level):
    modified_drop_rate = effective_drop_rate(swing_rate_hz)
    base_running_hours = chain_length_cm / modified_drop_rate
    if weight_mass_g > HEAVY_WEIGHT_GRAMS:
        base_running_hours -= SLIPPAGE_PENALTY_HOURS
    if dust_level > DUSTY_LEVEL_THRESHOLD:
        base_running_hours -= FRICTION_PENALTY_HOURS
    return base_running_hours


def wind(clocks):
    running_hours_list = []
    for entry_index, clock_entry in enumerate(clocks):
        chain_length_cm, swing_rate_hz, weight_mass_g, dust_level = validate_clock_entry(
            clock_entry, entry_index
        )
        final_running_hours = running_hours_for_clock(
            chain_length_cm, swing_rate_hz, weight_mass_g, dust_level
        )
        running_hours_list.append(final_running_hours)
    max_running_hours = max(running_hours_list) if running_hours_list else 0
    return running_hours_list, max_running_hours


def format_wind_report(clocks, running_hours_list, max_running_hours):
    report_lines = []
    for entry_index, clock_entry in enumerate(clocks):
        chain_length_cm, swing_rate_hz = clock_entry[0], clock_entry[1]
        hours_for_entry = running_hours_list[entry_index]
        longest_marker = " <- longest" if hours_for_entry == max_running_hours else ""
        report_lines.append(
            "clock %d: chain %.1f cm at %.2f Hz runs %.2f h%s"
            % (entry_index, chain_length_cm, swing_rate_hz, hours_for_entry, longest_marker)
        )
    report_lines.append("maximum continuous running hours: %.2f" % max_running_hours)
    return "\n".join(report_lines)


def main():
    clock_collection = [
        (120.0, 0.5, 450.0, 2),
        (120.0, 1.5, 450.0, 2),
        (200.0, 0.8, 620.0, 7),
        (60.0, 2.0, 700.0, 9),
    ]
    running_hours_list, max_running_hours = wind(clock_collection)
    print(format_wind_report(clock_collection, running_hours_list, max_running_hours))


if __name__ == "__main__":
    main()

