import math


def compute_altitude_in_thousands(flight_altitude_feet):
    return math.floor(flight_altitude_feet / 1000)


def compute_modified_air_density(flight_altitude_feet, air_temperature_celsius):
    altitude_in_thousands = compute_altitude_in_thousands(flight_altitude_feet)
    modified_air_density = 1.2 - 0.1 * altitude_in_thousands
    if air_temperature_celsius < 0:
        freezing_air_multiplier = 1.05
        modified_air_density *= freezing_air_multiplier
    return modified_air_density


def compute_total_wind_force(airplane_speed_knots, flight_altitude_feet,
                             frontal_surface_area, air_temperature_celsius):
    modified_air_density = compute_modified_air_density(flight_altitude_feet,
                                                        air_temperature_celsius)
    return 0.5 * modified_air_density * airplane_speed_knots ** 2 * frontal_surface_area


def calculate(stunts):
    force_values = []
    for airplane_speed_knots, flight_altitude_feet, frontal_surface_area, air_temperature_celsius in stunts:
        total_wind_force = compute_total_wind_force(airplane_speed_knots,
                                                    flight_altitude_feet,
                                                    frontal_surface_area,
                                                    air_temperature_celsius)
        force_values.append(total_wind_force)
    if not force_values:
        return (0.0, 0.0)
    highest_wind_force = max(force_values)
    average_wind_force = sum(force_values) / len(force_values)
    return (highest_wind_force, average_wind_force)


def validate_stunt_records(stunt_records):
    validated_records = []
    for record_index, stunt_record in enumerate(stunt_records):
        if len(stunt_record) != 4:
            raise ValueError("stunt record %d must contain exactly four values" % record_index)
        airplane_speed_knots, flight_altitude_feet, frontal_surface_area, air_temperature_celsius = stunt_record
        if airplane_speed_knots < 0 or flight_altitude_feet < 0 or frontal_surface_area <= 0:
            raise ValueError("stunt record %d has impossible flight values" % record_index)
        validated_records.append((airplane_speed_knots, flight_altitude_feet,
                                  frontal_surface_area, air_temperature_celsius))
    return validated_records


def format_stunt_report(stunt_records):
    report_lines = []
    for airplane_speed_knots, flight_altitude_feet, frontal_surface_area, air_temperature_celsius in stunt_records:
        single_wind_force = compute_total_wind_force(airplane_speed_knots,
                                                     flight_altitude_feet,
                                                     frontal_surface_area,
                                                     air_temperature_celsius)
        report_lines.append("%4d kn @ %6d ft, %.1f m2, %5.1f C -> %10.2f N"
                            % (airplane_speed_knots, flight_altitude_feet,
                               frontal_surface_area, air_temperature_celsius,
                               single_wind_force))
    highest_wind_force, average_wind_force = calculate(stunt_records)
    report_lines.append("highest total wind force: %.2f N" % highest_wind_force)
    report_lines.append("average total wind force: %.2f N" % average_wind_force)
    return "\n".join(report_lines)


