text_nat:
WIND_DRIFT_FACTOR_METERS = 2.0
EXCESSIVE_FORCE_THRESHOLD_NEWTONS = 50.0
EXCESSIVE_FORCE_DRIFT_METERS = 5.0
ALTITUDE_THRESHOLD_METERS = 2.0
ALTITUDE_DRIFT_PENALTY_METERS = 3.0
PERFECT_CATCH_DRIFT_LIMIT_METERS = 10.0
MINIMUM_VALID_ANGLE_DEGREES = 40.0
MAXIMUM_VALID_ANGLE_DEGREES = 50.0


def is_valid_throwing_angle(initial_angle_degrees):
    return MINIMUM_VALID_ANGLE_DEGREES <= initial_angle_degrees <= MAXIMUM_VALID_ANGLE_DEGREES


def compute_ambient_wind_drift(ambient_wind_speed_mph):
    return ambient_wind_speed_mph * WIND_DRIFT_FACTOR_METERS


def compute_excessive_force_drift(initial_throwing_force_newtons):
    if initial_throwing_force_newtons > EXCESSIVE_FORCE_THRESHOLD_NEWTONS:
        return EXCESSIVE_FORCE_DRIFT_METERS
    return 0.0


def compute_altitude_drift_penalty(throwing_height_meters):
    if throwing_height_meters > ALTITUDE_THRESHOLD_METERS:
        return ALTITUDE_DRIFT_PENALTY_METERS
    return 0.0


def compute_total_return_drift(ambient_wind_speed_mph, initial_throwing_force_newtons, throwing_height_meters):
    wind_drift_meters = compute_ambient_wind_drift(ambient_wind_speed_mph)
    force_drift_meters = compute_excessive_force_drift(initial_throwing_force_newtons)
    altitude_drift_meters = compute_altitude_drift_penalty(throwing_height_meters)
    return wind_drift_meters + force_drift_meters + altitude_drift_meters


def throw(attempts):
    perfect_catch_count = 0
    highest_total_drift = 0.0
    for initial_angle_degrees, ambient_wind_speed_mph, initial_throwing_force_newtons, throwing_height_meters in attempts:
        total_return_drift = compute_total_return_drift(
            ambient_wind_speed_mph,
            initial_throwing_force_newtons,
            throwing_height_meters,
        )
        angle_is_valid = is_valid_throwing_angle(initial_angle_degrees)
        if angle_is_valid and total_return_drift < PERFECT_CATCH_DRIFT_LIMIT_METERS:
            perfect_catch_count += 1
        if total_return_drift > highest_total_drift:
            highest_total_drift = total_return_drift
    return (perfect_catch_count, highest_total_drift)


def format_attempt_report(attempt_tuple):
