def compute_hourly_can_rate(pan_capacity_quarts, is_liquid_based, wind_factor):
    baseline_can_rate = 2 if is_liquid_based else 1
    large_pan_penalty = 1 if pan_capacity_quarts > 6 else 0
    high_wind_penalty = 1 if wind_factor > 3 else 0
    return baseline_can_rate + large_pan_penalty + high_wind_penalty


def validate_pan_entry(pan_entry, entry_index):
    if len(pan_entry) != 4:
        raise ValueError("pan entry %d must hold exactly four fields" % entry_index)
