    if pan_capacity_quarts <= 0:
        raise ValueError("pan entry %d has a non-positive capacity" % entry_index)
    if event_duration_hours < 0:
        raise ValueError("pan entry %d has a negative event duration" % entry_index)
    if wind_factor < 0:
        raise ValueError("pan entry %d has a negative wind factor" % entry_index)
    return pan_capacity_quarts, bool(is_liquid_based), event_duration_hours, wind_factor


