JOINT_ALLOWANCE_PER_CORNER = 2.0
REINFORCEMENT_RATIO = 0.10


def validate_panel(panel_spec):
    if len(panel_spec) != 3:
        raise ValueError("each panel needs sides, side length and complexity")
    side_count, average_side_length, complexity_multiplier = panel_spec
    if int(side_count) != side_count or side_count < 3:
        raise ValueError("a polygon panel needs at least three whole sides")
    if average_side_length <= 0:
        raise ValueError("average side length must be positive")
    if complexity_multiplier <= 0:
        raise ValueError("design complexity multiplier must be positive")
    return int(side_count), float(average_side_length), float(complexity_multiplier)


def measure_single_panel(side_count, average_side_length, complexity_multiplier):
    basic_perimeter = side_count * average_side_length
    reinforcement_length = basic_perimeter * REINFORCEMENT_RATIO
    gross_lead_required = (basic_perimeter + reinforcement_length) * complexity_multiplier
    joint_allowance_total = side_count * JOINT_ALLOWANCE_PER_CORNER
    return gross_lead_required + joint_allowance_total


def calculate(panels):
    lead_length_results = []
    for panel_spec in panels:
        side_count, average_side_length, complexity_multiplier = validate_panel(panel_spec)
        total_lead_length = measure_single_panel(
            side_count, average_side_length, complexity_multiplier
        )
        lead_length_results.append(round(total_lead_length, 4))
    return lead_length_results


def summarize_order(panels, lead_length_results):
    total_lead_inches = sum(lead_length_results)
    longest_panel_index = lead_length_results.index(max(lead_length_results))
    return {
        "panel_count": len(panels),
        "totalLeadInches": round(total_lead_inches, 4),
        "total_lead_feet": round(total_lead_inches / 12.0, 4),
        "largest_panel": longest_panel_index + 1,
    }


def format_report(panels, lead_length_results):
    report_lines = ["Panel  Sides  Side(in)  Complexity  Lead(in)"]
    for panel_number, (panel_spec, lead_length) in enumerate(zip(panels, lead_length_results), 1):
        side_count, average_side_length, complexity_multiplier = panel_spec
        report_lines.append(
            "{:>5}  {:>5}  {:>8.2f}  {:>10.2f}  {:>8.2f}".format(
                panel_number, side_count, average_side_length, complexity_multiplier, lead_length
            )
        )
    order_summary = summarize_order(panels, lead_length_results)
    report_lines.append(
        "Total for {panel_count} panel(s): {totalLeadInches} in "
        "({total_lead_feet} ft); largest is panel {largest_panel}".format(**order_summary)
    )
    return "\n".join(report_lines)


