import math

HOT_DOG_VOLUME_ML = 150.0
MATCH_DURATION_MINUTES = 10.0


def validate_contestant(contestant_record, record_index):
    if len(contestant_record) != 3:
        raise ValueError(
            "contestant %d must provide capacity, bite size and chew rate" % record_index
        )
    stomach_capacity_ml, bite_size_ml, chew_rate_per_minute = contestant_record
    if stomach_capacity_ml <= 0:
        raise ValueError("contestant %d has a non-positive stomach capacity" % record_index)
    if bite_size_ml <= 0:
        raise ValueError("contestant %d has a non-positive bite size" % record_index)
    if chew_rate_per_minute <= 0:
        raise ValueError("contestant %d has a non-positive chew rate" % record_index)
    return float(stomach_capacity_ml), float(bite_size_ml), float(chew_rate_per_minute)


def bites_per_hot_dog(bite_size_ml):
    return HOT_DOG_VOLUME_ML / bite_size_ml


def hot_dogs_per_minute(bite_size_ml, chew_rate_per_minute):
    bites_needed = bites_per_hot_dog(bite_size_ml)
    return chew_rate_per_minute / bites_needed


def theoretical_limit(bite_size_ml, chew_rate_per_minute):
    eating_rate = hot_dogs_per_minute(bite_size_ml, chew_rate_per_minute)
    return eating_rate * MATCH_DURATION_MINUTES


def capacity_limit(stomach_capacity_ml):
    return stomach_capacity_ml / HOT_DOG_VOLUME_ML


def analyze(contestants):
    final_counts = []
    for record_index, contestant_record in enumerate(contestants, start=1):
        stomach_capacity_ml, bite_size_ml, chew_rate_per_minute = validate_contestant(
            contestant_record, record_index
        )
        chew_limited_total = theoretical_limit(bite_size_ml, chew_rate_per_minute)
        stomach_limited_total = capacity_limit(stomach_capacity_ml)
        final_counts.append(min(chew_limited_total, stomach_limited_total))
    return final_counts


def describe_results(contestants, final_counts):
    report_lines = []
    for record_index, (contestant_record, hot_dog_total) in enumerate(
        zip(contestants, final_counts), start=1
    ):
        stomach_capacity_ml, bite_size_ml, chew_rate_per_minute = contestant_record
        chew_limited_total = theoretical_limit(float(bite_size_ml), float(chew_rate_per_minute))
        stomach_limited_total = capacity_limit(float(stomach_capacity_ml))
        limiting_factor = "stomach" if stomach_limited_total < chew_limited_total else "chewing"
        whole_hot_dogs = math.floor(hot_dog_total)
        report_lines.append(
            "Contestant %d: %.2f hot dogs (%d whole), limited by %s"
            % (record_index, hot_dog_total, whole_hot_dogs, limiting_factor)
        )
    return report_lines


def main():
    contestant_table = [(3000, 30, 60), (1500, 50, 45), (4500, 25, 90)]
    final_counts = analyze(contestant_table)
    print(final_counts)
    for report_line in describe_results(contestant_table, final_counts):
        print(report_line)
    winning_total = max(final_counts)
    winner_index = final_counts.index(winning_total) + 1
    print("Winner: contestant %d with %.2f hot dogs" % (winner_index, winning_total))


if __name__ == "__main__":
