OVERSPEED_THRESHOLD = 1000.0
SPLASH_PENALTY_RATE = 0.10


def validate_wheel_spec(wheel_spec, wheel_index):
    if len(wheel_spec) != 3:
        raise ValueError("wheel %d must have flow, diameter and friction" % wheel_index)
    flow_rate, wheel_diameter, friction_coefficient = wheel_spec
    if flow_rate < 0:
        raise ValueError("wheel %d has a negative flow rate" % wheel_index)
    if wheel_diameter <= 0:
        raise ValueError("wheel %d has a non-positive diameter" % wheel_index)
    if not 0.0 <= friction_coefficient <= 1.0:
        raise ValueError("wheel %d friction must be between 0 and 1" % wheel_index)
    return float(flow_rate), float(wheel_diameter), float(friction_coefficient)


def unhindered_speed(flow_rate, wheel_diameter):
    return flow_rate * wheel_diameter


def friction_loss(free_speed, friction_coefficient):
    return free_speed * friction_coefficient


def apply_splash_penalty(working_speed):
    if working_speed <= OVERSPEED_THRESHOLD:
        return working_speed
    excess_speed = working_speed - OVERSPEED_THRESHOLD
    return working_speed - excess_speed * SPLASH_PENALTY_RATE


def generate(wheels):
    power_output_list = []
    for wheel_index, wheel_spec in enumerate(wheels):
        flow_rate, wheel_diameter, friction_coefficient = validate_wheel_spec(wheel_spec, wheel_index)
        free_speed = unhindered_speed(flow_rate, wheel_diameter)
        lost_speed = friction_loss(free_speed, friction_coefficient)
        net_speed = free_speed - lost_speed
        final_power = apply_splash_penalty(net_speed)
        power_output_list.append(final_power)
    return power_output_list


def describe_mill(wheel_spec, power_value):
    flow_rate, wheel_diameter, friction_coefficient = wheel_spec
    friction_percent = friction_coefficient * 100.0
