OVERSPEED_THRESHOLD = 1000.0
SPLASH_PENALTY_RATE = 0.10


def validateWheelSpec(wheelSpec, wheelIndex):
    if len(wheelSpec) != 3:
        raise ValueError("wheel %d must have flow, diameter and friction" % wheelIndex)
    flowRate, wheelDiameter, frictionCoefficient = wheelSpec
    if flowRate < 0:
        raise ValueError("wheel %d has a negative flow rate" % wheelIndex)
    if wheelDiameter <= 0:
        raise ValueError("wheel %d has a non-positive diameter" % wheelIndex)
    if not 0.0 <= frictionCoefficient <= 1.0:
        raise ValueError("wheel %d friction must be between 0 and 1" % wheelIndex)
    return float(flowRate), float(wheelDiameter), float(frictionCoefficient)


def unhinderedSpeed(flowRate, wheelDiameter):
    return flowRate * wheelDiameter


def frictionLoss(freeSpeed, frictionCoefficient):
    return freeSpeed * frictionCoefficient


def applySplashPenalty(workingSpeed):
    if workingSpeed <= OVERSPEED_THRESHOLD:
        return workingSpeed
    excessSpeed = workingSpeed - OVERSPEED_THRESHOLD
    return workingSpeed - excessSpeed * SPLASH_PENALTY_RATE


def generate(wheels):
    powerOutputList = []
    for wheelIndex, wheelSpec in enumerate(wheels):
        flowRate, wheelDiameter, frictionCoefficient = validateWheelSpec(wheelSpec, wheelIndex)
        freeSpeed = unhinderedSpeed(flowRate, wheelDiameter)
        lostSpeed = frictionLoss(freeSpeed, frictionCoefficient)
        netSpeed = freeSpeed - lostSpeed
        finalPower = applySplashPenalty(netSpeed)
        powerOutputList.append(finalPower)
    return powerOutputList


def describeMill(wheelSpec, powerValue):
    flowRate, wheelDiameter, frictionCoefficient = wheelSpec
    frictionPercent = frictionCoefficient * 100.0
