import math

def normalize_bearing(bearing_degrees):
    return bearing_degrees % 360.0


def compute_step_time(pace_count, difficulty_multiplier):
    return pace_count * difficulty_multiplier


def displace(east_coordinate, north_coordinate, pace_count, heading_degrees):
    heading_radians = math.radians(heading_degrees)
    new_east = east_coordinate + pace_count * math.sin(heading_radians)
    new_north = north_coordinate + pace_count * math.cos(heading_radians)
    return new_east, new_north


def validate_instruction(raw_instruction, step_index):
    if len(raw_instruction) != 3:
        raise ValueError("instruction %d must have 3 fields" % step_index)
    pace_count, bearing_change, difficulty_multiplier = raw_instruction
    if pace_count < 0:
        raise ValueError("instruction %d has negative paces" % step_index)
    if difficulty_multiplier <= 0:
        raise ValueError("instruction %d has non-positive terrain factor" % step_index)
    return float(pace_count), float(bearing_change), float(difficulty_multiplier)


def navigate(instructions):
    total_time = 0.0
    current_heading = 0.0
    east_coordinate = 0.0
    north_coordinate = 0.0
    for step_index, raw_instruction in enumerate(instructions):
        pace_count, bearing_change, difficulty_multiplier = validate_instruction(
            raw_instruction, step_index
        )
        total_time += compute_step_time(pace_count, difficulty_multiplier)
        current_heading = normalize_bearing(current_heading + bearing_change)
        east_coordinate, north_coordinate = displace(
            east_coordinate, north_coordinate, pace_count, current_heading
        )
    straight_line_distance = math.hypot(east_coordinate, north_coordinate)
    return (round(total_time, 1), round(straight_line_distance, 1))


