WORD_NUMBER_MAP = {
    "one": 1, "two": 2, "three": 3, "four": 4, "five": 5,
    "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
}
BASE_DECAY_MULTIPLIER = 15
AIR_RESISTANCE_THRESHOLD = 60.0
EXCESS_CAP_RATIO = 0.5


def parse_friction_rating(raw_rating):
    """Turn a friction rating ('five', '5' or 5) into a number from 1 to 10."""
    if isinstance(raw_rating, str):
        cleaned_rating_text = raw_rating.strip().lower()
        if cleaned_rating_text in WORD_NUMBER_MAP:
            numeric_rating = float(WORD_NUMBER_MAP[cleaned_rating_text])
        else:
            numeric_rating = float(cleaned_rating_text)
    else:
        numeric_rating = float(raw_rating)
    if not 1.0 <= numeric_rating <= 10.0:
        raise ValueError("friction rating must lie between one and ten")
    return numeric_rating


def compute_decay_rate(friction_rating, bearing_efficiency):
    """Baseline decay from the string, reduced by the bearing efficiency factor."""
    if bearing_efficiency <= 0:
        raise ValueError("bearing efficiency factor must be positive")
    baseline_decay_rate = friction_rating * BASE_DECAY_MULTIPLIER
    adjusted_decay_rate = baseline_decay_rate * bearing_efficiency
    return adjusted_decay_rate


def apply_air_resistance_cap(raw_duration):
    """Long spins lose part of the time above sixty seconds to air resistance."""
    if raw_duration <= AIR_RESISTANCE_THRESHOLD:
        return raw_duration
    excess_duration = raw_duration - AIR_RESISTANCE_THRESHOLD
    max_allowed_excess = raw_duration * EXCESS_CAP_RATIO
    return AIR_RESISTANCE_THRESHOLD + min(excess_duration, max_allowed_excess)


def predict(tricks):
    """Return the remaining spin time, in seconds, for every trick described."""
    spin_time_list = []
    for initial_spin, friction_rating, bearing_efficiency in tricks:
        if initial_spin <= 0:
            raise ValueError("initial spin must be a positive number of revolutions")
        numeric_friction_rating = parse_friction_rating(friction_rating)
        adjusted_decay_rate = compute_decay_rate(numeric_friction_rating, bearing_efficiency)
        raw_duration = initial_spin / adjusted_decay_rate
        final_spin_time = apply_air_resistance_cap(raw_duration)
        spin_time_list.append(round(final_spin_time, 2))
    return spin_time_list


def format_spin_report(tricks, spin_time_list):
    """Build one readable report line per trick."""
    report_lines = []
    for trick_index, (trick_data, spin_time) in enumerate(zip(tricks, spin_time_list), start=1):
        initial_spin, friction_rating, bearing_efficiency = trick_data
        report_lines.append(
            "Trick {}: {} rpm, friction {}, bearing {} -> {:.2f} s".format(
                trick_index, initial_spin, friction_rating, bearing_efficiency, spin_time
            )
        )
    return report_lines


def main():
    trick_input_list = [
        (6000, 5, 0.8),
        (9000, "three", 1.2),
        (12000, "2", 0.5),
    ]
    predicted_spin_times = predict(trick_input_list)
    for report_line in format_spin_report(trick_input_list, predicted_spin_times):
        print(report_line)
    longest_spin_time = max(predicted_spin_times)
    print("Longest predicted spin: {:.2f} seconds".format(longest_spin_time))


if __name__ == "__main__":
