def validate_stroke(stroke_entry):
    if len(stroke_entry) != 3:
        raise ValueError("each stroke needs velocity, angle and friction")
    initial_velocity, impact_angle, friction_coefficient = stroke_entry
    if initial_velocity <= 0:
        raise ValueError("initial velocity must be positive")
    if not 0 <= impact_angle <= 90:
        raise ValueError("impact angle must lie between 0 and 90 degrees")
    if friction_coefficient <= 0:
        raise ValueError("friction coefficient must be positive")
    return float(initial_velocity), float(impact_angle), float(friction_coefficient)


def deflection_penalty(impact_angle):
    return impact_angle / 90.0


def rolling_distance(current_velocity, friction_coefficient):
    return current_velocity / friction_coefficient


def exit_velocity(initial_velocity, impact_angle):
    return initial_velocity - deflection_penalty(impact_angle)


def putt(strokes):
    total_distances = []
    for stroke_entry in strokes:
        initial_velocity, impact_angle, friction_coefficient = validate_stroke(stroke_entry)
        pre_impact_distance = rolling_distance(initial_velocity, friction_coefficient)
        velocity_after_wall = exit_velocity(initial_velocity, impact_angle)
        post_impact_distance = rolling_distance(velocity_after_wall, friction_coefficient)
        total_distances.append(pre_impact_distance + post_impact_distance)
    return total_distances


def summarise_strokes(strokes, total_distances):
    report_lines = []
    for stroke_entry, travel_distance in zip(strokes, total_distances):
        initial_velocity, impact_angle, friction_coefficient = stroke_entry
        report_lines.append(
            "v={0:.1f} angle={1:g} friction={2:g} -> {3:.2f} units".format(
                initial_velocity, impact_angle, friction_coefficient, travel_distance
            )
        )
    return report_lines


def longest_travel(total_distances):
    best_index = 0
    max_distance = total_distances[0]
    for current_index, travel_distance in enumerate(total_distances):
        if travel_distance > max_distance:
            max_distance = travel_distance
            best_index = current_index
    return best_index, max_distance


def main():
    stroke_list = [(10.0, 45, 0.5), (12.5, 90, 0.8), (7.0, 0, 0.25)]
    total_distances = putt(stroke_list)
