        print(report_line)
    best_index, max_distance = longest_travel(total_distances)
    print("longest travel: stroke {0} at {1:.2f} units".format(best_index + 1, max_distance))
    average_distance = sum(total_distances) / len(total_distances)
    print("average travel: {0:.2f} units".format(average_distance))


