def validate_dune_record(dune_record):
    if len(dune_record) != 3:
        raise ValueError("each dune record needs wind speed, grain size and months")
    wind_speed, grain_size, months_elapsed = dune_record
    if wind_speed < 0:
        raise ValueError("wind speed cannot be negative")
    if grain_size <= 0:
        raise ValueError("sand grain size must be greater than zero")
    if months_elapsed < 0:
        raise ValueError("months elapsed cannot be negative")
    return wind_speed, grain_size, months_elapsed


def base_migration_rate(wind_speed):
    return (wind_speed ** 2) / 100.0


def adjusted_migration_rate(wind_speed, grain_size):
    return base_migration_rate(wind_speed) / grain_size


def compaction_factor(months_elapsed):
    full_year_count = int(months_elapsed) // 12
    return max(0.0, 1.0 - 0.05 * full_year_count)


def migration_distance(wind_speed, grain_size, months_elapsed):
    monthly_rate = adjusted_migration_rate(wind_speed, grain_size)
    raw_distance = monthly_rate * months_elapsed
    return raw_distance * compaction_factor(months_elapsed)


def track(dunes):
    final_distances = []
    for dune_record in dunes:
        wind_speed, grain_size, months_elapsed = validate_dune_record(dune_record)
        final_distances.append(migration_distance(wind_speed, grain_size, months_elapsed))
    return final_distances


def format_dune_report(dunes, distance_list):
    report_lines = []
    for dune_record, total_distance in zip(dunes, distance_list):
        wind_speed, grain_size, months_elapsed = dune_record
        penalty_percent = (1.0 - compaction_factor(months_elapsed)) * 100.0
        report_lines.append(
            "wind {0} km/h, grain {1} mm, {2} months -> {3:.2f} m "
            "(compaction penalty {4:.0f}%)".format(
                wind_speed, grain_size, months_elapsed, total_distance, penalty_percent
            )
        )
    return "\n".join(report_lines)


def fastest_shifting_dune(dunes, distance_list):
    best_index = 0
    for current_index, current_distance in enumerate(distance_list):
        if current_distance > distance_list[best_index]:
            best_index = current_index
    return dunes[best_index], distance_list[best_index]


def main():
    dune_samples = [(20, 0.5, 24), (35, 1.2, 18), (12, 0.25, 6), (48, 2.0, 36)]
    distance_list = track(dune_samples)
    print(format_dune_report(dune_samples, distance_list))
    leading_dune, leading_distance = fastest_shifting_dune(dune_samples, distance_list)
    print("largest shift: {0} moves {1:.2f} m".format(leading_dune, leading_distance))
    total_shift = sum(distance_list)
    average_shift = total_shift / len(distance_list)
    print("total shift: {0:.2f} m, average shift: {1:.2f} m".format(total_shift, average_shift))


if __name__ == "__main__":
    main()

