        raise ValueError("each dune record needs wind speed, grain size and months")
    windSpeed, grainSize, monthsElapsed = duneRecord
    if windSpeed < 0:
        raise ValueError("wind speed cannot be negative")
    if grainSize <= 0:
        raise ValueError("sand grain size must be greater than zero")
    if monthsElapsed < 0:
        raise ValueError("months elapsed cannot be negative")
    return windSpeed, grainSize, monthsElapsed


def baseMigrationRate(windSpeed):
    return (windSpeed ** 2) / 100.0


def adjustedMigrationRate(windSpeed, grainSize):
    return baseMigrationRate(windSpeed) / grainSize


def compactionFactor(monthsElapsed):
    fullYearCount = int(monthsElapsed) // 12
    return max(0.0, 1.0 - 0.05 * fullYearCount)


def migrationDistance(windSpeed, grainSize, monthsElapsed):
    monthlyRate = adjustedMigrationRate(windSpeed, grainSize)
    rawDistance = monthlyRate * monthsElapsed
    return rawDistance * compactionFactor(monthsElapsed)


def track(dunes):
    finalDistances = []
    for duneRecord in dunes:
        windSpeed, grainSize, monthsElapsed = validateDuneRecord(duneRecord)
        finalDistances.append(migrationDistance(windSpeed, grainSize, monthsElapsed))
    return finalDistances


def formatDuneReport(dunes, distanceList):
    reportLines = []
    for duneRecord, totalDistance in zip(dunes, distanceList):
        windSpeed, grainSize, monthsElapsed = duneRecord
        penaltyPercent = (1.0 - compactionFactor(monthsElapsed)) * 100.0
        reportLines.append(
            "wind {0} km/h, grain {1} mm, {2} months -> {3:.2f} m "
            "(compaction penalty {4:.0f}%)".format(
                windSpeed, grainSize, monthsElapsed, totalDistance, penaltyPercent
            )
        )
    return "\n".join(reportLines)


def fastestShiftingDune(dunes, distanceList):
    bestIndex = 0
    for currentIndex, currentDistance in enumerate(distanceList):
        if currentDistance > distanceList[bestIndex]:
            bestIndex = currentIndex
    return dunes[bestIndex], distanceList[bestIndex]


def main():
    duneSamples = [(20, 0.5, 24), (35, 1.2, 18), (12, 0.25, 6), (48, 2.0, 36)]
    distanceList = track(duneSamples)
    print(formatDuneReport(duneSamples, distanceList))
    leadingDune, leadingDistance = fastestShiftingDune(duneSamples, distanceList)
    print("largest shift: {0} moves {1:.2f} m".format(leadingDune, leadingDistance))
    totalShift = sum(distanceList)
    averageShift = totalShift / len(distanceList)
    print("total shift: {0:.2f} m, average shift: {1:.2f} m".format(totalShift, averageShift))


if __name__ == "__main__":
    main()

