BANK_ANGLE_THRESHOLD = 20.0
BANK_BONUS_PER_DEGREE = 0.2
REFERENCE_ICE_TEMPERATURE = -5.0
FRICTION_PENALTY_PER_DEGREE = 0.5
SPEED_RETENTION_FACTOR = 0.9
MAX_VELOCITY_FACTOR = 1.2


def compute_bank_bonus(bank_angle):
    excess_angle = bank_angle - BANK_ANGLE_THRESHOLD
    if excess_angle <= 0:
        return 0.0
    return excess_angle * BANK_BONUS_PER_DEGREE


def compute_friction_penalty(ice_temperature):
    temperature_excess = ice_temperature - REFERENCE_ICE_TEMPERATURE
    if temperature_excess <= 0:
        return 0.0
    return temperature_excess * FRICTION_PENALTY_PER_DEGREE


def validate_curve(curve_data):
    if len(curve_data) != 3:
        raise ValueError("each curve needs bank angle, entry velocity and ice temperature")
    bank_angle, entry_velocity, ice_temperature = curve_data
    if bank_angle < 0:
        raise ValueError("bank angle cannot be negative")
    if entry_velocity < 0:
        raise ValueError("entry velocity cannot be negative")
    return float(bank_angle), float(entry_velocity), float(ice_temperature)


def compute_exit_velocity(bank_angle, entry_velocity, ice_temperature):
    retained_speed = entry_velocity * SPEED_RETENTION_FACTOR
    bank_bonus = compute_bank_bonus(bank_angle)
    friction_penalty = compute_friction_penalty(ice_temperature)
    raw_velocity = retained_speed + bank_bonus - friction_penalty
    velocity_ceiling = entry_velocity * MAX_VELOCITY_FACTOR
    if raw_velocity > velocity_ceiling:
        return velocity_ceiling
    if raw_velocity < 0.0:
        return 0.0
    return raw_velocity


def race(curves):
    exit_velocities = []
    for curve_data in curves:
        bank_angle, entry_velocity, ice_temperature = validate_curve(curve_data)
        exit_velocities.append(compute_exit_velocity(bank_angle, entry_velocity, ice_temperature))
    return exit_velocities


def format_run_report(curves, exit_velocities):
    report_lines = []
    for curve_index, (curve_data, exit_velocity) in enumerate(zip(curves, exit_velocities), start=1):
        bank_angle, entry_velocity, ice_temperature = curve_data
        velocity_change = exit_velocity - entry_velocity
        report_lines.append(
            "curve {0}: {1:.0f} deg bank, {2:.1f} C ice, {3:.2f} -> {4:.2f} m/s ({5:+.2f})".format(
                curve_index, bank_angle, ice_temperature, entry_velocity, exit_velocity, velocity_change
            )
        )
    return "\n".join(report_lines)


def main():
