import math


def validate_shot(shot_description):
    """Check that a single shot tuple holds usable physical values."""
    if len(shot_description) != 3:
        raise ValueError("each shot needs elasticity, payload weight and draw length")
    band_constant, payload_weight, draw_length = shot_description
    if band_constant <= 0:
        raise ValueError("band elasticity constant must be positive")
    if payload_weight <= 0:
        raise ValueError("payload weight must be positive")
    if draw_length < 0:
        raise ValueError("draw length cannot be negative")
    return float(band_constant), float(payload_weight), float(draw_length)


def stored_energy(band_constant, draw_length):
    """Elastic energy held by the drawn band."""
    return band_constant * (draw_length ** 2) / 2.0


def launch_velocity(energy_value, payload_weight):
    """Speed given to the pouch payload once the band is released."""
    return math.sqrt(energy_value / payload_weight)


def truncate_two_places(raw_value):
    """Cut a distance down to centimetre precision without rounding up."""
    return math.floor(raw_value * 100) / 100


def launch(shots):
    """Return the flight distance in metres for every described shot."""
    aerodynamic_factor = 3.5
    heavy_payload_limit = 50.0
    heavy_payload_penalty = 0.9
    flight_distances = []
    for shot_description in shots:
        band_constant, payload_weight, draw_length = validate_shot(shot_description)
        energy_value = stored_energy(band_constant, draw_length)
        velocity_value = launch_velocity(energy_value, payload_weight)
        base_distance = velocity_value * aerodynamic_factor
        if payload_weight > heavy_payload_limit:
            base_distance *= heavy_payload_penalty
        flight_distances.append(truncate_two_places(base_distance))
    return flight_distances


def build_report(shots, flight_distances):
    """Pair each shot with its outcome as human readable lines."""
    report_lines = []
    for shot_description, distance_value in zip(shots, flight_distances):
        band_constant, payload_weight, draw_length = shot_description
        report_lines.append(
            "k={0} payload={1}g draw={2}cm -> {3} m".format(
                band_constant, payload_weight, draw_length, distance_value
            )
        )
    return report_lines


def main():
    shot_table = [(10.0, 40, 20), (12.5, 75, 25), (8.0, 20, 15)]
    flight_distances = launch(shot_table)
    for report_line in build_report(shot_table, flight_distances):
        print(report_line)
    longest_shot = max(flight_distances)
    print("Best range: {0} m".format(longest_shot))
    print(flight_distances)


if __name__ == "__main__":
    main()

