def compute_rebound_energy(compression_distance):
    return compression_distance ** 2 * SPRING_EFFICIENCY_FACTOR


def compute_hop_height(jump_record):
    compression_distance, rider_weight, softness_penalty = validate_jump_record(jump_record)
    rebound_energy = compute_rebound_energy(compression_distance)
    theoretical_height = rebound_energy / rider_weight
    energy_loss_amount = theoretical_height * softness_penalty
    final_height = theoretical_height - energy_loss_amount
    if final_height < 0:
        final_height = 0.0
    return final_height


def bounce(jumps):
    height_results = []
    for jump_record in jumps:
        height_results.append(compute_hop_height(jump_record))
    return height_results


def summarize_session(jumps):
    achieved_heights = bounce(jumps)
    if not achieved_heights:
        return {"jumpCount": 0, "best_height": 0.0, "average_height": 0.0}
    total_height = sum(achieved_heights)
    jump_count = len(achieved_heights)
    return {
        "jumpCount": jump_count,
        "best_height": max(achieved_heights),
        "average_height": total_height / jump_count,
