def validate_glacier_record(glacier_record):
    if len(glacier_record) != 3:
        raise ValueError("each glacier record needs snowfall, temperature and decades")
    annual_snowfall, summer_temperature, decades_elapsed = glacier_record
    if annual_snowfall < 0:
        raise ValueError("annual snowfall cannot be negative")
    if decades_elapsed < 0:
        raise ValueError("decades elapsed cannot be negative")
    return float(annual_snowfall), float(summer_temperature), float(decades_elapsed)


def compute_accumulation_rate(annual_snowfall):
    return BASELINE_RATE_PER_DECADE * (annual_snowfall / SNOWFALL_REFERENCE_DEPTH)


def apply_melting_penalty(accumulation_rate, summer_temperature):
    if summer_temperature > 0:
        return accumulation_rate * MELT_PENALTY_FACTOR
    return accumulation_rate


def project_single_glacier(glacier_record):
    annual_snowfall, summer_temperature, decades_elapsed = validate_glacier_record(glacier_record)
    active_rate = compute_accumulation_rate(annual_snowfall)
    adjusted_rate = apply_melting_penalty(active_rate, summer_temperature)
    return adjusted_rate * decades_elapsed


