IDLE_OVERHEAD_MILLILITRES = 10.0
FUEL_DIVISOR = 50.0
SHARPNESS_REFERENCE = 100.0


def validate_cut_entry(cut_entry, entry_index):
    if len(cut_entry) != 3:
        raise ValueError("cut %d must hold density, sharpness and volume" % entry_index)
    density_rating, sharpness_percentage, cut_volume = cut_entry
    if density_rating <= 0:
        raise ValueError("cut %d has a non-positive density rating" % entry_index)
    if sharpness_percentage <= 0:
        raise ValueError("cut %d has a non-positive blade sharpness" % entry_index)
    if cut_volume < 0:
        raise ValueError("cut %d has a negative cut volume" % entry_index)
    return float(density_rating), float(sharpness_percentage), float(cut_volume)


def compute_base_effort(density_rating, cut_volume):
    return density_rating * cut_volume


def apply_tool_condition(base_effort, sharpness_percentage):
    return base_effort * SHARPNESS_REFERENCE / sharpness_percentage


def estimate_fuel_for_cut(density_rating, sharpness_percentage, cut_volume):
    base_effort = compute_base_effort(density_rating, cut_volume)
    adjusted_effort = apply_tool_condition(base_effort, sharpness_percentage)
    raw_fuel_millilitres = adjusted_effort / FUEL_DIVISOR
    return round(raw_fuel_millilitres + IDLE_OVERHEAD_MILLILITRES, 1)


def carve(cuts):
    fuel_per_cut = []
    for entry_index, cut_entry in enumerate(cuts):
        density_rating, sharpness_percentage, cut_volume = validate_cut_entry(cut_entry, entry_index)
        fuel_per_cut.append(estimate_fuel_for_cut(density_rating, sharpness_percentage, cut_volume))
    return fuel_per_cut


def summarise_fuel_usage(fuel_per_cut):
    total_fuel = round(sum(fuel_per_cut), 1)
    heaviest_cut_fuel = max(fuel_per_cut) if fuel_per_cut else 0.0
    average_fuel = round(total_fuel / len(fuel_per_cut), 1) if fuel_per_cut else 0.0
    return total_fuel, heaviest_cut_fuel, average_fuel


def format_fuel_report(cuts, fuel_per_cut):
    report_lines = []
    for cut_entry, fuel_used in zip(cuts, fuel_per_cut):
        density_rating, sharpness_percentage, cut_volume = cut_entry
        report_lines.append(
            "density %.1f, sharpness %d%%, volume %d cc -> %.1f mL"
            % (density_rating, sharpness_percentage, cut_volume, fuel_used)
        )
    total_fuel, heaviest_cut_fuel, average_fuel = summarise_fuel_usage(fuel_per_cut)
    report_lines.append("total %.1f mL, worst cut %.1f mL, average %.1f mL" % (total_fuel, heaviest_cut_fuel, average_fuel))
    return "\n".join(report_lines)


