MAX_LOOP_DIAMETER = 3.0
CENTRIFUGAL_DIVISOR = 100.0
TRAVEL_ALLOWANCE_FACTOR = 0.5


def validate_lasso_spec(lasso_spec, spec_index):
    if len(lasso_spec) != 3:
        raise ValueError("lasso %d must contain exactly three values" % spec_index)
    stiffness_rating, rotation_speed, target_distance = lasso_spec
    if stiffness_rating <= 0:
        raise ValueError("lasso %d has a non-positive stiffness rating" % spec_index)
    if rotation_speed < 0:
        raise ValueError("lasso %d has a negative rotation speed" % spec_index)
    if target_distance < 0:
        raise ValueError("lasso %d has a negative target distance" % spec_index)
    return float(stiffness_rating), float(rotation_speed), float(target_distance)


def compute_loop_diameter(stiffness_rating, rotation_speed, target_distance):
    centrifugal_expansion = (rotation_speed ** 2) / CENTRIFUGAL_DIVISOR
    restricted_expansion = centrifugal_expansion / stiffness_rating
    travel_allowance = target_distance * TRAVEL_ALLOWANCE_FACTOR
    total_diameter = restricted_expansion + travel_allowance
    return min(total_diameter, MAX_LOOP_DIAMETER)


def twirl(lassos):
    loop_diameters = []
    for spec_index, lasso_spec in enumerate(lassos):
        stiffness_rating, rotation_speed, target_distance = validate_lasso_spec(lasso_spec, spec_index)
        loop_diameters.append(compute_loop_diameter(stiffness_rating, rotation_speed, target_distance))
    return loop_diameters


def describe_throw(lasso_spec, loop_diameter):
    stiffness_rating, rotation_speed, target_distance = lasso_spec
    if loop_diameter >= MAX_LOOP_DIAMETER:
        stability_note = "capped for aerodynamic stability"
    elif loop_diameter >= target_distance * TRAVEL_ALLOWANCE_FACTOR + 1.0:
        stability_note = "wide and confident"
    else:
        stability_note = "tight loop, spin faster"
    return "stiffness %.1f at %g rpm toward %.1f m -> %.2f m loop (%s)" % (
        stiffness_rating,
        rotation_speed,
        target_distance,
        loop_diameter,
        stability_note,
    )


def build_throw_report(lasso_list):
    computed_diameters = twirl(lasso_list)
    report_lines = []
    for lasso_spec, loop_diameter in zip(lasso_list, computed_diameters):
        report_lines.append(describe_throw(lasso_spec, loop_diameter))
    widest_diameter = max(computed_diameters)
    average_diameter = sum(computed_diameters) / len(computed_diameters)
    report_lines.append("widest loop: %.2f m, average loop: %.2f m" % (widest_diameter, average_diameter))
    return "\n".join(report_lines)


def main():
    lasso_specs = [
        (5.0, 30, 4.0),
        (12.0, 40, 1.0),
        (8.0, 25, 0.0),
        (2.5, 10, 6.0),
    ]
    print(twirl(lasso_specs))
    print(build_throw_report(lasso_specs))


