GRAVITY_THRESHOLD = 50.0


def validate_door_spec(door_spec):
    if len(door_spec) != 3:
        raise ValueError("each door spec needs mass, length and hinge strength")
    log_mass, pendulum_length, hinge_strength = door_spec
    if log_mass <= 0 or pendulum_length <= 0:
        raise ValueError("ram log mass and pendulum length must be positive")
    if hinge_strength <= 0:
        raise ValueError("door hinge strength must be positive")
    return float(log_mass), float(pendulum_length), float(hinge_strength)


def swing_kinetic_energy(log_mass, pendulum_length):
    return log_mass * pendulum_length ** 2


def fracture_impact(log_mass, pendulum_length, hinge_strength):
    kinetic_energy = swing_kinetic_energy(log_mass, pendulum_length)
    return kinetic_energy / hinge_strength


def breach_probability(door_spec):
    log_mass, pendulum_length, hinge_strength = validate_door_spec(door_spec)
    impact_value = fracture_impact(log_mass, pendulum_length, hinge_strength)
    if impact_value > GRAVITY_THRESHOLD:
        return 1.0
    return impact_value / GRAVITY_THRESHOLD


def breach(doors):
    return [breach_probability(door_spec) for door_spec in doors]


def classify_probability(probability_value):
    if probability_value >= 1.0:
        return "certain breach"
    if probability_value >= 0.5:
        return "likely breach"
    if probability_value > 0.0:
        return "weak blow"
    return "no effect"


def format_siege_report(doors, probability_list):
    report_lines = []
    for door_index, (door_spec, probability_value) in enumerate(zip(doors, probability_list), start=1):
        log_mass, pendulum_length, hinge_strength = door_spec
        outcome_label = classify_probability(probability_value)
        report_lines.append(
            "Door {0}: ram {1} kg on {2} m swing vs hinge {3} -> {4:.2%} ({5})".format(
                door_index, log_mass, pendulum_length, hinge_strength,
                probability_value, outcome_label
            )
        )
    return "\n".join(report_lines)


def summarize_siege(doors):
    probability_list = breach(doors)
    total_probability = sum(probability_list)
    average_probability = total_probability / len(probability_list)
    best_target_index = max(range(len(probability_list)), key=probability_list.__getitem__)
    return probability_list, average_probability, best_target_index


def main():
    siege_plan = [(100, 4, 200), (400, 6, 120), (50, 2, 900), (1200, 5, 300)]
    probability_list, average_probability, best_target_index = summarize_siege(siege_plan)
    print(format_siege_report(siege_plan, probability_list))
    print("Average breach probability: {0:.2%}".format(average_probability))
    print("Best target: door {0}".format(best_target_index + 1))
    print(breach([(100, 4, 200)]))


if __name__ == "__main__":
    main()

