        raise ValueError("each door spec needs mass, length and hinge strength")
    logMass, pendulumLength, hingeStrength = doorSpec
    if logMass <= 0 or pendulumLength <= 0:
        raise ValueError("ram log mass and pendulum length must be positive")
    if hingeStrength <= 0:
        raise ValueError("door hinge strength must be positive")
    return float(logMass), float(pendulumLength), float(hingeStrength)


def swingKineticEnergy(logMass, pendulumLength):
    return logMass * pendulumLength ** 2


def fractureImpact(logMass, pendulumLength, hingeStrength):
    kineticEnergy = swingKineticEnergy(logMass, pendulumLength)
    return kineticEnergy / hingeStrength


def breachProbability(doorSpec):
    logMass, pendulumLength, hingeStrength = validateDoorSpec(doorSpec)
    impactValue = fractureImpact(logMass, pendulumLength, hingeStrength)
    if impactValue > GRAVITY_THRESHOLD:
        return 1.0
    return impactValue / GRAVITY_THRESHOLD


def breach(doors):
    return [breachProbability(doorSpec) for doorSpec in doors]


def classifyProbability(probabilityValue):
    if probabilityValue >= 1.0:
        return "certain breach"
    if probabilityValue >= 0.5:
        return "likely breach"
    if probabilityValue > 0.0:
        return "weak blow"
    return "no effect"


def formatSiegeReport(doors, probabilityList):
    reportLines = []
    for doorIndex, (doorSpec, probabilityValue) in enumerate(zip(doors, probabilityList), start=1):
        logMass, pendulumLength, hingeStrength = doorSpec
        outcomeLabel = classifyProbability(probabilityValue)
        reportLines.append(
            "Door {0}: ram {1} kg on {2} m swing vs hinge {3} -> {4:.2%} ({5})".format(
                doorIndex, logMass, pendulumLength, hingeStrength,
                probabilityValue, outcomeLabel
            )
        )
    return "\n".join(reportLines)


def summarizeSiege(doors):
    probabilityList = breach(doors)
    totalProbability = sum(probabilityList)
    averageProbability = totalProbability / len(probabilityList)
    bestTargetIndex = max(range(len(probabilityList)), key=probabilityList.__getitem__)
    return probabilityList, averageProbability, bestTargetIndex


def main():
    siegePlan = [(100, 4, 200), (400, 6, 120), (50, 2, 900), (1200, 5, 300)]
    probabilityList, averageProbability, bestTargetIndex = summarizeSiege(siegePlan)
    print(formatSiegeReport(siegePlan, probabilityList))
    print("Average breach probability: {0:.2%}".format(averageProbability))
    print("Best target: door {0}".format(bestTargetIndex + 1))
    print(breach([(100, 4, 200)]))


if __name__ == "__main__":
    main()

