BASE_CRUISE_SPEED = 60.0
NAVIGATION_DELAY_PER_ANOMALY = 0.2


def validate_flight_record(flight_record):
    if len(flight_record) != 3:
        raise ValueError("each flight needs distance, headwind speed and anomaly strength")
    flight_distance, headwind_speed, anomaly_strength = flight_record
    if flight_distance < 0:
        raise ValueError("flight distance cannot be negative: %r" % (flight_distance,))
    if anomaly_strength < 0:
        raise ValueError("anomaly strength cannot be negative: %r" % (anomaly_strength,))
    return float(flight_distance), float(headwind_speed), float(anomaly_strength)


def compute_ground_speed(headwind_speed):
    ground_speed = BASE_CRUISE_SPEED - headwind_speed
    if ground_speed <= 0:
        raise ValueError("headwind of %r km/h grounds the pigeon" % (headwind_speed,))
    return ground_speed


def compute_navigation_delay(anomaly_strength):
    return anomaly_strength * NAVIGATION_DELAY_PER_ANOMALY


def compute_arrival_time(flight_record):
    flight_distance, headwind_speed, anomaly_strength = validate_flight_record(flight_record)
    ground_speed = compute_ground_speed(headwind_speed)
    raw_flight_time = flight_distance / ground_speed
    navigation_delay = compute_navigation_delay(anomaly_strength)
    return round(raw_flight_time + navigation_delay, 2)


def home(flights):
    arrival_times = []
    for flight_record in flights:
        arrival_times.append(compute_arrival_time(flight_record))
