def validate_candle_entry(candle_entry, entry_index):
    if len(candle_entry) != 3:
        raise ValueError(
            "candle %d must contain melting point, wick thickness and draft speed"
            % entry_index
        )
    melting_point_celsius, wick_thickness_mm, draft_speed = candle_entry
    if wick_thickness_mm <= 0:
        raise ValueError("candle %d has a non-positive wick thickness" % entry_index)
