        base_burn_rate *= HARDNESS_REDUCTION_FACTOR
    draft_acceleration = draft_speed * DRAFT_ACCELERATION_FACTOR
    return base_burn_rate + draft_acceleration


def burn(candles):
    burn_time_list = []
