CORE_RATE_PER_DEGREE = 0.5
INFINITE_LIFESPAN_MARKER = -1


def compute_core_melt_rate(ambient_temperature):
    """Core melt rate in decimeters per hour for a given ambient temperature."""
    return ambient_temperature * CORE_RATE_PER_DEGREE


def compute_exposed_melt_rate(ambient_temperature, complexity_multiplier):
    """Core rate scaled by how much surface the sculpture exposes."""
    core_melt_rate = compute_core_melt_rate(ambient_temperature)
    return core_melt_rate * complexity_multiplier


def compute_melt_time(starting_volume, complexity_multiplier, ambient_temperature):
    """Hours until a single sculpture collapses, or -1 when it never melts."""
    if ambient_temperature <= 0:
        return INFINITE_LIFESPAN_MARKER
    exposed_melt_rate = compute_exposed_melt_rate(ambient_temperature, complexity_multiplier)
    if exposed_melt_rate <= 0:
        return INFINITE_LIFESPAN_MARKER
    return starting_volume / exposed_melt_rate


def melt(sculptures):
    """Return a list of hours until total collapse for every sculpture."""
    collapse_times = []
    for sculpture_entry in sculptures:
        starting_volume, complexity_multiplier, ambient_temperature = sculpture_entry
        collapse_times.append(
            compute_melt_time(starting_volume, complexity_multiplier, ambient_temperature)
        )
    return collapse_times


def describe_lifespan(hours_until_collapse):
    """Human readable lifespan for one computed melt time."""
    if hours_until_collapse == INFINITE_LIFESPAN_MARKER:
        return "never melts (freezing or colder)"
    whole_hours = int(hours_until_collapse)
    leftover_minutes = round((hours_until_collapse - whole_hours) * 60)
    return "{0} h {1} min".format(whole_hours, leftover_minutes)


def build_melt_report(sculptures):
    """Pair each sculpture description with its lifespan summary."""
    report_lines = []
    lifespan_hours = melt(sculptures)
    for sculpture_index, sculpture_entry in enumerate(sculptures):
        starting_volume, complexity_multiplier, ambient_temperature = sculpture_entry
        lifespan_text = describe_lifespan(lifespan_hours[sculpture_index])
        report_lines.append(
            "{0} dm3 x{1} at {2}C -> {3}".format(
                starting_volume, complexity_multiplier, ambient_temperature, lifespan_text
            )
        )
    return report_lines


def find_longest_lasting(sculptures):
    """Index of the sculpture that survives longest; eternal ones win outright."""
    lifespan_hours = melt(sculptures)
    best_index = 0
    best_lifespan = lifespan_hours[0]
    for current_index, current_lifespan in enumerate(lifespan_hours):
        if current_lifespan == INFINITE_LIFESPAN_MARKER:
            return current_index
        if current_lifespan > best_lifespan:
            best_index = current_index
            best_lifespan = current_lifespan
    return best_index


def main():
    gallery_sculptures = [(100, 2.0, 5), (250, 1.5, 12), (80, 0.8, -3), (60, 3.0, 20)]
    print(melt(gallery_sculptures))
    for report_line in build_melt_report(gallery_sculptures):
        print(report_line)
    winning_index = find_longest_lasting(gallery_sculptures)
    print("Longest lasting piece: #{0}".format(winning_index + 1))


if __name__ == "__main__":
    main()

