    wholeHours = int(hoursUntilCollapse)
    leftoverMinutes = round((hoursUntilCollapse - wholeHours) * 60)
    return "{0} h {1} min".format(wholeHours, leftoverMinutes)


def buildMeltReport(sculptures):
    """Pair each sculpture description with its lifespan summary."""
    reportLines = []
    lifespanHours = melt(sculptures)
    for sculptureIndex, sculptureEntry in enumerate(sculptures):
        startingVolume, complexityMultiplier, ambientTemperature = sculptureEntry
        lifespanText = describeLifespan(lifespanHours[sculptureIndex])
        reportLines.append(
            "{0} dm3 x{1} at {2}C -> {3}".format(
                startingVolume, complexityMultiplier, ambientTemperature, lifespanText
            )
        )
    return reportLines


def findLongestLasting(sculptures):
    """Index of the sculpture that survives longest; eternal ones win outright."""
    lifespanHours = melt(sculptures)
    bestIndex = 0
    bestLifespan = lifespanHours[0]
    for currentIndex, currentLifespan in enumerate(lifespanHours):
        if currentLifespan == INFINITE_LIFESPAN_MARKER:
            return currentIndex
        if currentLifespan > bestLifespan:
            bestIndex = currentIndex
            bestLifespan = currentLifespan
    return bestIndex


def main():
    gallerySculptures = [(100, 2.0, 5), (250, 1.5, 12), (80, 0.8, -3), (60, 3.0, 20)]
    print(melt(gallerySculptures))
    for reportLine in buildMeltReport(gallerySculptures):
        print(reportLine)
    winningIndex = findLongestLasting(gallerySculptures)
    print("Longest lasting piece: #{0}".format(winningIndex + 1))


