def parse_shipment(raw_shipment):
    origin_code, total_mass, purity_ratio = raw_shipment
    if total_mass < 0:
        raise ValueError("negative mass for origin " + str(origin_code))
    if not 0.0 <= purity_ratio <= 1.0:
        raise ValueError("purity out of range for origin " + str(origin_code))
    return str(origin_code), float(total_mass), float(purity_ratio)


def compute_shipment_yield(total_mass, purity_ratio):
    raw_yield = total_mass * purity_ratio
    if purity_ratio < 0.5:
        penalty_factor = 0.95
        return raw_yield * penalty_factor
    return raw_yield


def refine(shipments):
    total_usable_yield = 0.0
    best_origin_code = None
    best_single_yield = None
    for raw_shipment in shipments:
        origin_code, total_mass, purity_ratio = parse_shipment(raw_shipment)
        shipment_yield = compute_shipment_yield(total_mass, purity_ratio)
        total_usable_yield += shipment_yield
        if best_single_yield is None or shipment_yield > best_single_yield:
            best_single_yield = shipment_yield
            best_origin_code = origin_code
    return (total_usable_yield, best_origin_code)


def build_yield_table(shipments):
    yield_table = []
    for raw_shipment in shipments:
        origin_code, total_mass, purity_ratio = parse_shipment(raw_shipment)
        shipment_yield = compute_shipment_yield(total_mass, purity_ratio)
        was_penalised = purity_ratio < 0.5
        yield_table.append((origin_code, total_mass, purity_ratio,
                            shipment_yield, was_penalised))
    return yield_table


def format_yield_report(shipments):
    yield_table = build_yield_table(shipments)
    total_usable_yield, best_origin_code = refine(shipments)
    report_lines = ["origin      mass  purity     yield  penalty"]
    for origin_code, total_mass, purity_ratio, shipment_yield, was_penalised in yield_table:
        penalty_mark = "yes" if was_penalised else "no"
        report_lines.append("{:<8}{:>8.1f}{:>8.2f}{:>10.2f}{:>9}".format(
            origin_code, total_mass, purity_ratio, shipment_yield, penalty_mark))
    report_lines.append("total usable yield: {:.2f}".format(total_usable_yield))
    report_lines.append("best origin: {}".format(best_origin_code))
    return "\n".join(report_lines)


def main():
    delivery_manifest = [
        ["alpha", 100, 0.40],
        ["beta", 200, 0.80],
        ["gamma", 340, 0.49],
        ["delta", 75, 0.95],
    ]
    print(format_yield_report(delivery_manifest))
    total_usable_yield, best_origin_code = refine(delivery_manifest)
    average_yield = total_usable_yield / len(delivery_manifest)
    print("average yield per shipment: {:.2f}".format(average_yield))
    if best_origin_code is not None:
        print("schedule follow-up survey at {}".format(best_origin_code))


if __name__ == "__main__":
    main()

