def normalize_rotation_angle(raw_angle):
    """Return an equivalent angle between -180 and 180 degrees."""
    if raw_angle > 180 or raw_angle < -180:
        shifted_angle = (raw_angle + 180) % 360
        normalized_angle = shifted_angle - 180
        if normalized_angle == -180:
            normalized_angle = 180
        return normalized_angle
    return raw_angle


def validate_movement(movement_command):
    """Unpack a command tuple, raising ValueError on unusable data."""
    if len(movement_command) != 3:
        raise ValueError("each command needs a joint, an angle and a speed")
    joint_name, rotation_angle, movement_speed = movement_command
    if movement_speed <= 0:
        raise ValueError("speed for joint %r must be positive" % (joint_name,))
    return joint_name, rotation_angle, movement_speed


def compute_movement_time(normalized_angle, movement_speed):
    """Time needed to sweep the given angle at the given speed."""
    return abs(normalized_angle) / movement_speed


def calibrate(movements):
    total_time = 0.0
    max_absolute_angle = 0
    for movement_command in movements:
        joint_name, rotation_angle, movement_speed = validate_movement(movement_command)
        normalized_angle = normalize_rotation_angle(rotation_angle)
        total_time += compute_movement_time(normalized_angle, movement_speed)
        absolute_angle = abs(normalized_angle)
        if absolute_angle > max_absolute_angle:
            max_absolute_angle = absolute_angle
    return total_time, max_absolute_angle


def build_movement_report(movements):
    """Describe every command, returning report lines and the totals."""
    report_lines = []
    for movement_command in movements:
        joint_name, rotation_angle, movement_speed = validate_movement(movement_command)
        normalized_angle = normalize_rotation_angle(rotation_angle)
        elapsed_time = compute_movement_time(normalized_angle, movement_speed)
        report_lines.append(
            "%-8s %6d -> %6d deg at %5.1f deg/s : %6.2f s"
            % (joint_name, rotation_angle, normalized_angle, movement_speed, elapsed_time)
        )
    total_time, max_absolute_angle = calibrate(movements)
    report_lines.append("total time %.2f s, widest sweep %d deg" % (total_time, max_absolute_angle))
    return report_lines, total_time, max_absolute_angle


def main():
    movement_program = [
        ("elbow", 190, 10),
        ("wrist", -90, 5),
        ("shoulder", 450, 15),
        ("base", -270, 9),
    ]
    report_lines, total_time, max_absolute_angle = build_movement_report(movement_program)
    for report_line in report_lines:
        print(report_line)
    if total_time > 60:
        print("warning: calibration exceeds the one minute service window")
    if max_absolute_angle >= 180:
        print("warning: a joint reached its rotation limit")
    faulty_program = [("gripper", 45, 0)]
    try:
        calibrate(faulty_program)
    except ValueError as validation_error:
        print("rejected program:", validation_error)


if __name__ == "__main__":
    main()

