MIN_ALTITUDE_SEPARATION = 1000
MIN_SPEED_SEPARATION = 50


def validate_flight_record(flight_record):
    if len(flight_record) != 3:
        raise ValueError("each flight needs a callsign, an altitude and a speed")
    raw_callsign, raw_altitude, raw_speed = flight_record
    clean_callsign = str(raw_callsign).strip()
    if not clean_callsign:
        raise ValueError("flight callsign must not be empty")
    altitude_in_feet = float(raw_altitude)
    speed_in_knots = float(raw_speed)
    if altitude_in_feet < 0:
        raise ValueError("altitude of %s must not be negative" % clean_callsign)
    if speed_in_knots < 0:
        raise ValueError("speed of %s must not be negative" % clean_callsign)
    return clean_callsign, altitude_in_feet, speed_in_knots


def is_separation_violation(first_flight, second_flight):
    altitude_difference = abs(first_flight[1] - second_flight[1])
    speed_difference = abs(first_flight[2] - second_flight[2])
    return (altitude_difference < MIN_ALTITUDE_SEPARATION
            and speed_difference < MIN_SPEED_SEPARATION)


def monitor(aircraft):
    checked_flights = [validate_flight_record(entry) for entry in aircraft]
    seen_callsigns = set()
    for callsign, _altitude, _speed in checked_flights:
        if callsign in seen_callsigns:
            raise ValueError("duplicate callsign %s in traffic list" % callsign)
        seen_callsigns.add(callsign)
    violating_pairs = []
    total_flight_count = len(checked_flights)
    for first_index in range(total_flight_count):
        for second_index in range(first_index + 1, total_flight_count):
            leading_flight = checked_flights[first_index]
            trailing_flight = checked_flights[second_index]
            if is_separation_violation(leading_flight, trailing_flight):
                pair_of_callsigns = tuple(sorted((leading_flight[0], trailing_flight[0])))
                violating_pairs.append(pair_of_callsigns)
    violating_pairs.sort()
    return violating_pairs


def format_violation_report(violating_pairs):
    if not violating_pairs:
        return "No separation violations detected."
    report_lines = ["%d separation violation(s):" % len(violating_pairs)]
    for first_callsign, second_callsign in violating_pairs:
        report_lines.append("  %s <-> %s" % (first_callsign, second_callsign))
    return "\n".join(report_lines)


def main():
    current_traffic = [
        ("a1", 30000, 400),
        ("b2", 30500, 420),
        ("c3", 35000, 500),
        ("d4", 35400, 480),
        ("e5", 12000, 250),
    ]
    detected_violations = monitor(current_traffic)
    print(format_violation_report(detected_violations))
    clear_traffic_sample = [("f6", 10000, 300), ("g7", 20000, 300)]
    print(format_violation_report(monitor(clear_traffic_sample)))


if __name__ == "__main__":
    main()

