text_nat:
VOLUMETRIC_DIVISOR = 5000.0
HEAVY_FREIGHT_THRESHOLD = 50.0
HEAVY_FREIGHT_ZONE = "heavy freight"
STANDARD_PARCEL_ZONE = "standard parcel"


def compute_volumetric_weight(length_cm, width_cm):
    return (length_cm * width_cm) / VOLUMETRIC_DIVISOR


def compute_billable_weight(actual_weight, length_cm, width_cm):
    volumetric_weight = compute_volumetric_weight(length_cm, width_cm)
    return max(float(actual_weight), volumetric_weight)


def assign_zone(billable_weight):
    if billable_weight > HEAVY_FREIGHT_THRESHOLD:
        return HEAVY_FREIGHT_ZONE
    return STANDARD_PARCEL_ZONE


def validate_package(package_record):
    if len(package_record) != 4:
        raise ValueError("each package needs a tracking id, weight, length and width")
    tracking_id, actual_weight, length_cm, width_cm = package_record
    if not isinstance(tracking_id, int):
        raise ValueError("tracking id must be an integer")
    for measured_value in (actual_weight, length_cm, width_cm):
        if measured_value < 0:
            raise ValueError("weights and dimensions must not be negative")
    return tracking_id, actual_weight, length_cm, width_cm


def route(packages):
    total_billable_weight = 0.0
    heavy_freight_ids = []
    for package_record in packages:
        tracking_id, actual_weight, length_cm, width_cm = validate_package(package_record)
        billable_weight = compute_billable_weight(actual_weight, length_cm, width_cm)
        total_billable_weight += billable_weight
        if assign_zone(billable_weight) == HEAVY_FREIGHT_ZONE:
            heavy_freight_ids.append(tracking_id)
    return total_billable_weight, heavy_freight_ids


def build_manifest_lines(packages):
    manifest_lines = []
    for package_record in packages:
        tracking_id, actual_weight, length_cm, width_cm = validate_package(package_record)
