VOLUMETRIC_DIVISOR = 5000.0
HEAVY_FREIGHT_THRESHOLD = 50.0
HEAVY_FREIGHT_ZONE = "heavy freight"
STANDARD_PARCEL_ZONE = "standard parcel"


def computeVolumetricWeight(lengthCm, widthCm):
    return (lengthCm * widthCm) / VOLUMETRIC_DIVISOR


def computeBillableWeight(actualWeight, lengthCm, widthCm):
    volumetricWeight = computeVolumetricWeight(lengthCm, widthCm)
    return max(float(actualWeight), volumetricWeight)


def assignZone(billableWeight):
    if billableWeight > HEAVY_FREIGHT_THRESHOLD:
        return HEAVY_FREIGHT_ZONE
    return STANDARD_PARCEL_ZONE


def validatePackage(packageRecord):
    if len(packageRecord) != 4:
        raise ValueError("each package needs a tracking id, weight, length and width")
    trackingId, actualWeight, lengthCm, widthCm = packageRecord
    if not isinstance(trackingId, int):
        raise ValueError("tracking id must be an integer")
    for measuredValue in (actualWeight, lengthCm, widthCm):
        if measuredValue < 0:
            raise ValueError("weights and dimensions must not be negative")
    return trackingId, actualWeight, lengthCm, widthCm


def route(packages):
    totalBillableWeight = 0.0
    heavyFreightIds = []
    for packageRecord in packages:
        trackingId, actualWeight, lengthCm, widthCm = validatePackage(packageRecord)
        billableWeight = computeBillableWeight(actualWeight, lengthCm, widthCm)
        totalBillableWeight += billableWeight
        if assignZone(billableWeight) == HEAVY_FREIGHT_ZONE:
            heavyFreightIds.append(trackingId)
    return totalBillableWeight, heavyFreightIds


def buildManifestLines(packages):
    manifestLines = []
    for packageRecord in packages:
        trackingId, actualWeight, lengthCm, widthCm = validatePackage(packageRecord)
        volumetricWeight = computeVolumetricWeight(lengthCm, widthCm)
        billableWeight = max(float(actualWeight), volumetricWeight)
        assignedZone = assignZone(billableWeight)
        manifestLines.append(
            "{0:>6}  actual={1:7.2f}  volumetric={2:7.2f}  billable={3:7.2f}  zone={4}".format(
                trackingId, float(actualWeight), volumetricWeight, billableWeight, assignedZone
            )
        )
    return manifestLines


def main():
    packageList = [
        (111, 60, 10, 10),
        (222, 10, 100, 100),
        (333, 5, 900, 400),
        (444, 50, 20, 20),
    ]
