MINIMUM_VISIBILITY_MINUTES = 30
MAXIMUM_POLLUTION_RATING = 8
MAX_TARGETS_PER_NIGHT = 3


def observation_value(visibility_minutes, priority_score, pollution_rating):
    return (visibility_minutes * priority_score) / pollution_rating


def is_observable(visibility_minutes, pollution_rating):
    if visibility_minutes < MINIMUM_VISIBILITY_MINUTES:
        return False
    return pollution_rating <= MAXIMUM_POLLUTION_RATING


def validate_target(target_record):
    if len(target_record) != 4:
        raise ValueError("each target needs 4 fields, got %d" % len(target_record))
    object_id, visibility_minutes, priority_score, pollution_rating = target_record
    if visibility_minutes < 0:
        raise ValueError("negative visibility for object %r" % (object_id,))
    if pollution_rating <= 0:
        raise ValueError("pollution rating must be positive for object %r" % (object_id,))
    return object_id, visibility_minutes, priority_score, pollution_rating


def rank_targets(targets):
    scored_targets = []
    for target_record in targets:
        object_id, visibility_minutes, priority_score, pollution_rating = validate_target(target_record)
        if not is_observable(visibility_minutes, pollution_rating):
            continue
        computed_value = observation_value(visibility_minutes, priority_score, pollution_rating)
        scored_targets.append((object_id, computed_value))
    scored_targets.sort(key=lambda scored_entry: scored_entry[1], reverse=True)
    return scored_targets


def schedule(targets):
    ranked_targets = rank_targets(targets)
    return [object_id for object_id, _value in ranked_targets[:MAX_TARGETS_PER_NIGHT]]


def format_schedule_report(targets):
    ranked_targets = rank_targets(targets)
    rejected_count = len(targets) - len(ranked_targets)
    report_lines = ["Observation plan for tonight:"]
    for slot_number, (object_id, computed_value) in enumerate(ranked_targets[:MAX_TARGETS_PER_NIGHT], start=1):
        report_lines.append("  %d. object %s (value %.2f)" % (slot_number, object_id, computed_value))
    if not ranked_targets:
        report_lines.append("  no target meets the observing constraints")
    waiting_list = ranked_targets[MAX_TARGETS_PER_NIGHT:]
    if waiting_list:
        waiting_ids = ", ".join(str(object_id) for object_id, _value in waiting_list)
        report_lines.append("  backup targets: %s" % waiting_ids)
    report_lines.append("  filtered out: %d target(s)" % rejected_count)
    return "\n".join(report_lines)


