def validate_ingredient(ingredient_record):
    if len(ingredient_record) != 4:
        raise ValueError("each ingredient needs category, grams, protein ratio and fat ratio")
    food_category, gram_weight, protein_per_gram, fat_per_gram = ingredient_record
    if not isinstance(food_category, str) or not food_category:
        raise ValueError("food category must be a non-empty string")
    if gram_weight < 0:
        raise ValueError("gram weight of %s cannot be negative" % food_category)
    for ratio_value in (protein_per_gram, fat_per_gram):
        if ratio_value < 0 or ratio_value > 1:
            raise ValueError("macro ratios of %s must lie between 0 and 1" % food_category)
    return food_category, gram_weight, protein_per_gram, fat_per_gram


def macro_grams(ingredients):
    total_protein_grams = 0.0
    total_fat_grams = 0.0
    for ingredient_record in ingredients:
        _, gram_weight, protein_per_gram, fat_per_gram = validate_ingredient(ingredient_record)
        total_protein_grams += gram_weight * protein_per_gram
        total_fat_grams += gram_weight * fat_per_gram
    return total_protein_grams, total_fat_grams


def nutrition(ingredients):
    total_protein_grams, total_fat_grams = macro_grams(ingredients)
    protein_calories = total_protein_grams * PROTEIN_CALORIES_PER_GRAM
    fat_calories = total_fat_grams * FAT_CALORIES_PER_GRAM
    is_high_fat = fat_calories > protein_calories
    return round(protein_calories + fat_calories, 1), is_high_fat


def heaviest_ingredient(ingredients):
    heaviest_category = None
    max_gram_weight = -1.0
    for ingredient_record in ingredients:
        food_category, gram_weight, _, _ = validate_ingredient(ingredient_record)
        if gram_weight > max_gram_weight:
            max_gram_weight = gram_weight
            heaviest_category = food_category
