def least_frequent_char(input_string_data):
    """
    Finds the character that appears least frequently in a given string.
    If there are multiple, returns the first one encountered.
    """
    character_frequency_map = {}
    for single_input_character in input_string_data:
        character_frequency_map[single_input_character] = character_frequency_map.get(single_input_character, 0) + 1

    minimum_frequency_value = float('inf')
    least_frequent_character_result = ''

    for single_input_character in input_string_data:
        current_character_count = character_frequency_map[single_input_character]
        if current_character_count < minimum_frequency_value:
            minimum_frequency_value = current_character_count
            least_frequent_character_result = single_input_character

    return least_frequent_character_result

