    if not isinstance(year, int) or not isinstance(month, int):
        raise TypeError("year and month must be integers")
    if month < 1 or month > 12:
        raise ValueError("month must be between 1 and 12")
    if year < datetime.MINYEAR or year > datetime.MAXYEAR:
        raise ValueError("year is outside the supported range")


def count_business_days(year, month):
    validateMonthInput(year, month)
    daysInMonth = calendar.monthrange(year, month)[1]
    businessDayCount = 0
    for dayNumber in range(1, daysInMonth + 1):
        currentDate = datetime.date(year, month, dayNumber)
        if currentDate.weekday() < 5:
            businessDayCount += 1
    return businessDayCount


def listBusinessDays(year, month):
    validateMonthInput(year, month)
    daysInMonth = calendar.monthrange(year, month)[1]
    businessDateList = []
    for dayNumber in range(1, daysInMonth + 1):
        currentDate = datetime.date(year, month, dayNumber)
        if currentDate.weekday() < 5:
            businessDateList.append(currentDate)
    return businessDateList


def countBusinessDaysInYear(year):
    monthlyCounts = {}
    for monthNumber in range(1, 13):
        monthlyCounts[monthNumber] = count_business_days(year, monthNumber)
    return monthlyCounts


def formatMonthReport(year, month):
    businessDates = listBusinessDays(year, month)
    monthLabel = calendar.month_name[month]
    totalDays = calendar.monthrange(year, month)[1]
    weekendCount = totalDays - len(businessDates)
    firstBusinessDay = businessDates[0]
    lastBusinessDay = businessDates[-1]
    reportLines = [
        "{} {}".format(monthLabel, year),
        "  total days:     {}".format(totalDays),
        "  business days:  {}".format(len(businessDates)),
        "  weekend days:   {}".format(weekendCount),
        "  first workday:  {}".format(firstBusinessDay.isoformat()),
        "  last workday:   {}".format(lastBusinessDay.isoformat()),
    ]
    return "\n".join(reportLines)


def formatYearSummary(year):
    monthlyCounts = countBusinessDaysInYear(year)
    yearlyTotal = sum(monthlyCounts.values())
    summaryLines = ["Business days per month in {}".format(year)]
    for monthNumber, monthTotal in monthlyCounts.items():
        shortLabel = calendar.month_abbr[monthNumber]
        summaryLines.append("  {:<4} {:>3}".format(shortLabel, monthTotal))
    summaryLines.append("  {:<4} {:>3}".format("all", yearlyTotal))
    return "\n".join(summaryLines)


def main():
    targetYear = 2023
    for targetMonth in (10, 11):
        print(formatMonthReport(targetYear, targetMonth))
        print()
    print(formatYearSummary(targetYear))


if __name__ == "__main__":
    main()
